const QUESTIONS = [
  {"id":"MEC-T1-1","subject":"mecanica","exam":"Tema 1","text":"¿Cómo se clasifican los motores según su modo de trabajo?","options":["De dos y cuatro tiempos","De gasolina y diésel","En línea y en V"],"correct":0,"e":"Por su modo de trabajo (ciclo), los motores se clasifican en dos y cuatro tiempos. Gasolina o diésel es por combustible; en línea o en V, por disposición de los cilindros."},
  {"id":"LOG-T1-1","subject":"logistica","exam":"Tema 1","text":"Una catástrofe que aparece fruto del desarrollo de los procesos industriales y el avance tecnológico, es considerada como:","options":["Catástrofe natural.","Catástrofe tecnológica.","Catástrofe sociológica."],"correct":1,"e":"Las catástrofes tecnológicas son las causadas por la actividad industrial y la tecnología (explosiones, fugas químicas, accidentes nucleares…), a diferencia de las naturales o las sociológicas."},
  {"id":"LOG-T1-2","subject":"logistica","exam":"Tema 1","text":"La fase de emergencia en una catástrofe es:","options":["Fase en la que se aplica el plan de emergencias, se realizan las acciones operativas que implican la clasificación, el socorro y la evacuación de víctimas.","Fase de notificación y alerta a los grupos operativos y al director del plan de los hechos que hagan necesaria la activación del plan de emergencias.","Momento de la catástrofe propiamente dicha."],"correct":0,"e":"En la fase de emergencia se pone en marcha el plan: se clasifica, se socorre y se evacúa a las víctimas. La notificación es la fase de alerta y el momento del suceso es la fase de impacto."},
  {"id":"MEC-T1-2","subject":"mecanica","exam":"Tema 1","text":"¿Cuál es un elemento fijo del motor?","options":["La biela","El pistón","El cigüeñal"],"correct":2,"u":true,"e":"La clave del temario considera el cigüeñal como elemento fijo del motor, frente a biela y pistón. Ojo: en otros manuales el cigüeñal figura entre los elementos móviles."},
  {"id":"MEC-T1-3","subject":"mecanica","exam":"Tema 1","text":"¿Qué elemento pertenece al sistema de distribución?","options":["El cárter","El volante de inercia","El árbol de levas"],"correct":2,"e":"El árbol de levas forma parte de la distribución: abre y cierra las válvulas en el momento justo. El cárter y el volante no pertenecen a ella."},
  {"id":"LOG-T1-3","subject":"logistica","exam":"Tema 1","text":"Dentro de los principios de logística sanitaria se define como «la facilidad de entendimiento de uso y aplicación de técnicas» a:","options":["Flexibilidad.","Sencillez.","Seguridad."],"correct":1,"e":"La sencillez es el principio que pide que las técnicas y el material sean fáciles de entender, usar y aplicar por cualquier interviniente."},
  {"id":"LOG-T1-4","subject":"logistica","exam":"Tema 1","text":"Definimos logística ligera:","options":["Aquella que utiliza medios necesarios de vida y funcionamiento en un lugar durante un tiempo limitado.","Desarrolla pequeñas unidades de asistencia sanitaria o ayuda humanitaria a través de elementos sanitarios básicos.","Ambas son correctas."],"correct":2,"e":"La logística ligera reúne las dos ideas: aporta los medios de vida y funcionamiento durante un tiempo limitado y despliega pequeñas unidades asistenciales con material sanitario básico."},
  {"id":"MEC-T1-4","subject":"mecanica","exam":"Tema 1","text":"¿Cuántas vueltas del cigüeñal requiere un ciclo de cuatro tiempos?","options":["Dos","Una","Cuatro"],"correct":0,"e":"En un motor de cuatro tiempos el ciclo completo necesita dos vueltas de cigüeñal: cada tiempo es media vuelta."},
  {"id":"LOG-T1-5","subject":"logistica","exam":"Tema 1","text":"¿Qué es la logística?","options":["Es el proceso de planificación, implementación y control eficiente y efectivo del flujo y almacenamiento de materias primas, desde su lugar de origen al lugar de consumo.","Todo aquel acontecimiento inesperado que sucede de forma brusca y rápida, que produce importantes daños tanto materiales como humanos.","Es la combinación de peligrosidad, vulnerabilidad y elementos de riesgo."],"correct":0,"e":"La logística es la planificación y el control del flujo y almacenamiento de recursos desde su origen hasta donde se consumen. La opción B define una catástrofe y la C, el riesgo."},
  {"id":"MEC-T1-5","subject":"mecanica","exam":"Tema 1","text":"¿Cuál es el orden del ciclo teórico de cuatro tiempos?","options":["Compresión, admisión, escape y explosión","Admisión, compresión, explosión y escape","Admisión, explosión, compresión y escape"],"correct":1,"e":"El orden del ciclo de cuatro tiempos es admisión, compresión, explosión (expansión) y escape."},
  {"id":"LOG-T1-6","subject":"logistica","exam":"Tema 1","text":"Todos aquellos actos que llevamos a cabo para que no se produzca un desastre o un simple evento no se convierta en este engloban:","options":["El control de la vulnerabilidad.","La prevención de riesgos.","La mitigación de riesgos."],"correct":1,"e":"La prevención de riesgos agrupa todas las acciones que evitan que ocurra un desastre o que un suceso menor llegue a convertirse en uno."},
  {"id":"MEC-T1-6","subject":"mecanica","exam":"Tema 1","text":"¿Qué ocurre con el pistón durante la admisión en el motor de gasolina de cuatro tiempos?","options":["Asciende y expulsa gases","Permanece inmóvil","Desciende y absorbe aire"],"correct":2,"e":"En la admisión el pistón baja y la depresión que crea aspira la mezcla (o el aire) por la válvula de admisión abierta."},
  {"id":"MEC-T1-7","subject":"mecanica","exam":"Tema 1","text":"¿Qué válvula se cierra al comenzar la compresión?","options":["La de admisión","La de escape","La de presión del aceite"],"correct":0,"e":"Al empezar la compresión se cierra la válvula de admisión, de modo que ambas válvulas quedan cerradas mientras el pistón sube."},
  {"id":"LOG-T1-7","subject":"logistica","exam":"Tema 1","text":"Definimos la peligrosidad como:","options":["Susceptibilidad de los sistemas naturales, económicos y sociales al impacto de un peligro de origen natural o inducido por el hombre.","Probabilidad de que ocurra un suceso potencialmente peligroso, durante un cierto periodo de tiempo, en un lugar determinado.","Capacidad de prevención de una población ante un cierto riesgo."],"correct":1,"e":"La peligrosidad es la probabilidad de que ocurra un fenómeno dañino en un lugar y un periodo concretos. La A define la vulnerabilidad."},
  {"id":"LOG-T1-8","subject":"logistica","exam":"Tema 1","text":"Cuando calculamos el riesgo, definimos como factor de pronóstico:","options":["Características que no pueden ser modificadas de una población.","Aquella circunstancia o situación que aumenta las probabilidades de una persona o situación a sufrir un problema.","Afección o característica de una situación que puede usarse para calcular la probabilidad de la recuperación del desastre o de su recurrencia."],"correct":2,"e":"Un factor de pronóstico sirve para estimar la probabilidad de recuperarse de un desastre o de que vuelva a ocurrir. La B describe un factor de riesgo."},
  {"id":"MEC-T1-8","subject":"mecanica","exam":"Tema 1","text":"¿Qué elemento provoca la chispa en el motor de gasolina descrito?","options":["El inyector","La bujía","El calentador"],"correct":1,"e":"En el motor de gasolina la bujía produce la chispa que enciende la mezcla comprimida. En el diésel no hay chispa."},
  {"id":"LOG-T1-9","subject":"logistica","exam":"Tema 1","text":"¿Qué es la medicina de catástrofe?","options":["Es el conjunto de procedimientos organizativos y asistenciales que permiten desarrollar actividades de atención sanitaria urgente sobre el terreno.","Es un pilar fundamental para la atención sanitaria urgente a múltiples víctimas.","Es el patrón oro de la logística."],"correct":0,"e":"La medicina de catástrofe es el conjunto de procedimientos organizativos y asistenciales para prestar atención sanitaria urgente sobre el terreno cuando hay muchas víctimas."},
  {"id":"MEC-T1-9","subject":"mecanica","exam":"Tema 1","text":"¿Qué sucede durante el escape?","options":["El pistón desciende y aspira combustible","Se comprime la mezcla con las válvulas abiertas","El pistón asciende y expulsa los gases quemados"],"correct":2,"e":"En el escape la válvula de escape se abre y el pistón sube empujando fuera los gases quemados."},
  {"id":"LOG-T1-10","subject":"logistica","exam":"Tema 1","text":"En la Conferencia Mundial sobre reducción de desastres naturales se fijan los siguientes objetivos:","options":["Atención a múltiples víctimas en catástrofes.","Crear comunidades capaces de resistir a los desastres y poder lograr la disminución de víctimas.","Evaluación de catástrofes acontecidas hasta el momento con la finalidad de prevención a futuras."],"correct":1,"e":"El objetivo fijado en la Conferencia Mundial fue crear comunidades resilientes, capaces de resistir los desastres y reducir el número de víctimas."},
  {"id":"MEC-T1-10","subject":"mecanica","exam":"Tema 1","text":"¿Qué examina la sonda lambda según el tema?","options":["Los gases sobrantes de la combustión","La presión del aceite","El nivel del refrigerante"],"correct":0,"e":"La sonda lambda analiza el oxígeno de los gases de escape para que la centralita ajuste la mezcla."},
  {"id":"MEC-T1-11","subject":"mecanica","exam":"Tema 1","text":"¿Cuántas explosiones se producen por vuelta del cigüeñal en un motor de dos tiempos?","options":["Dos","Una","Una cada dos vueltas"],"correct":1,"e":"El motor de dos tiempos completa su ciclo en una vuelta de cigüeñal, así que hay una explosión por vuelta."},
  {"id":"LOG-T2-1","subject":"logistica","exam":"Tema 2","text":"¿Cuál no es un objetivo de la cadena de mando?","options":["Que exista una referencia de autoridad única que defina funciones y actuaciones.","Garantiza decisiones ordenadas y consensuadas.","La estabilización del paciente en las mejores condiciones para poder admitir un traslado en las mejores garantías de salud."],"correct":2,"e":"La cadena de mando sirve para que haya una autoridad única y las decisiones sean ordenadas. Estabilizar al paciente para el traslado es un objetivo asistencial, no de mando."},
  {"id":"LOG-T2-2","subject":"logistica","exam":"Tema 2","text":"El puesto sanitario avanzado (PSA) es:","options":["Es un lugar donde se centralizarán las funciones de coordinación de la evacuación.","Se trata de un centro asistencial sanitario que se sitúa en las inmediaciones de una catástrofe.","Se caracteriza por ser una estructura desplegable, a modo de tienda de campaña."],"correct":2,"e":"Según el temario, el PSA se caracteriza por ser una estructura desplegable, como una tienda de campaña, que se monta cerca de la zona de la catástrofe."},
  {"id":"MEC-T1-12","subject":"mecanica","exam":"Tema 1","text":"¿Por dónde entran y salen los gases en el motor de dos tiempos descrito?","options":["Por válvulas accionadas por balancines","Por el tapón del cárter","Por lumbreras"],"correct":2,"e":"El motor de dos tiempos no tiene válvulas: los gases entran y salen por lumbreras (orificios en el cilindro) que el pistón tapa y destapa."},
  {"id":"MEC-T1-13","subject":"mecanica","exam":"Tema 1","text":"En el Sistema de inyección indirecta, el inyector se encuentra en el colector de admisión.","options":["No, siempre inyecta en la cámara de combustión","Depende de la temperatura de funcionamiento","Sí"],"correct":2,"e":"Sí: en la inyección indirecta el inyector pulveriza el combustible en el colector de admisión, antes de la válvula, no dentro del cilindro."},
  {"id":"LOG-T2-3","subject":"logistica","exam":"Tema 2","text":"Las funciones del puesto de mando avanzado (PMA):","options":["Coordinación de las actuaciones de los equipos.","Punto de enlace de la información entre el CECOP y los equipos de intervención.","Ambas son correctas."],"correct":2,"e":"El PMA coordina a los equipos sobre el terreno y a la vez sirve de enlace de información entre ellos y el CECOP, así que las dos son correctas."},
  {"id":"LOG-T2-4","subject":"logistica","exam":"Tema 2","text":"Las zonas de las que se disponen en el lugar de la catástrofe son:","options":["Puesto de carga de ambulancias y áreas de descanso del personal.","Nidos de heridos, área de clasificación, puesto de carga de ambulancias, redil, morgue y áreas de descanso del personal.","Nidos de heridos, área de recuperación, puesto de carga de ambulancias, redil, morgue y áreas de descanso del personal."],"correct":1,"e":"En el lugar de la catástrofe se organizan nidos de heridos, área de clasificación, puesto de carga de ambulancias, redil, morgue y zonas de descanso. No existe un «área de recuperación»."},
  {"id":"MEC-T1-14","subject":"mecanica","exam":"Tema 1","text":"¿Qué proporción de aceite en gasolina indica el tema para lubricar motores de dos tiempos?","options":["Entre el 10 % y el 15 %","Entre el 2 % y el 5 %","Entre el 20 % y el 25 %"],"correct":1,"e":"Los motores de dos tiempos se lubrican mezclando aceite con la gasolina, en una proporción de entre el 2 y el 5%."},
  {"id":"LOG-T2-5","subject":"logistica","exam":"Tema 2","text":"Señala la incorrecta con respecto al Puesto de Carga de Ambulancias (PCAMB):","options":["Se trata de un lugar entre el nido de heridos y el acceso al PSA.","Área a la que llegan los vehículos de transporte sanitario.","La mayoría de los vehículos estarán estacionados en el área base."],"correct":0,"e":"Es incorrecta la A: el PCAMB es la zona a la que llegan los vehículos para cargar a los pacientes, con la mayoría estacionados en el área base. El lugar entre el nido de heridos y el PSA es otro espacio."},
  {"id":"MEC-T1-15","subject":"mecanica","exam":"Tema 1","text":"¿Qué riesgo implica una mezcla con escaso aceite en un motor de dos tiempos?","options":["Aumento de refrigerante","Apertura permanente del termostato","Gripado del motor"],"correct":2,"e":"Con poco aceite en la mezcla, el pistón y el cilindro se rozan en seco y el motor puede griparse."},
  {"id":"LOG-T2-6","subject":"logistica","exam":"Tema 2","text":"¿Qué hace referencia a la característica multifuncionalidad?","options":["Materiales ligeros, que no necesite de medios de transporte complejos.","Los equipos deben estar diseñados para que su manipulación sea sencilla.","Equipos que puedan ser empleados para la realización del mayor número de tareas."],"correct":2,"e":"Multifuncionalidad quiere decir que un mismo equipo sirve para hacer el mayor número posible de tareas."},
  {"id":"MEC-T1-16","subject":"mecanica","exam":"Tema 1","text":"¿Cuál es una ventaja de los motores de dos tiempos citada en el tema?","options":["Construcción más sencilla y ligera","Menor consumo de combustible siempre","Ausencia total de desgaste"],"correct":0,"e":"El motor de dos tiempos tiene menos piezas (no hay válvulas ni distribución), por lo que es más sencillo, ligero y barato."},
  {"id":"MEC-T1-17","subject":"mecanica","exam":"Tema 1","text":"¿Cómo se enciende el combustible en un motor diésel?","options":["Por chispa de una bujía convencional","Por autoinflamación al inyectarse en aire caliente","Por contacto con el líquido refrigerante"],"correct":1,"e":"En el diésel el aire se comprime tanto que se calienta, y el gasóleo se inflama solo al inyectarse en él (autoinflamación)."},
  {"id":"LOG-T2-7","subject":"logistica","exam":"Tema 2","text":"¿Qué espacio es destinado para ubicar a las personas fallecidas en el lugar de la catástrofe?","options":["Morgue.","Redil.","Nido de heridos."],"correct":0,"e":"La morgue es el espacio reservado para los fallecidos. El redil está en el área de socorro y el nido de heridos es donde se agrupan las víctimas al principio."},
  {"id":"LOG-T2-8","subject":"logistica","exam":"Tema 2","text":"¿Qué característica del material empleado facilita el almacenamiento y ubicación en cualquier lugar de la catástrofe?","options":["Equipos alimentados por energías de fácil acceso.","Equipos de reparación sencilla.","Volumen reducido."],"correct":2,"e":"Un volumen reducido permite almacenar y colocar el material en cualquier punto de la zona de catástrofe."},
  {"id":"MEC-T1-18","subject":"mecanica","exam":"Tema 1","text":"¿Qué elemento se menciona para facilitar el funcionamiento diésel en frío?","options":["Los segmentos","Las bujías","Los calentadores"],"correct":2,"e":"Los calentadores precalientan la cámara de combustión para que el diésel arranque con el motor frío."},
  {"id":"LOG-T2-9","subject":"logistica","exam":"Tema 2","text":"¿Qué es el Ambú?","options":["Se trata de una pieza triangular elaborada en materiales plásticos que permiten adaptarse a la cara del paciente.","Es un instrumento que se utiliza para administrar de un modo artificial y manual aire a las vías aéreas.","Son tubos destinados a la extracción de secreciones del árbol traqueobronquial."],"correct":1,"e":"El Ambú (balón autoinflable) sirve para ventilar de forma manual y artificial las vías aéreas del paciente. La A describe una mascarilla y la C, sondas de aspiración."},
  {"id":"MEC-T1-19","subject":"mecanica","exam":"Tema 1","text":"¿Qué ventaja del diésel frente a gasolina destaca el tema?","options":["Menor consumo de combustible","Menor ruido en todos los casos","Reparaciones siempre más baratas"],"correct":0,"e":"La principal ventaja del diésel frente a la gasolina es su menor consumo de combustible."},
  {"id":"MEC-T1-20","subject":"mecanica","exam":"Tema 1","text":"¿Qué inconveniente de los motores diésel se señala?","options":["Necesidad de mezclar aceite con gasóleo al 5 %","Mayor coste de reparaciones y repuestos","Imposibilidad de usar arranque eléctrico"],"correct":1,"e":"Un inconveniente del diésel es que sus reparaciones y repuestos son más caros, porque sus piezas son más robustas y complejas."},
  {"id":"LOG-T2-10","subject":"logistica","exam":"Tema 2","text":"El instrumento de auscultación que se emplea para comprobar una ventilación correcta es:","options":["Fonendoscopio.","Tubo endotraqueal.","Laringoscopio."],"correct":0,"e":"El fonendoscopio permite auscultar ambos campos pulmonares para comprobar que la ventilación es correcta."},
  {"id":"LOG-T2A-1","subject":"logistica","exam":"Tema 2 · Avanzado","text":"¿Cuál no es un material de soporte circulatorio?","options":["Cánulas de acceso venoso periférico.","Vías centrales de acceso periférico.","Lubricante."],"correct":2,"e":"Cánulas y vías sirven para el soporte circulatorio (administrar fluidos y fármacos). El lubricante no forma parte de ese material."},
  {"id":"MEC-T1-21","subject":"mecanica","exam":"Tema 1","text":"¿Qué pieza cierra el motor por su parte superior y lleva el tapón de llenado de aceite?","options":["El cárter","El cigüeñal","La tapa de balancines"],"correct":2,"e":"La tapa de balancines cierra el motor por arriba, protege la distribución y suele llevar el tapón de llenado de aceite."},
  {"id":"LOG-T2A-2","subject":"logistica","exam":"Tema 2 · Avanzado","text":"¿Cuáles son características del sistema de sueros?","options":["Es un dispositivo que cuenta con una goma que accede a la vía periférica o central.","Está conectada a un gotero que contiene un microfiltro para evitar el paso de partículas.","Ambas son correctas."],"correct":2,"e":"El sistema de sueros tiene un tubo que conecta con la vía periférica o central y un gotero con microfiltro que evita el paso de partículas, así que ambas son correctas."},
  {"id":"MEC-T1-22","subject":"mecanica","exam":"Tema 1","text":"¿Cuál es la función de la junta de culata?","options":["Asegurar la estanqueidad entre circuitos y cilindros","Impulsar combustible al inyector","Transformar movimiento alternativo en giro"],"correct":0,"e":"La junta de culata sella la unión entre bloque y culata para que no se mezclen los gases de los cilindros, el aceite y el refrigerante."},
  {"id":"LOG-T2A-3","subject":"logistica","exam":"Tema 2 · Avanzado","text":"¿Qué es un monitor-desfibrilador?","options":["Son equipos que cuentan con una bomba de vacío que permite aspirar todo tipo de secreciones u objetos extraños.","Es un aparato que permite determinar las principales constantes del paciente.","Es un aparato destinado a medir la saturación de oxígeno."],"correct":1,"e":"El monitor-desfibrilador permite medir las principales constantes del paciente y, además, desfibrilar. La A describe un aspirador y la C, un pulsioxímetro."},
  {"id":"MEC-T1-23","subject":"mecanica","exam":"Tema 1","text":"¿Qué indica el tema al desmontar la culata respecto a su junta?","options":["Reutilizarla siempre","Sustituirla por una nueva","Retirarla definitivamente"],"correct":1,"e":"Al desmontar la culata hay que poner siempre una junta nueva, porque la vieja queda aplastada y no volvería a sellar bien."},
  {"id":"MEC-T1-24","subject":"mecanica","exam":"Tema 1","text":"¿Qué función desempeña el bloque motor?","options":["Regular la presión del circuito de combustible","Filtrar el combustible","Soportar los órganos mecánicos del motor"],"correct":2,"e":"El bloque motor es la pieza principal que aloja los cilindros y soporta el resto de órganos mecánicos del motor."},
  {"id":"LOG-T2A-4","subject":"logistica","exam":"Tema 2 · Avanzado","text":"¿Qué instrumento se utiliza para evaluar de un modo continuo los cambios en la función cardíaca?","options":["Electrocardiógrafo.","Pulsioxímetro.","Monitor-desfibrilador."],"correct":0,"e":"El electrocardiógrafo registra la actividad eléctrica del corazón y permite valorar de forma continua los cambios en la función cardíaca."},
  {"id":"LOG-T2A-5","subject":"logistica","exam":"Tema 2 · Avanzado","text":"¿Qué elemento forma parte de la inmovilización?","options":["Collarín cervical.","Férula espinal.","Ambas respuestas son correctas."],"correct":2,"e":"El collarín cervical y la férula espinal son material de inmovilización, así que ambas son correctas."},
  {"id":"MEC-T1-25","subject":"mecanica","exam":"Tema 1","text":"¿Qué elemento une el pistón con el cigüeñal?","options":["La biela","El radiador","El termostato"],"correct":0,"e":"La biela une el pistón con el cigüeñal y transmite la fuerza de uno a otro."},
  {"id":"MEC-T1-26","subject":"mecanica","exam":"Tema 1","text":"¿Qué misión tiene el cigüeñal?","options":["Abrir el paso del refrigerante","Convertir el movimiento lineal en rotatorio","Filtrar los gases de escape"],"correct":1,"e":"El cigüeñal transforma el movimiento lineal (de subida y bajada) de los pistones en movimiento de giro."},
  {"id":"LOG-T2A-6","subject":"logistica","exam":"Tema 2 · Avanzado","text":"¿Para qué se emplea la camilla de nido?","options":["Su principal característica es que una vez colocado al paciente se le pueden realizar diferentes estudios de radiodiagnóstico, sin tener que movilizarlo de nuevo.","Se emplea principalmente en tareas de rescate, fundamentalmente en lugares de difícil acceso, y con dificultades del terreno.","Son muy utilizadas para pequeños traslados, y en pacientes que en principio, no presenten traumatismo cervical o en la columna."],"correct":1,"e":"La camilla de nido se usa sobre todo en rescates en lugares de difícil acceso o terreno complicado. La A describe la camilla de cuchara/radiotransparente."},
  {"id":"LOG-T2A-7","subject":"logistica","exam":"Tema 2 · Avanzado","text":"El redil:","options":["Área a la que llegan los vehículos de transporte sanitario.","Es el espacio situado en el área de socorro.","Lugar entre el nido de heridos y el acceso al PSA."],"correct":1,"e":"El redil es el espacio situado en el área de socorro. La A corresponde al puesto de carga de ambulancias."},
  {"id":"MEC-T1-27","subject":"mecanica","exam":"Tema 1","text":"¿Dónde se aloja habitualmente el aceite de lubricación en el sistema descrito?","options":["En el colector de admisión","En el radiador","En el cárter"],"correct":2,"e":"El aceite se almacena en el cárter, en la parte inferior del motor, desde donde lo aspira la bomba."},
  {"id":"LOG-T2A-8","subject":"logistica","exam":"Tema 2 · Avanzado","text":"¿Qué característica deben tener los contenedores termoformados?","options":["Estancos, ignífugos, impermeables, reflectantes, apilables y transformables.","Resistentes e indeformables, antideslizantes, manejables, de fácil apertura y con asas escamoteables.","Ambas son correctas."],"correct":2,"e":"Los contenedores termoformados deben reunir todas esas características: estancos, ignífugos, resistentes, apilables, manejables y fáciles de abrir."},
  {"id":"MEC-T1-28","subject":"mecanica","exam":"Tema 1","text":"¿Qué evita la película o cuña de aceite lubricante?","options":["El contacto directo metal con metal","La entrada de aire al cilindro","El giro del árbol de levas"],"correct":0,"e":"La película de aceite separa las piezas móviles e impide el contacto directo metal con metal, reduciendo rozamiento y desgaste."},
  {"id":"MEC-T1-29","subject":"mecanica","exam":"Tema 1","text":"¿Qué componente impulsa el aceite por el circuito de lubricación?","options":["La bomba de combustible","La bomba de aceite","El ventilador"],"correct":1,"e":"La bomba de aceite impulsa el lubricante a presión por todo el circuito."},
  {"id":"LOG-T2A-9","subject":"logistica","exam":"Tema 2 · Avanzado","text":"¿Qué información no deben por qué contener las etiquetas de los contenedores?","options":["Logotipo del servicio.","Pegatina de material inflamatorio.","Códigos de letras, números y colores."],"correct":1,"e":"Las etiquetas deben llevar el logotipo del servicio y los códigos de letras, números y colores. Una pegatina de «material inflamatorio» no es obligatoria."},
  {"id":"MEC-T1-30","subject":"mecanica","exam":"Tema 1","text":"¿Qué clasificación de aceites se basa en la viscosidad y la temperatura?","options":["ABS","VIN","SAE"],"correct":2,"e":"La clasificación SAE ordena los aceites según su viscosidad a distintas temperaturas."},
  {"id":"LOG-T2A-10","subject":"logistica","exam":"Tema 2 · Avanzado","text":"¿Cuál no es una función del Sistema de Manejo de Suministros Sanitarios?","options":["Creación de informes sobre suministros recibidos.","Clasificar suministros por prioridades.","Creación de infraestructuras."],"correct":2,"e":"El sistema de manejo de suministros registra, clasifica y prioriza lo que llega. Crear infraestructuras no es una de sus funciones."},
  {"id":"PSI-T1-1","subject":"psico","exam":"Tema 1","text":"Según Cattell, los datos que reflejan el comportamiento en la vida cotidiana son:","options":["Datos Q.","Datos T.","Datos L."],"correct":2,"e":"Cattell distinguía tres fuentes de datos: L (life, la conducta en la vida cotidiana), Q (cuestionarios) y T (tests objetivos)."},
  {"id":"MEC-T1-31","subject":"mecanica","exam":"Tema 1","text":"¿Qué significa la letra W en una designación SAE?","options":["Winter, relacionada con el comportamiento en frío","Water, porcentaje de agua","Wear, nivel de desgaste"],"correct":0,"e":"La W viene de «winter» (invierno) e indica cómo se comporta el aceite en frío."},
  {"id":"LOG-T1-11","subject":"logistica","exam":"Tema 1","text":"Los eventos deportivos, fiestas, romerías, etc., son considerados:","options":["Catástrofes naturales.","Catástrofes tecnológicas.","Catástrofes sociológicas."],"correct":2,"e":"Las concentraciones de personas (eventos deportivos, fiestas, romerías) se clasifican como riesgos o catástrofes sociológicas, porque el peligro nace de la propia aglomeración humana."},
  {"id":"PSI-T1-2","subject":"psico","exam":"Tema 1","text":"La etapa en la que los niños sólo se sirven de sus habilidades de succión y prensión es:","options":["Etapa preoperacional.","Etapa sensoriomotriz.","Etapa de operaciones concretas."],"correct":1,"e":"En la etapa sensoriomotriz de Piaget (0-2 años) el bebé usa sobre todo sus reflejos innatos, como la succión y la prensión, para explorar el mundo."},
  {"id":"MEC-T1-32","subject":"mecanica","exam":"Tema 1","text":"¿Qué caracteriza a un aceite multigrado como SAE 10W40?","options":["Solo se puede usar en verano","Se identifica mediante dos grados SAE","Carece de clasificación de viscosidad"],"correct":1,"e":"Un aceite multigrado lleva dos grados SAE: uno para frío (10W) y otro para caliente (40), así sirve todo el año."},
  {"id":"LOG-T1-12","subject":"logistica","exam":"Tema 1","text":"La fase en la que identificamos una amenaza y nos permite activar las medidas establecidas en un plan para minimizar los efectos en una población es:","options":["Fase de alerta o pre-catástrofe.","Fase de intercatástrofe.","Fase de emergencia."],"correct":0,"e":"La fase de alerta o pre-catástrofe es cuando se detecta la amenaza y se activan las medidas del plan antes de que llegue el impacto."},
  {"id":"LOG-T1-13","subject":"logistica","exam":"Tema 1","text":"Podemos considerar la depresión el efecto directo de una catástrofe:","options":["No, ya que se produce a largo plazo.","Sí, ya que la catástrofe puede afectar al comportamiento psicológico de la población afectada.","Ninguna es correcta."],"correct":1,"e":"Sí: una catástrofe afecta también a la salud mental, y la depresión puede considerarse un efecto directo sobre el comportamiento psicológico de los afectados."},
  {"id":"MEC-T1-33","subject":"mecanica","exam":"Tema 1","text":"¿Qué se recomienda hacer con la junta del filtro nuevo de aceite?","options":["Montarla completamente seca por obligación","Pegarla con adhesivo","Impregnarla con un poco de aceite"],"correct":2,"e":"Se recomienda untar la junta del filtro nuevo con un poco de aceite para que selle bien y luego se pueda desmontar con facilidad."},
  {"id":"PSI-T1-3","subject":"psico","exam":"Tema 1","text":"¿Qué método de defensa añadió Anna Freud a los nueve ya descritos?","options":["Sublimación.","Represión.","Introyección."],"correct":0,"e":"Según el temario, Anna Freud amplió la lista de mecanismos de defensa añadiendo la sublimación, que canaliza impulsos hacia actividades socialmente aceptadas."},
  {"id":"PSI-T1-4","subject":"psico","exam":"Tema 1","text":"Respecto a los cinco estadios de adaptación a la enfermedad, lo siguiente a la ira es:","options":["La negación.","Depresión.","Negociación."],"correct":2,"e":"Las cinco fases de Kübler-Ross son negación, ira, negociación, depresión y aceptación. Después de la ira viene la negociación."},
  {"id":"MEC-T1-34","subject":"mecanica","exam":"Tema 1","text":"¿Qué función principal cumple el sistema de refrigeración?","options":["Eliminar el exceso de calor del motor","Aumentar continuamente la temperatura","Suministrar gasolina a presión"],"correct":0,"e":"La refrigeración elimina el exceso de calor y mantiene el motor a su temperatura de trabajo."},
  {"id":"LOG-T1-14","subject":"logistica","exam":"Tema 1","text":"¿Qué no abarca la logística de grandes desastres?","options":["Alimentación y nutrición.","Higiene.","Gestión de los recursos."],"correct":2,"e":"La logística de grandes desastres se ocupa de necesidades básicas como alimentación, nutrición, agua e higiene. La gestión de recursos es una función general, no uno de estos ámbitos."},
  {"id":"MEC-T1-35","subject":"mecanica","exam":"Tema 1","text":"¿Qué componente hace circular el líquido refrigerante?","options":["El filtro de aceite","La bomba de agua","El volante de inercia"],"correct":1,"e":"La bomba de agua hace circular el refrigerante entre el motor y el radiador."},
  {"id":"PSI-T1-5","subject":"psico","exam":"Tema 1","text":"¿Qué trastorno consiste en la aparición progresiva y permanente de la ansiedad pero sin una causa que la provoque?","options":["Trastorno del pánico.","Trastorno por estrés postraumático.","Trastorno obsesivo compulsivo."],"correct":1,"u":true,"e":"La clave del curso marca el trastorno por estrés postraumático. Ojo: en la clasificación habitual, la ansiedad persistente sin causa concreta corresponde al trastorno de ansiedad generalizada; el TEPT aparece tras un suceso traumático."},
  {"id":"LOG-T1-15","subject":"logistica","exam":"Tema 1","text":"La planificación de acciones para reducir amenazas y riesgos y disminuir la vulnerabilidad, son actividades propias de:","options":["La mitigación de riesgos.","Fase de intercatástrofe.","Preparación de un plan de emergencias."],"correct":0,"e":"La mitigación consiste en planificar acciones que reducen amenazas, riesgos y vulnerabilidad antes de que ocurra el desastre."},
  {"id":"PSI-T1-6","subject":"psico","exam":"Tema 1","text":"La psicología es el estudio científico de:","options":["El comportamiento/conducta.","Los procesos fisiológicos.","Ambas respuestas son correctas."],"correct":0,"e":"La psicología es el estudio científico de la conducta y los procesos mentales. Los procesos fisiológicos los estudia la fisiología."},
  {"id":"MEC-T1-36","subject":"mecanica","exam":"Tema 1","text":"¿Qué regula el termostato?","options":["La cantidad de refrigerante inyectado","La chispa de la bujía","El paso del refrigerante al radiador según la temperatura"],"correct":2,"e":"El termostato es una válvula que deja pasar el refrigerante al radiador solo cuando el motor alcanza su temperatura de trabajo."},
  {"id":"LOG-T1-16","subject":"logistica","exam":"Tema 1","text":"Los objetivos de la medicina de catástrofe son:","options":["La estrategia, táctica y logística.","Identificación y búsqueda de los medios materiales.","Salvar el mayor número posible de vidas, disminuir los efectos y disminuir los costes."],"correct":2,"e":"La medicina de catástrofe persigue salvar el mayor número de vidas, reducir las secuelas y minimizar los costes. Estrategia, táctica y logística son herramientas, no objetivos."},
  {"id":"MEC-T1-37","subject":"mecanica","exam":"Tema 1","text":"¿Qué función cumple el ventilador del sistema de refrigeración?","options":["Crear una corriente de aire a través del radiador","Refrigerar el aceite","Lubricar los cojinetes"],"correct":0,"e":"El ventilador crea una corriente de aire a través del radiador para enfriar el líquido, sobre todo a baja velocidad o parado."},
  {"id":"LOG-T1-17","subject":"logistica","exam":"Tema 1","text":"Los problemas de salud indirectos ocasionados por una catástrofe se abordan en:","options":["Primer periodo asistencial.","Segundo periodo asistencial.","Tercer periodo asistencial."],"correct":1,"e":"El primer periodo atiende a los heridos directos del impacto; el segundo, los problemas de salud indirectos (infecciones, descompensaciones, falta de agua o alimentos)."},
  {"id":"PSI-T1-7","subject":"psico","exam":"Tema 1","text":"La teoría de Freud:","options":["Daba mucha más relevancia al fenómeno inconsciente para explicar los problemas de sus pacientes que a la consciencia.","Daba más importancia a la consciencia que al fenómeno inconsciente.","Solamente daba importancia a la conciencia."],"correct":0,"e":"Freud situaba el origen de los problemas psicológicos en el inconsciente, al que daba mucha más importancia que a la conciencia."},
  {"id":"MEC-T1-38","subject":"mecanica","exam":"Tema 1","text":"¿Para qué se utilizan los orificios tallados en el bloque motor y culata?","options":["Paso de aceite, refrigerante y combustible","Paso de aceite y aire para refrigerar el motor","Paso de aceite, refrigerante y tornillería"],"correct":2,"e":"Según el temario, los orificios del bloque y la culata sirven para el paso de aceite y refrigerante y para la tornillería que los une."},
  {"id":"LOG-T1-18","subject":"logistica","exam":"Tema 1","text":"Entendemos la oportunidad, un principio de la logística sanitaria como:","options":["La facilidad de uso y aplicación de técnicas en el momento adecuado.","Disponer de lo necesario en el momento oportuno y el lugar adecuado.","Multifuncionalidad de algo en un momento concreto."],"correct":1,"e":"El principio de oportunidad significa tener lo necesario en el momento oportuno y en el lugar adecuado."},
  {"id":"PSI-T1-8","subject":"psico","exam":"Tema 1","text":"¿Cuál NO es una característica de los rasgos de personalidad?","options":["Son patrones de conducta.","Son relativamente duraderos y estables en el tiempo.","Son inestables y cambian con gran facilidad."],"correct":2,"e":"Los rasgos de personalidad son patrones de conducta relativamente estables y duraderos. Precisamente por eso no cambian con facilidad."},
  {"id":"LOG-T1-19","subject":"logistica","exam":"Tema 1","text":"Qué no es una función del puesto de mando avanzado (PMA):","options":["Asesoramiento técnico sobre riesgos específicos.","Control cronológico de intervenciones y eventos.","Facilitar la evacuación controlada a centros hospitalarios."],"correct":2,"e":"El PMA coordina, asesora y registra las intervenciones. La evacuación a los hospitales la organizan el puesto de carga de ambulancias y el centro coordinador."},
  {"id":"PSI-T1-9","subject":"psico","exam":"Tema 1","text":"Un modo que tiene la psicología para resumir la personalidad de un individuo es utilizando vocablos como: amigable, agresivo, coqueta y miedoso. En términos psicológicos, estas palabras se refieren a:","options":["Los rasgos.","Los patrones.","Las habilidades."],"correct":0,"e":"Palabras como amigable, agresivo o miedoso describen rasgos: tendencias estables de comportamiento de una persona."},
  {"id":"MEC-T1-39","subject":"mecanica","exam":"Tema 1","text":"¿Qué función tiene el filtro de combustible?","options":["Elevar la temperatura del aceite","Controlar el movimiento de las válvulas","Retener suciedad y humedad presentes en el combustible"],"correct":2,"e":"El filtro de combustible retiene la suciedad y la humedad para proteger la bomba y los inyectores."},
  {"id":"PSI-T1-10","subject":"psico","exam":"Tema 1","text":"Según Gordon Allport, para entender la personalidad se debe tener en cuenta:","options":["Los mecanismos de desarrollo de la personalidad: diferenciación, integración, maduración, imitación, aprendizaje, autonomía funcional y extensión del self.","El propium o self: la imagen que uno se hace de sí mismo a lo largo de su desarrollo.","Ambas respuestas son correctas."],"correct":2,"e":"Allport tenía en cuenta tanto los mecanismos de desarrollo de la personalidad como el propium o self (la imagen de uno mismo), así que ambas son correctas."},
  {"id":"LOG-T1-20","subject":"logistica","exam":"Tema 1","text":"El momento en que se produce la catástrofe propiamente dicha se denomina:","options":["Fase de impacto.","Fase de alerta.","Fase de emergencia."],"correct":0,"e":"La fase de impacto es el momento en que se produce la catástrofe propiamente dicha. Antes está la alerta y después la emergencia."},
  {"id":"MEC-T1-40","subject":"mecanica","exam":"Tema 1","text":"En el Sistema de inyección indirecta, la inyección se realiza en la cámara de combustión.","options":["Verdadero","Falso","Depende de la temperatura de funcionamiento del motor"],"correct":1,"e":"Falso: en la inyección indirecta el combustible se inyecta en el colector de admisión. La inyección en la cámara de combustión es la directa."},
  {"id":"PSI-T1-11","subject":"psico","exam":"Tema 1","text":"¿Cuál no es un rasgo de la teoría de los cinco factores de la personalidad?","options":["La extraversión.","La introversión.","La afabilidad."],"correct":1,"e":"Los cinco factores son apertura, responsabilidad, extraversión, amabilidad (afabilidad) y neuroticismo. La introversión es solo el polo bajo de la extraversión, no un factor propio."},
  {"id":"LOG-T3-1","subject":"logistica","exam":"Tema 3","text":"Las necesidades calóricas por persona y día se establecen en:","options":["2.500 Kcal.","2.100 Kcal.","1.800 Kcal."],"correct":1,"e":"Las necesidades energéticas mínimas de referencia en emergencias son de unas 2.100 kcal por persona y día."},
  {"id":"LOG-T3-2","subject":"logistica","exam":"Tema 3","text":"Todas las raciones deben incluir:","options":["Proteínas, glúcidos o hidratos de carbono, lípidos o grasas, minerales y vitaminas.","Proteínas, glúcidos o hidratos de carbono, aminoácidos, minerales y vitaminas.","Proteínas, glúcidos o hidratos de carbono, aminoácidos, lípidos o grasas y vitaminas."],"correct":0,"e":"Toda ración debe incluir los cinco grupos de nutrientes: proteínas, hidratos de carbono, grasas, minerales y vitaminas. Los aminoácidos forman parte de las proteínas."},
  {"id":"PSI-T1-12","subject":"psico","exam":"Tema 1","text":"Según la teoría de los 5 factores, el neuroticismo:","options":["Evalúa la cantidad y la intensidad de la interacción entre sujetos, el grado de actividad, la necesidad de estímulos y la capacidad de disfrutar.","Identifica a los sujetos vulnerables a sufrimiento psicológico, ideas no realistas, caprichos o urgencias excesivas y respuestas de afrontamiento no adaptativas.","Evalúa la búsqueda y la valoración de la experiencia de uno mismo, además de la tolerancia y la investigación de lo desconocido."],"correct":1,"e":"El neuroticismo mide la inestabilidad emocional: vulnerabilidad al malestar, ideas poco realistas y afrontamiento poco adaptativo. La A describe la extraversión y la C, la apertura."},
  {"id":"LOG-T3-3","subject":"logistica","exam":"Tema 3","text":"Una de las causas que da lugar a situaciones de emergencia son las causas naturales las cuales pueden ser:","options":["Terremotos.","Inundaciones.","Ambas son correctas."],"correct":2,"e":"Terremotos e inundaciones son ejemplos de causas naturales de emergencia, así que ambas son correctas."},
  {"id":"PSI-T1-13","subject":"psico","exam":"Tema 1","text":"Según Cattell hay tres tipos de rasgos de personalidad, ¿cuál no es uno de ellos?","options":["Rasgos actitudinales.","Rasgos dinámicos.","Rasgos estáticos."],"correct":2,"e":"Según el temario, Cattell hablaba de rasgos actitudinales, dinámicos y de temperamento. Los «rasgos estáticos» no forman parte de su clasificación."},
  {"id":"PSI-T1-14","subject":"psico","exam":"Tema 1","text":"Dentro de la etapa del desarrollo prenatal, la etapa fetal comienza:","options":["A los 2 meses.","A los 3 meses.","A los 4 meses."],"correct":1,"e":"El periodo prenatal se divide en germinal, embrionario y fetal. La etapa fetal empieza hacia el tercer mes de gestación."},
  {"id":"LOG-T3-4","subject":"logistica","exam":"Tema 3","text":"El 17% del total de las calorías que debe consumir una persona corresponde a:","options":["Grasas.","Proteínas.","Micronutrientes esenciales."],"correct":0,"e":"Alrededor del 17% de las calorías diarias debe proceder de las grasas."},
  {"id":"LOG-T3-5","subject":"logistica","exam":"Tema 3","text":"El objetivo fundamental de todos los equipos de intervención ha de ser:","options":["Que no haya necesidad de alimentos en cada una de las comidas diaria.","Que solo se administren alimentos a grupos de riesgo.","Que a todas las personas damnificadas se les provea de todo lo necesario para atender a las necesidades más básicas."],"correct":2,"e":"El objetivo es que todas las personas damnificadas tengan cubiertas sus necesidades básicas, no solo los grupos de riesgo."},
  {"id":"PSI-T1-15","subject":"psico","exam":"Tema 1","text":"¿Qué mecanismo de defensa consiste en rechazar fuera de la conciencia todo aquello que resulta penoso?","options":["Regresión.","Represión.","Anulación."],"correct":1,"e":"La represión expulsa de la conciencia los pensamientos o recuerdos dolorosos. La regresión es volver a conductas infantiles."},
  {"id":"PSI-T1-16","subject":"psico","exam":"Tema 1","text":"El representante de la teoría psicoanalítica es:","options":["Eysenck.","Cattell.","Freud."],"correct":2,"e":"Sigmund Freud es el creador del psicoanálisis. Eysenck y Cattell son autores de teorías de rasgos."},
  {"id":"LOG-T3-6","subject":"logistica","exam":"Tema 3","text":"En el restablecimiento de abastecimiento de víveres se debe considerar:","options":["La posibilidad de conflictos violentos a la hora del reparto.","La implicación de las comunidades locales en las tareas de control y planificación de la distribución.","Ambas son correctas."],"correct":2,"e":"Al restablecer el abastecimiento hay que prever posibles conflictos en el reparto e implicar a la comunidad local en el control y la distribución."},
  {"id":"PSI-T1-17","subject":"psico","exam":"Tema 1","text":"Freud construyó unos conceptos teóricos que interactuaban entre sí, estos son:","options":["El ello y el yo.","El ello, el yo y el super-yo.","El ello y el super-yo."],"correct":1,"e":"Freud describió tres instancias de la personalidad: el ello (impulsos), el yo (realidad) y el superyó (normas morales)."},
  {"id":"LOG-T3-7","subject":"logistica","exam":"Tema 3","text":"¿Cuál no es un indicador clave del proyecto esfera?","options":["El uso medio de agua se establece en 15 litros por persona y día.","El tiempo de espera establecido para obtener el agua no debe superar los 15 minutos.","El grado de turbidez no debe superar nunca las 5 NTU (unidades turbidimétricas)."],"correct":2,"e":"Según el temario, son indicadores de Esfera los 15 litros por persona y día y la espera máxima para obtener agua. La turbidez de 5 NTU no figura como indicador clave."},
  {"id":"PSI-T1-18","subject":"psico","exam":"Tema 1","text":"¿Hasta qué siglo formó la psicología parte de la filosofía?","options":["Hasta el siglo XVIII.","Hasta el siglo XIX.","Nunca ha formado parte de la filosofía."],"correct":1,"e":"La psicología se separó de la filosofía en el siglo XIX, cuando Wundt fundó el primer laboratorio de psicología experimental (1879)."},
  {"id":"LOG-T3-8","subject":"logistica","exam":"Tema 3","text":"Las proteínas se han de incluir en una ración normal en un:","options":["10%.","20%.","15%."],"correct":0,"e":"Según el temario, las proteínas deben aportar en torno al 10% de la energía de una ración normal."},
  {"id":"PSI-T1-19","subject":"psico","exam":"Tema 1","text":"En el periodo sensoriomotriz, los niños:","options":["Comienzan aplicando simplemente las habilidades con que nacen, sobre todo succión y prensión, a una gran variedad de actividades.","Es una etapa de interacción con el entorno.","Ambas respuestas son correctas."],"correct":2,"e":"En la etapa sensoriomotriz el niño parte de sus habilidades innatas (succión, prensión) y aprende interactuando con el entorno, así que ambas son correctas."},
  {"id":"LOG-T3-9","subject":"logistica","exam":"Tema 3","text":"Los sistemas utilizados para la distribución de agua son:","options":["Sistemas de distribución aislados, sistemas regulares y sistemas radiales.","Sistemas de distribución aislados y sistemas lineales.","Sistemas de distribución aislados, sistemas lineales y sistemas radiales."],"correct":2,"e":"El agua se distribuye mediante sistemas aislados, lineales y radiales."},
  {"id":"LOG-T3-10","subject":"logistica","exam":"Tema 3","text":"Toda la metodología empleada para la potabilización del agua va dirigida a obtener un agua:","options":["Libre de microorganismos patógenos.","Exenta de productos tóxicos.","Ambas son correctas."],"correct":2,"e":"Potabilizar el agua busca que esté libre de microorganismos patógenos y también de sustancias tóxicas."},
  {"id":"PSI-T1-20","subject":"psico","exam":"Tema 1","text":"Reconoce el tipo de mecanismo de defensa que aparece en este caso: «Tras la vivencia de un accidente de tráfico en el cual María pierde a su marido, vuelve a dejar encendida todas las noches la luz de su habitación para poder conciliar el sueño como hacía cuando era pequeña».","options":["Represión.","Regresión.","Proyección."],"correct":1,"e":"Es una regresión: ante el trauma, María vuelve a una conducta propia de su infancia (dormir con la luz encendida)."},
  {"id":"LOG-T3-11","subject":"logistica","exam":"Tema 3","text":"¿En qué consiste el desbaste?","options":["Realizar un pretratamiento al agua tras ser obtenida de la fuente de abastecimiento.","Dotar al agua de una serie de características adecuadas a un agua de calidad.","Es una técnica que permite detectar la presencia de sólidos disueltos en la suspensión."],"correct":0,"e":"El desbaste es el pretratamiento del agua recién captada: se retiran los sólidos gruesos antes del resto del proceso."},
  {"id":"PSI-T1-21","subject":"psico","exam":"Tema 1","text":"Si ves a una persona que realiza conductas rituales absurdas, podrías pensar que...","options":["Padece un trastorno del pánico.","Padece un trastorno de ansiedad por separación.","Padece un trastorno obsesivo compulsivo."],"correct":2,"e":"Las conductas rituales repetitivas que la persona siente que debe hacer son típicas del trastorno obsesivo-compulsivo."},
  {"id":"PSI-T1-22","subject":"psico","exam":"Tema 1","text":"En los tipos de escucha, ¿en cuál hay una atención completa por parte del receptor?","options":["Escucha activa.","Escucha ignorada.","Escucha empática."],"correct":0,"e":"En la escucha activa el receptor presta atención completa, verbal y no verbal, a lo que dice el emisor."},
  {"id":"LOG-T3-12","subject":"logistica","exam":"Tema 3","text":"Entre los métodos que se utilizan para la clarificación, ¿cuál es el que consiste en añadir a la solución de aguas y partículas una serie de sustancias que tienen la capacidad de retener las partículas en suspensión?","options":["Decantación.","Coagulación o Floculación.","Filtración."],"correct":1,"e":"En la coagulación-floculación se añaden sustancias que atrapan las partículas en suspensión para que formen flóculos y se separen."},
  {"id":"LOG-T3-13","subject":"logistica","exam":"Tema 3","text":"Las técnicas de análisis del agua son:","options":["La turbidimetría, determinación de cloro residual y análisis bacteriológico.","La determinación de cloro residual y el análisis bacteriológico.","La turbidimetría y el análisis bacteriológico."],"correct":0,"e":"El agua se analiza con tres técnicas: turbidimetría, determinación del cloro residual y análisis bacteriológico."},
  {"id":"PSI-T2-1","subject":"psico","exam":"Tema 2","text":"Para prestar un buen apoyo psicológico, el profesional sanitario debe:","options":["Imponer respeto.","Conocer los protocolos de actuación.","Llevar al menos 2 años en la profesión."],"correct":1,"e":"Para dar un buen apoyo psicológico hay que conocer los protocolos de actuación. Imponer respeto o tener antigüedad no garantizan una buena intervención."},
  {"id":"LOG-T3-14","subject":"logistica","exam":"Tema 3","text":"¿Cuál no es un producto perecedero?","options":["Un filete de ternera.","Una trucha.","Arroz."],"correct":2,"e":"El arroz es un alimento no perecedero porque se conserva mucho tiempo en seco. La carne y el pescado son perecederos."},
  {"id":"PSI-T2-2","subject":"psico","exam":"Tema 2","text":"El periodo en el que se empieza a llevar a cabo una valoración y clasificación de los daños sufridos es:","options":["El periodo de crisis.","El periodo post-crítico.","El periodo de rehabilitación."],"correct":1,"e":"En el periodo post-crítico, pasado lo peor, se empiezan a valorar y clasificar los daños sufridos."},
  {"id":"PSI-T2-3","subject":"psico","exam":"Tema 2","text":"Una de las reacciones emocionales de la sociedad durante el periodo pre-crítico es:","options":["Shock.","Sentimiento de culpa.","Miedo o pánico."],"correct":2,"e":"En el periodo pre-crítico, ante la amenaza, la reacción emocional típica de la población es el miedo o el pánico. El shock y la culpa aparecen después del impacto."},
  {"id":"LOG-T3-15","subject":"logistica","exam":"Tema 3","text":"Las condiciones en las que deben estar los productos perecederos son:","options":["Un estricto control higiénico y sanitario.","El establecimiento de un flujo de desechos.","Ambas son correctas."],"correct":2,"e":"Los productos perecederos requieren un estricto control higiénico-sanitario y un circuito para retirar sus desechos."},
  {"id":"LOG-T3-16","subject":"logistica","exam":"Tema 3","text":"¿Dónde debe realizarse la eliminación de residuos?","options":["En un lugar en el centro de la población.","En lugares donde no puedan generar problemas secundarios.","Ninguna es correcta."],"correct":1,"e":"Los residuos deben eliminarse en lugares alejados donde no causen problemas secundarios de salud o de plagas."},
  {"id":"PSI-T2-4","subject":"psico","exam":"Tema 2","text":"Tranquilizar y orientar emocionalmente a los afectados que se encuentran perdidos o desorientados corresponde a la fase:","options":["De estabilización.","De seguridad y confort.","De asistencia práctica."],"correct":0,"e":"La fase de estabilización busca tranquilizar y orientar emocionalmente a quienes están desbordados o desorientados."},
  {"id":"PSI-T2-5","subject":"psico","exam":"Tema 2","text":"Los pacientes potencialmente violentos requieren medidas para desactivar la situación, ¿cuál de las siguientes es una de esas medidas?","options":["Dar al paciente objetos con los que se pueda herir.","Responder de una manera despiadada.","Expresar una preocupación simpática."],"correct":2,"e":"Mostrar una preocupación comprensiva ayuda a desactivar a un paciente agresivo. Nunca se le deben dar objetos peligrosos ni responder con dureza."},
  {"id":"LOG-T3-17","subject":"logistica","exam":"Tema 3","text":"¿Qué es el enterramiento?","options":["Es el método apropiado para utilizar en el caso de pequeñas poblaciones.","Se trata de eliminar mediante su quema aquellos residuos combustibles.","Se trata de lugares destinados a disponer los residuos, estos se van compactando de manera que los productos se vayan descomponiendo."],"correct":0,"e":"El enterramiento es el método adecuado para eliminar residuos en poblaciones pequeñas. La B describe la incineración."},
  {"id":"PSI-T2-6","subject":"psico","exam":"Tema 2","text":"En cuanto a las características del apoyo psicológico:","options":["Se encarga de atender los aspectos emocionales y psicosociales de la persona que lo requiera.","Intenta aumentar las secuelas favoreciendo una larga recuperación.","Ambas respuestas son correctas."],"correct":0,"e":"El apoyo psicológico atiende los aspectos emocionales y psicosociales de la persona para reducir secuelas y facilitar la recuperación, no al revés."},
  {"id":"LOG-T3-18","subject":"logistica","exam":"Tema 3","text":"¿Qué se puede depositar en los contenedores del GRUPO III?","options":["Medicamentos caducados.","Residuos de jardinería.","Agujas y material punzante y cortante."],"correct":2,"e":"Los contenedores del grupo III (residuos sanitarios específicos) recogen, entre otros, agujas y material punzante y cortante."},
  {"id":"LOG-T3-19","subject":"logistica","exam":"Tema 3","text":"¿Qué es la desratización?","options":["Proceso físico o químico que mata o inactiva agentes patógenos.","Eliminación de ratas y ratones.","Eliminación de insectos y arácnidos."],"correct":1,"e":"Desratizar es eliminar ratas y ratones. La A es la desinfección y la C, la desinsectación."},
  {"id":"PSI-T2-7","subject":"psico","exam":"Tema 2","text":"¿Qué cualidad NO es apta para prestar un buen apoyo psicológico?","options":["Dominio propio y de la situación.","Autocontrol.","Bloqueo emocional."],"correct":2,"e":"El bloqueo emocional impide ayudar. Para dar apoyo hacen falta autocontrol y dominio de uno mismo y de la situación."},
  {"id":"PSI-T2-8","subject":"psico","exam":"Tema 2","text":"El rol del paciente actualmente:","options":["Ha pasado de un rol pasivo a un rol activo.","Ha pasado de un rol activo a un rol pasivo.","No tiene un papel importante en la sanidad."],"correct":0,"e":"El paciente ha pasado de un papel pasivo a uno activo: participa en las decisiones sobre su salud."},
  {"id":"LOG-T3-20","subject":"logistica","exam":"Tema 3","text":"¿Cuál es el factor que determina la aparición de enfermedades?","options":["Países en desarrollo.","Pérdida de los servicios públicos.","Ambas son correctas."],"correct":2,"e":"Tanto la situación de país en desarrollo como la pérdida de servicios públicos favorecen la aparición de enfermedades tras una catástrofe."},
  {"id":"PSI-T2-9","subject":"psico","exam":"Tema 2","text":"Juan es técnico en emergencias sanitarias, son las 23:00 horas y reciben un aviso de un accidente de tráfico bastante grave. En ese momento, Juan se pone en acción, activa todos sus recursos tanto físicos como mentales para hacer frente a la emergencia y se dirige con su equipo al punto del accidente en el menor tiempo posible. ¿Qué tipo de estrés se da en este caso?","options":["Eustrés o estrés positivo.","Distrés o estrés negativo.","Ninguna respuesta es correcta."],"correct":0,"e":"Es eustrés o estrés positivo: Juan activa sus recursos físicos y mentales para responder bien a la emergencia."},
  {"id":"PSI-T2-10","subject":"psico","exam":"Tema 2","text":"¿Qué tipo de estresores son los estímulos externos que influyen sobre el organismo como, por ejemplo, la temperatura extrema?","options":["Estresores biológicos.","Estresores físicos.","Estresores sociales."],"correct":1,"e":"Los estresores físicos son estímulos del ambiente como el frío o el calor extremos, el ruido o la luz."},
  {"id":"PSI-T2-11","subject":"psico","exam":"Tema 2","text":"El periodo precrítico se caracteriza por:","options":["Un elevado grado de tensión.","Un bajo grado de tensión.","Depende de la situación."],"correct":0,"e":"El periodo pre-crítico, ante una amenaza inminente, se caracteriza por un grado elevado de tensión."},
  {"id":"PSI-T2-12","subject":"psico","exam":"Tema 2","text":"Cuando una población recibe una alerta de situación de emergencia, puede reaccionar de maneras diferentes:","options":["Con una actitud positiva de colaboración, vigilancia y autodefensa.","Con una actitud de negación, «eso no puede pasarme a mí».","Ambas respuestas son correctas."],"correct":2,"e":"Ante una alerta la población puede reaccionar colaborando y protegiéndose o negando el peligro, así que ambas son correctas."},
  {"id":"PSI-T2-13","subject":"psico","exam":"Tema 2","text":"Durante la puesta en práctica de los primeros auxilios psicológicos, NO debemos:","options":["Presentarnos y demostrar calma en todo momento.","Centrarnos en nosotros y contar historias personales.","Promover un contexto de seguridad y protección."],"correct":1,"e":"En los primeros auxilios psicológicos la atención debe centrarse en la persona afectada. Hablar de uno mismo o contar historias personales está desaconsejado."},
  {"id":"PSI-T2-14","subject":"psico","exam":"Tema 2","text":"¿Qué es el control decisional o emocional?","options":["Se refiere a la capacidad de elegir entre los distintos tipos de comportamientos el más adecuado para afrontar las situaciones difíciles y de crisis.","Es la capacidad para controlar los factores ambientales y las características del entorno.","Este tipo de control conlleva una tarea de interpretación y evaluación de las situaciones ambientales para lograr controlar los aspectos negativos de dicha situación y que no interfieran en nuestros pensamientos y decisiones."],"correct":0,"e":"El control decisional es la capacidad de elegir el comportamiento más adecuado para afrontar una situación difícil o de crisis."},
  {"id":"PSI-T2-15","subject":"psico","exam":"Tema 2","text":"Para controlar y reducir la ansiedad podemos:","options":["Explicarle con las palabras más sencillas y adecuadas al tipo de persona que las emociones y respuestas que está experimentando son normales.","Cuando prevenimos a los sujetos de que esas reacciones y sintomatología son normales le evitamos tener una doble preocupación.","Ambas respuestas son correctas."],"correct":2,"e":"Explicar con palabras sencillas que sus reacciones son normales tranquiliza a la persona y le evita preocuparse además por sus síntomas, así que ambas son correctas."},
  {"id":"PSI-T2-16","subject":"psico","exam":"Tema 2","text":"Dentro de los estresores psicológicos, ¿qué es la amenaza?","options":["Hace referencia a un hecho psicológico que ya ha tenido lugar, como por ejemplo, una muerte.","Es la anticipación de un daño que puede ocurrir, pero aún no se ha producido.","Situaciones en las que el individuo se enfrenta a situaciones difíciles, pero confía en sus capacidades para resolverlas y tiene recursos de afrontamiento."],"correct":1,"e":"La amenaza es la anticipación de un daño que todavía no ha ocurrido. La A describe una pérdida y la C, un desafío."},
  {"id":"PSI-T2-17","subject":"psico","exam":"Tema 2","text":"¿Cuál es considerada la fase de alerta?","options":["El periodo precrítico.","El periodo de crisis.","El periodo de reacción."],"correct":0,"e":"El periodo pre-crítico es la fase de alerta, cuando se conoce la amenaza antes del impacto."},
  {"id":"PSI-T2-18","subject":"psico","exam":"Tema 2","text":"El periodo de crisis:","options":["Es bastante grave.","Es bastante predecible.","Ambas respuestas son correctas."],"correct":0,"e":"El periodo de crisis es grave e imprevisible, por eso solo es correcta la A."},
  {"id":"PSI-T2-19","subject":"psico","exam":"Tema 2","text":"En el periodo de reacción, el estrés se manifiesta en:","options":["Orientación espacio-temporal.","Búsqueda de apoyo y socorro e intentos de tomar conciencia de lo sucedido.","Capacidad de decisión."],"correct":1,"e":"En el periodo de reacción las personas buscan ayuda y socorro e intentan tomar conciencia de lo ocurrido."},
  {"id":"PSI-T2-20","subject":"psico","exam":"Tema 2","text":"¿En qué fase se produce el retorno a la lucidez y estructuración social, disminuyendo la agitación, el pánico y la ansiedad?","options":["En el periodo de crisis.","En el periodo de restauración.","En el periodo de rehabilitación."],"correct":2,"e":"En el periodo de rehabilitación se recupera la lucidez y la organización social, y disminuyen la agitación, el pánico y la ansiedad."},
  {"id":"PSI-T2-21","subject":"psico","exam":"Tema 2","text":"Los primeros auxilios psicológicos son una ayuda:","options":["Extensa y duradera en el tiempo.","Breve y puntual.","Ninguna respuesta es correcta."],"correct":1,"e":"Los primeros auxilios psicológicos son una ayuda breve y puntual en el momento de la crisis, no un tratamiento prolongado."},
  {"id":"PSI-T2-22","subject":"psico","exam":"Tema 2","text":"El objetivo principal de la fase de contacto y encuentro es:","options":["La escucha y el apoyo.","Tranquilizar y orientar.","Recopilar información."],"correct":0,"e":"La fase de contacto y encuentro busca escuchar y ofrecer apoyo, estableciendo una relación de confianza con el afectado."},
  {"id":"PSI-T2-23","subject":"psico","exam":"Tema 2","text":"¿Cuál es el tercer paso de los primeros auxilios psicológicos?","options":["Contacto.","Estabilización.","Información."],"correct":1,"e":"El orden de los primeros auxilios psicológicos es contacto, seguridad y confort, y en tercer lugar estabilización."},
  {"id":"ANA-T1-1","subject":"anato","exam":"Tema 1","text":"La Anatomía es la ciencia:","options":["Que se ocupa del estudio de las funciones orgánicas de los seres orgánicos.","Comprende las distintas partes que componen el cuerpo humano, los principios arquitecturales junto con los mecanismos que presiden su desarrollo, estudia las relaciones entre sus partes y describe su estructura, necesaria para explicar los mecanismos de su función.","Es una de las condiciones que estudian y controlan los procesos fisiológicos humanos para describir y explicar las condiciones estáticas o constantes del medio interno."],"correct":1,"e":"La anatomía estudia la estructura del cuerpo: sus partes, cómo se organizan y se relacionan. El estudio de las funciones (opción A) es la fisiología."},
  {"id":"ANA-T1-2","subject":"anato","exam":"Tema 1","text":"El nivel celular es:","options":["El primer nivel biótico, es decir, el elemento de menor tamaño que puede considerarse vivo.","Un conjunto de células especializadas con una misma función y origen.","Un conjunto de órganos semejantes que realizan una función y que están formados por un mismo tipo de tejido."],"correct":0,"e":"La célula es el primer nivel biótico: la unidad más pequeña que se considera viva. Un conjunto de células con la misma función es un tejido."},
  {"id":"ANA-T1-3","subject":"anato","exam":"Tema 1","text":"La Teoría Celular establece que:","options":["Todos los seres vivos están formados por células.","La célula es capaz de realizar todos los procesos metabólicos necesarios para permanecer con vida.","Ambas respuestas son correctas."],"correct":2,"e":"La teoría celular dice que todos los seres vivos están formados por células y que la célula realiza todos los procesos necesarios para vivir, así que ambas son correctas."},
  {"id":"ANA-T1-4","subject":"anato","exam":"Tema 1","text":"Las partes fundamentales que componen la estructura celular son:","options":["Membrana celular, citoplasma y núcleo.","Aparato de Golgi, ribosomas y lisosomas.","Nucléolo y cromatina."],"correct":0,"e":"Toda célula eucariota tiene tres partes básicas: membrana, citoplasma y núcleo. Golgi, ribosomas y lisosomas son orgánulos del citoplasma."},
  {"id":"ANA-T1-5","subject":"anato","exam":"Tema 1","text":"La función de respiración celular se lleva a cabo en:","options":["En el núcleo.","En el retículo endoplasmático.","Las mitocondrias."],"correct":2,"e":"La respiración celular, que obtiene energía (ATP) a partir de los nutrientes, se produce en las mitocondrias."},
  {"id":"ANA-T1-6","subject":"anato","exam":"Tema 1","text":"El tejido conjuntivo:","options":["Cubre superficies del organismo, recubre órganos huecos, cavidades, conductos y forma glándulas.","Protege y sostiene el organismo y sus órganos, los mantiene unidos, almacena reserva de energía en forma de grasa y proporciona inmunidad.","Inicia y transmite los potenciales de acción que ayudan a coordinar las actividades."],"correct":1,"e":"El tejido conjuntivo sostiene y une los órganos, almacena grasa y participa en la defensa. La A describe el epitelial y la C, el nervioso."},
  {"id":"ANA-T1-7","subject":"anato","exam":"Tema 1","text":"El tejido que constituye el corazón es de tipo:","options":["Muscular.","Epitelial.","Nervioso."],"correct":0,"e":"El corazón está formado por tejido muscular cardíaco (miocardio), que es estriado y de contracción involuntaria."},
  {"id":"ANA-T1-8","subject":"anato","exam":"Tema 1","text":"La epidermis:","options":["Es la capa de la piel más interna y gruesa constituida por tejido conjuntivo.","Contiene glándulas sebáceas productoras de grasa que impermeabilizan la piel.","Es la capa de la piel más externa constituida por varias capas de células epiteliales que producen queratina."],"correct":2,"e":"La epidermis es la capa más externa de la piel, formada por varias capas de células epiteliales que producen queratina. La A describe la dermis."},
  {"id":"ANA-T1-9","subject":"anato","exam":"Tema 1","text":"La función principal del aparato respiratorio es:","options":["Llevar a todas las células del organismo lo necesario para que puedan ejercer sus funciones.","Conducir el oxígeno hasta el interior de los pulmones, donde tiene lugar el intercambio entre oxígeno y dióxido de carbono; y de vuelta, conducir el dióxido de carbono para que sea eliminado al exterior.","Descomponer el alimento en pequeñas moléculas capaces de atravesar la pared intestinal y pasar a la sangre y al hígado, donde son metabolizadas y enviadas a otras partes del organismo."],"correct":1,"e":"El aparato respiratorio lleva el oxígeno a los pulmones, donde se intercambia por dióxido de carbono, y expulsa este al exterior."},
  {"id":"ANA-T1-10","subject":"anato","exam":"Tema 1","text":"Las hormonas:","options":["Son sustancias segregadas por las glándulas cuyo fin es la regulación de ciertos procesos del organismo.","Se encargan de la defensa frente a agentes causantes de enfermedades.","Se encargan de la recogida, transferencia y procesado de información."],"correct":0,"e":"Las hormonas son sustancias que segregan las glándulas endocrinas y que viajan por la sangre para regular procesos del organismo."},
  {"id":"ANA-T1-11","subject":"anato","exam":"Tema 1","text":"El componente más abundante en los seres vivos después del agua:","options":["Glúcidos.","Proteínas.","Lípidos."],"correct":1,"e":"Después del agua, las proteínas son el componente más abundante de los seres vivos."},
  {"id":"ANA-T1-12","subject":"anato","exam":"Tema 1","text":"Los principios inmediatos inorgánicos de los seres vivos son:","options":["El agua y las sales minerales.","Glúcidos, lípidos, proteínas y ácidos nucleicos.","ADN."],"correct":0,"e":"Los principios inmediatos inorgánicos son el agua y las sales minerales. Glúcidos, lípidos, proteínas y ácidos nucleicos son los orgánicos."},
  {"id":"ANA-T1-13","subject":"anato","exam":"Tema 1","text":"Las células que tienen núcleo definido gracias a su membrana celular se denominan:","options":["Eucariotas.","Procariotas.","Unicelulares."],"correct":0,"e":"Las células eucariotas tienen el núcleo rodeado por una membrana. Las procariotas, como las bacterias, no tienen núcleo definido."},
  {"id":"ANA-T1-14","subject":"anato","exam":"Tema 1","text":"La mitosis:","options":["Es el proceso mediante el cual una célula eucariota separa los cromosomas en su núcleo, dando como resultado dos juegos idénticos. Estos se llaman «células hijas».","Es un tipo especial de división celular necesaria para la reproducción sexual en las eucariotas.","Solo ocurre en organismos cuya reproducción es sexual."],"correct":0,"e":"En la mitosis una célula reparte sus cromosomas y da dos células hijas idénticas. La división para la reproducción sexual es la meiosis."},
  {"id":"ANA-T1-15","subject":"anato","exam":"Tema 1","text":"El genotipo:","options":["Es la suma de los caracteres observables en un individuo.","Es el campo de la biología que busca comprender la herencia biológica que se transmite de generación en generación.","Es el conjunto de genes que contiene un organismo heredado de sus progenitores."],"correct":2,"e":"El genotipo es el conjunto de genes heredados de los progenitores. Los caracteres observables forman el fenotipo."},
  {"id":"ANA-T1-16","subject":"anato","exam":"Tema 1","text":"Las células que constituyen el tejido nervioso se denominan:","options":["Fibras musculares.","Neuronas y células de la glía.","Adipocitos."],"correct":1,"e":"El tejido nervioso está formado por neuronas, que transmiten el impulso, y células de la glía, que las sostienen y protegen."},
  {"id":"ANA-T1-17","subject":"anato","exam":"Tema 1","text":"Las dendritas:","options":["Constituyen una serie de prolongaciones pequeñas de las neuronas.","Captan el impulso nervioso y junto al axón se encargan de propagarlo a otras neuronas o músculos.","Ambas respuestas son correctas."],"correct":2,"e":"Las dendritas son prolongaciones cortas de la neurona que captan el impulso nervioso, que luego se propaga por el axón. Ambas son correctas."},
  {"id":"ANA-T1-18","subject":"anato","exam":"Tema 1","text":"El tejido muscular se regenera fácilmente tras una lesión:","options":["Por eso, tras un infarto de miocardio las zonas destruidas quedan reparadas totalmente.","El tejido muscular liso se regenera más que el tejido muscular estriado.","Ambas son incorrectas."],"correct":1,"e":"El músculo liso tiene más capacidad de regeneración que el estriado. El miocardio dañado en un infarto no se repara, sino que forma una cicatriz."},
  {"id":"ANA-T1-19","subject":"anato","exam":"Tema 1","text":"Se considera aparato:","options":["Un grupo de órganos que desempeñan una función común, realizando cada uno funciones similares con cierta independencia.","Un grupo de órganos asociados que concurren en una función general y están formados predominantemente por los mismos tipos de tejidos.","Al ser vivo en su conjunto. En él se incluyen tanto los organismos pluricelulares como los unicelulares."],"correct":0,"e":"Según el temario, un aparato es un grupo de órganos que colaboran en una función común, cada uno con cierta independencia. La B describe un sistema."},
  {"id":"ANA-T1-20","subject":"anato","exam":"Tema 1","text":"La locomoción es llevada a cabo por:","options":["El aparato locomotor.","El sistema nervioso.","El sistema muscular."],"correct":0,"e":"La locomoción la realiza el aparato locomotor, formado por huesos, articulaciones y músculos."},
  {"id":"ANA-T2-1","subject":"anato","exam":"Tema 2","text":"El plano que divide al cuerpo en parte anterior y posterior es:","options":["Horizontal o transversal.","Frontal, longitudinal o coronal.","Sagital, vertical o anteroposterior."],"correct":1,"e":"El plano frontal o coronal divide el cuerpo en una parte anterior y otra posterior. El sagital lo divide en derecha e izquierda y el transversal, en superior e inferior."},
  {"id":"ANA-T2-2","subject":"anato","exam":"Tema 2","text":"Hablamos de proximal y distal:","options":["Para las extremidades hace referencia a la proximidad o lejanía al tronco.","Cuando una parte del cuerpo se encuentra hacia atrás.","Cuando una parte del cuerpo está más cerca o más lejos de la superficie del cuerpo."],"correct":0,"e":"Proximal y distal se usan en las extremidades: proximal es lo más cercano al tronco y distal, lo más alejado."},
  {"id":"ANA-T2-3","subject":"anato","exam":"Tema 2","text":"La posición decúbito supino es:","options":["La posición de una persona que se encuentra de pie.","La persona se encuentra boca abajo, recostado sobre un lateral de su cuerpo.","La persona se encuentra boca arriba, tumbada sobre la espalda, con los brazos y las piernas en extensión y cerca del cuerpo."],"correct":2,"e":"En decúbito supino la persona está tumbada boca arriba, sobre la espalda, con brazos y piernas extendidos junto al cuerpo."},
  {"id":"ANA-T2-4","subject":"anato","exam":"Tema 2","text":"La posición decúbito ventral:","options":["Se encuentra de costado, tumbado sobre el abdomen, piernas extendidas y la cabeza girada hacia un lado.","Consiste en decúbito lateral con una pierna flexionada.","Entre decúbito lateral y prono."],"correct":0,"e":"En decúbito ventral o prono la persona está tumbada sobre el abdomen, con las piernas extendidas y la cabeza girada hacia un lado."},
  {"id":"ANA-T2-5","subject":"anato","exam":"Tema 2","text":"La posición Fowler consiste en:","options":["Tumbado sobre el dorso de su cuerpo, con los hombros en el límite de la cabecera de la cama o camilla, con la cabeza colgando fuera de la cama.","En decúbito supino sobre la cama o camilla, con una inclinación de 45º, con la cabeza más baja que los pies.","El cuerpo se encuentra semisentado, con las rodillas ligeramente flexionadas y el respaldo de la cama con una inclinación de 45º."],"correct":2,"e":"La posición de Fowler es semisentado, con el respaldo a unos 45º y las rodillas un poco flexionadas. Facilita la respiración."},
  {"id":"ANA-T2-6","subject":"anato","exam":"Tema 2","text":"La posición de shock:","options":["La persona se encuentra recostada boca arriba, se le levantarán las piernas unos 30 cm.","La persona se encuentra recostada con una inclinación de 45º, con la cabeza más alta que los pies.","Es una variante del decúbito prono pero con las caderas levantadas un poco más que los hombros."],"correct":0,"e":"En la posición antishock la persona está boca arriba con las piernas elevadas unos 30 cm, para favorecer el retorno de sangre al corazón y al cerebro."},
  {"id":"ANA-T2-7","subject":"anato","exam":"Tema 2","text":"El movimiento de flexión de una extremidad consiste en:","options":["Describir con la articulación un ángulo.","Retomar la extremidad a la posición habitual.","Giro total o en forma de cono de una estructura sobre su propio eje interno o externo."],"correct":0,"e":"Flexionar es doblar una articulación, reduciendo el ángulo entre sus segmentos. Volver a la posición es la extensión y el giro sobre su eje, la rotación o circunducción."},
  {"id":"ANA-T2-8","subject":"anato","exam":"Tema 2","text":"El movimiento de abducción consiste en:","options":["Separar las extremidades de la línea media del cuerpo.","Acercar las extremidades a la línea media del cuerpo.","Desplazar hacia debajo una parte del cuerpo."],"correct":0,"e":"La abducción separa la extremidad de la línea media del cuerpo. Acercarla es la aducción."},
  {"id":"ANA-T2-9","subject":"anato","exam":"Tema 2","text":"El movimiento de pronación consiste en:","options":["Rotación interna del antebrazo.","Orientación de la planta del pie al plano medio.","Movimiento que se produce al extender el brazo y colocar la palma de la mano hacia arriba."],"correct":0,"e":"La pronación es la rotación interna del antebrazo, que deja la palma hacia abajo. La supinación la pone hacia arriba."},
  {"id":"ANA-T2-10","subject":"anato","exam":"Tema 2","text":"Los movimientos principales que realiza el brazo son:","options":["Supinación y pronación.","Elevación y depresión.","Oposición."],"correct":0,"e":"Según el temario, los movimientos característicos del brazo (en concreto del antebrazo) son la supinación y la pronación."},
  {"id":"ANA-T2-11","subject":"anato","exam":"Tema 2","text":"La posición de referencia que se utiliza para describir el sitio o las diferentes partes del organismo se denomina:","options":["Anatómica.","Decúbito supino.","Erecta."],"correct":0,"e":"La posición anatómica (de pie, mirando al frente, brazos a los lados y palmas hacia delante) es la referencia para describir el cuerpo."},
  {"id":"ANA-T2-12","subject":"anato","exam":"Tema 2","text":"Los planos anatómicos:","options":["Son cortes imaginarios que se le practican al cuerpo o a una parte de él.","Sirven para localizar todos los componentes del cuerpo humano.","Ambas respuestas son correctas."],"correct":2,"e":"Los planos anatómicos son cortes imaginarios que sirven para localizar las estructuras del cuerpo, así que ambas son correctas."},
  {"id":"ANA-T2-13","subject":"anato","exam":"Tema 2","text":"Los tres planos anatómicos se denominan:","options":["Sagital, frontal y horizontal.","Frontal o coronal.","Horizontal y sagital."],"correct":0,"e":"Los tres planos anatómicos son el sagital, el frontal (coronal) y el horizontal (transversal)."},
  {"id":"ANA-T2-14","subject":"anato","exam":"Tema 2","text":"Según la Anatomía topográfica el cuerpo se divide en tres partes:","options":["Cráneo, cara y abdomen.","Cabeza, tronco y extremidades.","Tórax, cabeza y abdomen."],"correct":1,"e":"La anatomía topográfica divide el cuerpo en cabeza, tronco y extremidades."},
  {"id":"ANA-T2-15","subject":"anato","exam":"Tema 2","text":"La cavidad abdominal:","options":["Alberga la mayor parte de los órganos del metabolismo y la excreción.","Alberga la vejiga urinaria, el recto y algunos de los órganos del sistema reproductor.","Alberga el corazón, los pulmones, las vías respiratorias y el esófago."],"correct":0,"e":"La cavidad abdominal contiene la mayor parte de los órganos digestivos y del metabolismo. La B describe la pélvica y la C, la torácica."},
  {"id":"ANA-T2-16","subject":"anato","exam":"Tema 2","text":"El diafragma:","options":["Es un tejido muscular que interviene en la respiración.","Forma parte de la cavidad abdominal.","Se encuentra en la cavidad craneal."],"correct":0,"e":"El diafragma es un músculo que separa tórax y abdomen y es el principal músculo de la respiración."},
  {"id":"ANA-T2-17","subject":"anato","exam":"Tema 2","text":"La extremidad superior está constituida por:","options":["Brazo, antebrazo y mano.","Muslo, pierna y pie.","Epigastrio e hipogastrio."],"correct":0,"e":"La extremidad superior la forman brazo, antebrazo y mano. Muslo, pierna y pie son de la inferior."},
  {"id":"ANA-T2-18","subject":"anato","exam":"Tema 2","text":"La cabeza está constituida por dos partes fundamentales:","options":["Tórax y abdomen.","Cráneo y cara.","Mediastino."],"correct":1,"e":"La cabeza tiene dos partes: el cráneo, que protege el encéfalo, y la cara."},
  {"id":"ANA-T2-19","subject":"anato","exam":"Tema 2","text":"El epigastrio:","options":["Es una de las nueve regiones arbitrarias en que se divide el abdomen.","Está formado por huesos y con un gran número de orificios (la boca, las fosas nasales o las cavidades de los ojos).","Se conoce como cavidad pélvica."],"correct":0,"e":"El epigastrio es una de las nueve regiones en que se divide el abdomen; es la parte central y superior."},
  {"id":"ANA-T2-20","subject":"anato","exam":"Tema 2","text":"El término anterior o ventral hace referencia:","options":["A una estructura que se encuentra delante de otra.","Cuando una parte del cuerpo se encuentra hacia atrás.","Para las extremidades hace referencia a la proximidad o lejanía del tronco."],"correct":0,"e":"Anterior o ventral indica que una estructura está delante de otra. Lo que está detrás es posterior o dorsal."},
  {"id":"ANA-T3-1","subject":"anato","exam":"Tema 3","text":"¿Cuál es la definición de SALUD según la OMS?","options":["Es un estado de bienestar físico, mental y social, con capacidad de funcionamiento, y no sólo la ausencia de afecciones o enfermedades.","Alteración o desviación del estado fisiológico en una o varias partes del cuerpo, de etiología (causa) en general conocida, que se manifiesta por síntomas y signos característicos y cuya evolución es más o menos previsible.","Es el resultado de la reacción del organismo en particular frente a un agente que lo altera. Por ello en realidad no deberíamos hablar de enfermedades sino de enfermos."],"correct":0,"e":"La OMS define la salud como un estado de completo bienestar físico, mental y social, no solo la ausencia de enfermedad. La B es una definición de enfermedad."},
  {"id":"ANA-T3-2","subject":"anato","exam":"Tema 3","text":"¿Qué es la Organización Mundial de la Salud, OMS?","options":["Un organismo de la Organización de las Naciones Unidas (ONU) especializado en gestionar políticas de prevención, promoción e intervención en salud a nivel mundial.","Es el responsable de desempeñar una función de liderazgo en los asuntos sanitarios mundiales.","Ambas respuestas son correctas."],"correct":2,"e":"La OMS es el organismo de la ONU especializado en salud y lidera los asuntos sanitarios a nivel mundial, así que ambas son correctas."},
  {"id":"ANA-T3-3","subject":"anato","exam":"Tema 3","text":"Las variables que sirven para medir los cambios que se producen en el estado de salud se denominan:","options":["Indicadores sociales y económicos.","Indicadores de salud.","Determinantes de salud."],"correct":1,"e":"Los indicadores de salud son las variables que permiten medir los cambios en el estado de salud de una población."},
  {"id":"ANA-T3-4","subject":"anato","exam":"Tema 3","text":"¿Cuál de estos términos se utiliza para definir el estado de salud?","options":["Tasa de mortalidad.","Incidencia.","Etiología."],"correct":0,"e":"La tasa de mortalidad es un indicador que se usa para describir el estado de salud de una población."},
  {"id":"ANA-T3-5","subject":"anato","exam":"Tema 3","text":"La prevalencia:","options":["Define la cantidad de individuos que son considerados enfermos o que son víctimas de enfermedad en un espacio y tiempo determinado.","Contabiliza el número de casos nuevos de la enfermedad que estudiamos, que aparecen en un período de tiempo previamente determinado.","Describe la proporción de la población que padece la enfermedad, que queremos estudiar, en un momento determinado."],"correct":2,"e":"La prevalencia es la proporción de la población que tiene la enfermedad en un momento dado. Los casos nuevos en un periodo son la incidencia."},
  {"id":"ANA-T3-6","subject":"anato","exam":"Tema 3","text":"Se produce taquicardia cuando:","options":["La frecuencia cardíaca está por encima de 100 ppm.","La frecuencia cardíaca está por debajo de 60 ppm.","La temperatura corporal se encuentra por debajo de 35º."],"correct":0,"e":"Hay taquicardia cuando la frecuencia cardíaca supera los 100 latidos por minuto. Por debajo de 60 es bradicardia."},
  {"id":"ANA-T3-7","subject":"anato","exam":"Tema 3","text":"La hipoxia se produce cuando:","options":["La saturación de Oxígeno es mayor al 95%.","La saturación de Oxígeno es menor al 95%.","Cuando la temperatura corporal se encuentra por encima de 37.5 ºC."],"correct":1,"e":"Se considera hipoxia cuando la saturación de oxígeno baja del 95%."},
  {"id":"ANA-T3-8","subject":"anato","exam":"Tema 3","text":"En adulto sano la presión arterial normal está:","options":["Entre 120 mmHg de sistólica y 80 mmHg de diastólica.","Entre 140 mmHg de sistólica y 90 mmHg de diastólica.","Entre 90 mmHg de sistólica y 60 mmHg de diastólica."],"correct":0,"e":"La tensión arterial de referencia en un adulto sano es de 120 mmHg de sistólica y 80 de diastólica."},
  {"id":"ANA-T3-9","subject":"anato","exam":"Tema 3","text":"El procedimiento de auscultación cardíaca consiste en:","options":["La observación detallada del paciente.","La palpación de las diferentes partes del cuerpo.","Escuchar de forma indirecta o mediante instrumentos el área torácica para valorar los sonidos normales del corazón."],"correct":2,"e":"Auscultar el corazón es escuchar los ruidos cardíacos, directamente o con fonendoscopio, en el tórax."},
  {"id":"ANA-T3-10","subject":"anato","exam":"Tema 3","text":"La medición de la actividad eléctrica del corazón se realiza mediante:","options":["Electrocardiografía.","Electroencefalografía.","Electromiografía."],"correct":0,"e":"El electrocardiograma registra la actividad eléctrica del corazón. El electroencefalograma, la del cerebro y el electromiograma, la de los músculos."},
  {"id":"ANA-T3-11","subject":"anato","exam":"Tema 3","text":"La esperanza de vida:","options":["Es la media de la cantidad de años que vive una determinada población en un cierto periodo de tiempo.","Es la proporción de personas que mueren por una enfermedad entre los afectados por la misma en un periodo y área determinados.","Es la capacidad de reproducción de una población."],"correct":0,"e":"La esperanza de vida es la media de años que vive una población en un periodo determinado."},
  {"id":"ANA-T3-12","subject":"anato","exam":"Tema 3","text":"La enfermedad surge debido a tres causas principales:","options":["El medio ambiente, el huésped y el agente causal de la enfermedad.","La predisposición, las drogas y los medicamentos.","Bacterias, virus y parásitos."],"correct":0,"e":"La enfermedad surge de la interacción entre el agente causal, el huésped y el medio ambiente (la tríada ecológica)."},
  {"id":"ANA-T3-13","subject":"anato","exam":"Tema 3","text":"¿Qué es un alérgeno?","options":["Es una sustancia que puede provocar una reacción alérgica.","Es una bacteria.","Es un virus."],"correct":0,"e":"Un alérgeno es cualquier sustancia capaz de provocar una reacción alérgica en una persona sensible."},
  {"id":"ANA-T3-14","subject":"anato","exam":"Tema 3","text":"Una enfermedad idiopática se define como:","options":["Aquella producida por un virus.","Aquella de origen desconocido.","Aquella causada por una bacteria."],"correct":1,"e":"Una enfermedad idiopática es aquella cuya causa se desconoce."},
  {"id":"ANA-T3-15","subject":"anato","exam":"Tema 3","text":"Una enfermedad congénita es aquella:","options":["Debida a anomalías en el desarrollo fetal.","Debida a la transmisión hereditaria de genes, dominantes o recesivos, a los que están determinadas patologías.","Debida a la degeneración progresiva de las funciones nerviosas."],"correct":0,"e":"Una enfermedad congénita es la que está presente al nacer por una alteración del desarrollo fetal. La transmitida por genes es la hereditaria."},
  {"id":"DIG-T1-1","subject":"digi","exam":"Tema 1","text":"¿Cuál de las siguientes opciones describe mejor el modelo de economía lineal?","options":["Un modelo en el que se reutilizan, reparan y reciclan productos para minimizar los residuos.","Un modelo en el que los productos se fabrican, consumen y luego se desechan sin reutilización ni reciclaje.","Un modelo que promueve la utilización de recursos renovables y la reducción de residuos en todos los procesos productivos."],"correct":1,"e":"La economía lineal sigue el esquema «extraer, fabricar, usar y tirar», sin reutilizar ni reciclar."},
  {"id":"ANA-T3-16","subject":"anato","exam":"Tema 3","text":"La ciencia encargada del estudio de las enfermedades en su sentido más amplio es la:","options":["Etiología.","Fisiopatología.","Patología."],"correct":2,"e":"La patología estudia las enfermedades en su sentido más amplio. La etiología estudia solo las causas."},
  {"id":"DIG-T1-2","subject":"digi","exam":"Tema 1","text":"¿Cuál es uno de los principales objetivos de la economía circular?","options":["Reducir la cantidad de residuos y aprovechar al máximo los recursos naturales mediante la reutilización y el reciclaje.","Aumentar la producción y el consumo sin preocuparse por el impacto ambiental.","Desarrollar productos desechables para que los consumidores los reemplacen rápidamente."],"correct":0,"e":"La economía circular busca reducir residuos y aprovechar al máximo los recursos mediante la reutilización, la reparación y el reciclaje."},
  {"id":"DIG-T1-3","subject":"digi","exam":"Tema 1","text":"¿Cuál de las siguientes afirmaciones describe correctamente una diferencia clave entre la economía lineal (EL) y la economía circular (EC)?","options":["La economía lineal genera menos residuos y contaminación que la economía circular.","La economía circular busca reducir la extracción de recursos y la generación de residuos mediante el reciclaje y la reutilización.","La economía lineal promueve la reutilización de productos y la reducción de residuos, mientras que la economía circular depende de la extracción constante de recursos."],"correct":1,"e":"La diferencia clave es que la economía circular reduce la extracción de recursos y los residuos reciclando y reutilizando. Las otras opciones dicen lo contrario."},
  {"id":"ANA-T3-17","subject":"anato","exam":"Tema 3","text":"Los síntomas de una enfermedad se definen como:","options":["Todas las manifestaciones que son únicamente perceptibles por la persona afectada.","Las manifestaciones observables y medibles por la persona que examina.","Ambas respuestas son correctas."],"correct":0,"e":"Los síntomas son lo que percibe solo el paciente, como el dolor o el mareo. Lo que el sanitario observa o mide son los signos."},
  {"id":"DIG-T1-4","subject":"digi","exam":"Tema 1","text":"¿Cuál de las siguientes características es propia de la Cuarta Revolución Industrial?","options":["El uso exclusivo de la máquina de vapor para la producción en fábricas.","La mecanización de la producción con maquinaria operada manualmente.","La integración de la Inteligencia Artificial (IA), la automatización avanzada y la conectividad a través de Internet de las Cosas (IoT)."],"correct":2,"e":"La Cuarta Revolución Industrial integra inteligencia artificial, automatización avanzada e Internet de las Cosas. El vapor y la mecanización son de la primera."},
  {"id":"ANA-T3-18","subject":"anato","exam":"Tema 3","text":"El dolor:","options":["Es un signo de la enfermedad.","Es un síntoma de una enfermedad.","Es un signo que indica que la temperatura corporal es elevada."],"correct":1,"e":"El dolor es un síntoma porque lo percibe el paciente y no se puede medir objetivamente."},
  {"id":"ANA-T3-19","subject":"anato","exam":"Tema 3","text":"La tos:","options":["Es un signo de enfermedad.","Es un síntoma de enfermedad.","Consiste en dificultad respiratoria."],"correct":0,"e":"Según el temario, la tos es un signo porque quien explora puede observarla."},
  {"id":"DIG-T1-5","subject":"digi","exam":"Tema 1","text":"Verdadero o falso: la Industria 4.0 se basa principalmente en el uso de la inteligencia artificial, el Internet de las Cosas (IoT), la automatización avanzada y la impresión 3D para optimizar la producción, mejorar la calidad y ofrecer productos personalizados.","options":["Verdadero.","Falso."],"correct":0,"e":"Verdadero: la Industria 4.0 combina IA, IoT, automatización e impresión 3D para producir mejor y de forma personalizada."},
  {"id":"DIG-T1-6","subject":"digi","exam":"Tema 1","text":"¿Cuál de las siguientes características es más representativa de la Revolución Industrial?","options":["La transición de una economía agrícola a una economía basada en la manufactura y el trabajo en fábricas.","El aumento exclusivo de la producción agrícola gracias a la implementación de nuevas técnicas de cultivo.","La creación de grandes imperios coloniales sin ningún impacto en las ciudades industriales."],"correct":0,"e":"La Revolución Industrial supuso pasar de una economía agrícola a otra basada en la manufactura y el trabajo en fábricas."},
  {"id":"ANA-T3-20","subject":"anato","exam":"Tema 3","text":"Los signos vitales reflejan las funciones vitales del organismo. Son:","options":["Frecuencia cardíaca y temperatura.","Presión arterial y saturación de oxígeno.","Ambas respuestas son correctas."],"correct":2,"e":"Son signos vitales la frecuencia cardíaca, la temperatura, la presión arterial y la saturación de oxígeno (junto con la frecuencia respiratoria), así que ambas son correctas."},
  {"id":"DIG-T1-7","subject":"digi","exam":"Tema 1","text":"¿Cuál de las siguientes afirmaciones describe mejor un sistema ciberfísico?","options":["Un sistema que se basa únicamente en la automatización de procesos manuales sin interacción con el mundo físico.","Un sistema que combina componentes informáticos y físicos para controlar y monitorear procesos en tiempo real.","Un sistema que solo utiliza sensores para recopilar datos sin intervención de algoritmos de control."],"correct":1,"e":"Un sistema ciberfísico une componentes informáticos y físicos para controlar y vigilar procesos en tiempo real."},
  {"id":"ANA-T4-1","subject":"anato","exam":"Tema 4","text":"El sistema nervioso central (SNC) se encuentra localizado en:","options":["En la base del cráneo, es la parte del sistema nervioso que comunica el cerebro y la médula espinal.","En el interior del cráneo y la columna vertebral, estructuras óseas que le protegen.","Es la parte de mayor tamaño y se localiza en la zona superior de la cavidad craneal."],"correct":1,"e":"El sistema nervioso central (encéfalo y médula espinal) está dentro del cráneo y de la columna vertebral, que lo protegen."},
  {"id":"DIG-T1-8","subject":"digi","exam":"Tema 1","text":"¿Cuál de las siguientes tecnologías es fundamental para la transformación en la Industria 4.0?","options":["Solo la automatización de procesos manuales mediante máquinas.","La integración de Internet de las Cosas (IoT), Big Data y sistemas ciberfísicos en procesos de fabricación.","El uso exclusivo de trabajadores humanos sin la intervención de tecnología avanzada."],"correct":1,"e":"La transformación de la Industria 4.0 se basa en integrar IoT, Big Data y sistemas ciberfísicos en la fabricación."},
  {"id":"ANA-T4-2","subject":"anato","exam":"Tema 4","text":"La función de las meninges es:","options":["Proteger al sistema nervioso central.","Coordinar la actividad muscular, el equilibrio y el mantenimiento del tono muscular.","Relacionar al organismo con el medio exterior."],"correct":0,"e":"Las meninges (duramadre, aracnoides y piamadre) son las membranas que envuelven y protegen el sistema nervioso central."},
  {"id":"DIG-T1-9","subject":"digi","exam":"Tema 1","text":"¿Cuál de las siguientes características es propia de la economía lineal?","options":["Fomenta el reciclaje y la reutilización de productos.","Promueve un ciclo de producción y consumo que termina con la creación de residuos.","Se basa en la extracción mínima de recursos naturales."],"correct":1,"e":"La economía lineal produce, consume y termina generando residuos, sin cerrar el ciclo."},
  {"id":"ANA-T4-3","subject":"anato","exam":"Tema 4","text":"¿Cuál es la función del sistema nervioso periférico?","options":["Es el encargado de establecer las directrices de las funciones del cuerpo.","Transmitir el estímulo.","Obtener información interna y del exterior; así como transmitir las acciones necesarias para adaptarse a las necesidades según sea esa información."],"correct":2,"e":"El sistema nervioso periférico recoge información del interior y del exterior y transmite las respuestas para adaptarse a ella."},
  {"id":"DIG-T1-10","subject":"digi","exam":"Tema 1","text":"¿Cuál de las siguientes afirmaciones es una característica principal de la economía circular?","options":["Los productos se diseñan para ser desechados rápidamente.","Los recursos naturales se extraen sin considerar su renovación.","Los productos se diseñan para ser reutilizados, reciclados o reparados."],"correct":2,"e":"En la economía circular los productos se diseñan para poder reutilizarlos, repararlos o reciclarlos."},
  {"id":"ANA-T4-4","subject":"anato","exam":"Tema 4","text":"El sistema nervioso autónomo se divide en:","options":["Sistema nervioso simpático.","Sistema nervioso parasimpático.","Ambas respuestas son correctas."],"correct":2,"e":"El sistema nervioso autónomo se divide en simpático, que activa, y parasimpático, que relaja. Ambas son correctas."},
  {"id":"DIG-T1-11","subject":"digi","exam":"Tema 1","text":"¿Cuál de los siguientes modelos tiene un mayor impacto positivo en el medio ambiente?","options":["Economía Lineal (EL).","Economía Circular (EC).","Economía Tradicional."],"correct":1,"e":"La economía circular reduce la extracción de recursos y los residuos, por eso tiene un mayor impacto positivo en el medio ambiente."},
  {"id":"ANA-T4-5","subject":"anato","exam":"Tema 4","text":"La columna vertebral protege:","options":["El encéfalo.","El cerebelo.","La médula espinal."],"correct":2,"e":"La columna vertebral protege la médula espinal. El encéfalo y el cerebelo los protege el cráneo."},
  {"id":"DIG-T1-12","subject":"digi","exam":"Tema 1","text":"¿Cuál de las siguientes características es típica de un modelo económico lineal?","options":["Los productos están diseñados para ser reutilizados y reciclados.","Los recursos naturales se extraen, se utilizan y se desechan al final del ciclo de vida del producto.","Los residuos generados durante la producción se reutilizan en el proceso de fabricación."],"correct":1,"e":"En el modelo lineal los recursos se extraen, se usan y se tiran al final de la vida del producto."},
  {"id":"ANA-T4-6","subject":"anato","exam":"Tema 4","text":"Los receptores del sentido del gusto se encuentran:","options":["En las fosas nasales.","En las papilas gustativas.","En el globo ocular."],"correct":1,"e":"Los receptores del gusto están en las papilas gustativas de la lengua."},
  {"id":"ANA-T4-7","subject":"anato","exam":"Tema 4","text":"La miopía:","options":["Es un problema de proyección de la imagen que impide ver nítidamente lo más alejado.","Todo aquello que está lejos se distingue bien, pero lo que está cerca se ve borroso.","Impide enfocar los objetos cercanos."],"correct":0,"e":"El miope ve borroso de lejos porque la imagen se forma delante de la retina. Ver mal de cerca es la hipermetropía."},
  {"id":"DIG-T1-13","subject":"digi","exam":"Tema 1","text":"¿Cuál de los siguientes procesos es un ejemplo de la Economía Circular?","options":["El reciclaje de materiales para fabricar nuevos productos, como ropa hecha de plásticos reciclados.","La fabricación de productos electrónicos que se descartan al final de su vida útil.","La producción de alimentos utilizando grandes cantidades de pesticidas y fertilizantes químicos."],"correct":0,"e":"Reciclar materiales para fabricar productos nuevos, como ropa de plástico reciclado, es un ejemplo típico de economía circular."},
  {"id":"ANA-T4-8","subject":"anato","exam":"Tema 4","text":"La pérdida de capacidad auditiva se denomina:","options":["Catarata.","Ceguera.","Hipoacusia."],"correct":2,"e":"La hipoacusia es la pérdida de capacidad auditiva. La catarata afecta al cristalino del ojo."},
  {"id":"DIG-T1-14","subject":"digi","exam":"Tema 1","text":"¿Cuál es uno de los principales desafíos de la 4ª Revolución Industrial?","options":["La escasez de recursos naturales.","La automatización y la pérdida de empleos tradicionales.","La falta de transporte global."],"correct":1,"e":"Uno de los grandes retos de la Cuarta Revolución Industrial es que la automatización sustituya empleos tradicionales."},
  {"id":"DIG-T1-15","subject":"digi","exam":"Tema 1","text":"¿Qué caracteriza a los sistemas ciberfísicos (CPS)?","options":["Son sistemas que combinan procesos físicos con computación, comunicación y control.","Son sistemas que solo dependen de la computación y la inteligencia artificial.","Son sistemas diseñados para operar de forma manual sin interacción con dispositivos conectados."],"correct":0,"e":"Los sistemas ciberfísicos combinan procesos físicos con computación, comunicación y control."},
  {"id":"ANA-T4-9","subject":"anato","exam":"Tema 4","text":"El órgano más grande del cuerpo es:","options":["Corazón.","Piel.","Pulmones."],"correct":1,"e":"La piel es el órgano más grande del cuerpo."},
  {"id":"DIG-T1-16","subject":"digi","exam":"Tema 1","text":"¿Qué característica define mejor a los sistemas automatizados en la Industria 4.0?","options":["Se basan únicamente en procesos manuales controlados por operarios.","Los sistemas están desconectados entre sí, operando de manera independiente.","Los sistemas están interconectados, permiten la comunicación entre máquinas y toman decisiones en tiempo real."],"correct":2,"e":"En la Industria 4.0 las máquinas están interconectadas, se comunican entre sí y toman decisiones en tiempo real."},
  {"id":"ANA-T4-10","subject":"anato","exam":"Tema 4","text":"La cadena de huesecillos se encuentra localizada en el oído:","options":["Medio.","Externo.","Interno."],"correct":0,"e":"Los huesecillos (martillo, yunque y estribo) están en el oído medio."},
  {"id":"DIG-T1-17","subject":"digi","exam":"Tema 1","text":"¿Cuál de las siguientes características define mejor al metaverso?","options":["Un espacio virtual al que solo se puede acceder a través de dispositivos móviles.","Un entorno tridimensional en el que los usuarios interactúan entre sí y con objetos virtuales.","Un sitio web donde solo se realizan compras en línea."],"correct":1,"e":"El metaverso es un entorno virtual tridimensional en el que los usuarios interactúan entre sí y con objetos virtuales."},
  {"id":"ANA-T4-11","subject":"anato","exam":"Tema 4","text":"La parálisis:","options":["Es la disminución de sensación cutánea ante un estímulo específico como presión, tacto, temperatura.","Es una de las manifestaciones más frecuentes de las enfermedades neurológicas.","Es una alteración de la consciencia."],"correct":1,"e":"La parálisis, pérdida de la capacidad de mover una parte del cuerpo, es una de las manifestaciones más frecuentes de las enfermedades neurológicas. La A describe la hipoestesia."},
  {"id":"DIG-T1-18","subject":"digi","exam":"Tema 1","text":"¿Cuál de las siguientes ventajas para los clientes se ve favorecida por la Industria 4.0?","options":["Mayor accesibilidad a productos y servicios a través de plataformas digitales.","Reducción de la velocidad de entrega de productos.","Disminución de la personalización de productos y servicios."],"correct":0,"e":"La Industria 4.0 facilita a los clientes el acceso a productos y servicios a través de plataformas digitales."},
  {"id":"ANA-T4-12","subject":"anato","exam":"Tema 4","text":"¿Qué es la escala de valoración de coma de Glasgow?","options":["Es una escala que permite valorar el estado de consciencia.","Evalúa de manera práctica el nivel de Estado de Alerta en los seres humanos.","Ambas respuestas son correctas."],"correct":2,"e":"La escala de Glasgow valora el nivel de consciencia y el estado de alerta, así que ambas son correctas."},
  {"id":"ANA-T4-13","subject":"anato","exam":"Tema 4","text":"Las convulsiones son una de las manifestaciones más frecuentes de enfermedades neurológicas que consisten en:","options":["Contracciones musculares involuntarias de aparición brusca que provocan unos movimientos característicos en forma de espasmos.","La pérdida de memoria.","En una incapacidad para expresarse."],"correct":0,"e":"Las convulsiones son contracciones musculares involuntarias y bruscas que producen movimientos en forma de espasmos."},
  {"id":"DIG-T1-19","subject":"digi","exam":"Tema 1","text":"¿Cuál de las siguientes afirmaciones describe mejor la diferencia entre la economía lineal y la economía circular?","options":["La economía circular busca reducir el uso de recursos naturales mediante la extracción masiva de estos.","La economía circular se centra únicamente en la producción de bienes desechables y la economía lineal en la reparación de productos.","La economía lineal se basa en el modelo «tomar, hacer, desechar», mientras que la economía circular promueve el reciclaje y la reutilización de productos."],"correct":2,"e":"La economía lineal sigue el modelo «tomar, hacer, desechar»; la circular promueve reutilizar y reciclar."},
  {"id":"ANA-T4-14","subject":"anato","exam":"Tema 4","text":"La demencia:","options":["Se caracteriza por un deterioro progresivo, crónico e irreversible de las funciones mentales.","Es una enfermedad caracterizada por la aparición súbita de convulsiones.","Se trata de un trastorno de las estructuras nerviosas que regulan y coordinan los movimientos musculares involuntarios."],"correct":0,"e":"La demencia es un deterioro progresivo, crónico e irreversible de las funciones mentales."},
  {"id":"DIG-T1-20","subject":"digi","exam":"Tema 1","text":"¿Qué modelo económico promueve el uso continuo de materiales a través de su reutilización, reciclaje y reducción de residuos?","options":["Economía lineal.","Economía circular.","Economía de consumo."],"correct":1,"e":"La economía circular mantiene los materiales en uso mediante reutilización, reciclaje y reducción de residuos."},
  {"id":"ANA-T4-15","subject":"anato","exam":"Tema 4","text":"El dolor de cabeza es también llamado:","options":["Meningitis.","Accidente cerebrovascular (ACV).","Cefalea."],"correct":2,"e":"Cefalea es el nombre médico del dolor de cabeza."},
  {"id":"DIG-T1-21","subject":"digi","exam":"Tema 1","text":"¿Cuál es uno de los principales beneficios ambientales de la Economía Circular?","options":["Aumento de la producción de residuos.","Reducción del consumo de recursos naturales.","Mayor dependencia de la extracción de materias primas."],"correct":1,"e":"Al reutilizar y reciclar, la economía circular reduce el consumo de recursos naturales."},
  {"id":"ANA-T4-16","subject":"anato","exam":"Tema 4","text":"La melanina es un pigmento:","options":["Amarillo.","Abunda en las personas de raza negra.","Que desarrolla vesículas epiteliales."],"correct":1,"e":"La melanina es el pigmento que da color a la piel y abunda más en las personas de piel oscura."},
  {"id":"DIG-T1-22","subject":"digi","exam":"Tema 1","text":"¿Cuál de los siguientes procesos es un ejemplo de la Economía Lineal?","options":["Reciclaje de plásticos para fabricar nuevos productos.","Producción de alimentos con prácticas de agricultura sostenible.","Fabricación de productos electrónicos que se descartan al final de su vida útil."],"correct":2,"e":"Fabricar aparatos que se tiran al final de su vida útil sin recuperarlos es un ejemplo de economía lineal."},
  {"id":"ANA-T4-17","subject":"anato","exam":"Tema 4","text":"Las pecas o efélides:","options":["Son zonas elevadas de hasta 5 mm de diámetro, generalmente rojizas que aparecen en la piel.","Son zonas elevadas de más de 5 mm de diámetro, pueden tener también color rojizo, o normal, u otro.","Son irregularidades en la distribución de melanina en la piel."],"correct":2,"e":"Las pecas o efélides son irregularidades en la distribución de la melanina en la piel."},
  {"id":"DIG-T1-23","subject":"digi","exam":"Tema 1","text":"¿Cuál de los siguientes ejemplos representa un principio de la Economía Circular?","options":["Descartar los productos al final de su vida útil sin reciclaje.","Fabricar productos con materiales reciclados y diseñarlos para ser fácilmente reutilizados o reparados.","Producir productos de un solo uso con materiales que no pueden ser reciclados."],"correct":1,"e":"Usar materiales reciclados y diseñar productos fáciles de reparar o reutilizar es un principio de la economía circular."},
  {"id":"ANA-T4-18","subject":"anato","exam":"Tema 4","text":"La pérdida de la integridad de la uña se denomina:","options":["Escama.","Onicolisis.","Liquenificación."],"correct":1,"e":"La onicolisis es el despegamiento de la uña de su lecho, con pérdida de su integridad."},
  {"id":"DIG-T1-24","subject":"digi","exam":"Tema 1","text":"¿Cuál de las siguientes tecnologías es una de las principales características de la 4ª Revolución Industrial?","options":["La máquina de vapor.","La inteligencia artificial (IA).","La electricidad como fuente principal de energía."],"correct":1,"e":"La inteligencia artificial es una de las tecnologías clave de la Cuarta Revolución Industrial. El vapor y la electricidad corresponden a la primera y la segunda."},
  {"id":"ANA-T4-19","subject":"anato","exam":"Tema 4","text":"La hiperqueratosis:","options":["Es una hiperplasia del estrato córneo.","Consiste en la pérdida de conexiones intercelulares.","Es una forma de proliferación de los melanocitos en estrato basal."],"correct":0,"e":"La hiperqueratosis es el engrosamiento del estrato córneo, la capa más externa de la epidermis."},
  {"id":"DIG-T1-25","subject":"digi","exam":"Tema 1","text":"¿Cuál de las siguientes tecnologías es fundamental para que los sistemas ciberfísicos interactúen en tiempo real?","options":["La impresión 3D.","El almacenamiento en la nube.","Los sensores y actuadores."],"correct":2,"e":"Los sensores captan datos del mundo físico y los actuadores actúan sobre él, lo que permite a los sistemas ciberfísicos interactuar en tiempo real."},
  {"id":"DIG-T1-26","subject":"digi","exam":"Tema 1","text":"¿Cuál de las siguientes tecnologías es clave para la mejora de los sistemas automatizados en la Industria 4.0?","options":["El Internet de las Cosas (IoT).","La máquina de vapor.","El uso exclusivo de materiales reciclados."],"correct":0,"e":"El Internet de las Cosas conecta máquinas y dispositivos, y es clave para mejorar la automatización en la Industria 4.0."},
  {"id":"ANA-T4-20","subject":"anato","exam":"Tema 4","text":"La queratosis actínica:","options":["Es una enfermedad de la piel caracterizada por la hiperplasia y el engrosamiento del epitelio cornificado.","Es el estado temprano del carcinoma espinocelular.","Ambas respuestas son correctas."],"correct":2,"e":"La queratosis actínica engrosa el epitelio por exposición al sol y se considera una lesión precursora del carcinoma espinocelular, así que ambas son correctas."},
  {"id":"ANA-T5-1","subject":"anato","exam":"Tema 5","text":"El aparato locomotor necesita de otros órganos y estructuras para poder ejercer la locomoción. Éstos son:","options":["Sentido del tacto.","Sistema nervioso, vista y audición.","Sentido del olfato."],"correct":1,"e":"Para moverse, el aparato locomotor necesita el sistema nervioso, que da las órdenes, y la vista y el oído, que informan del entorno y del equilibrio."},
  {"id":"DIG-T1-27","subject":"digi","exam":"Tema 1","text":"¿Qué tecnología es clave para una experiencia inmersiva en el metaverso?","options":["Realidad aumentada (AR).","Realidad virtual (VR).","Navegadores web tradicionales."],"correct":1,"e":"La realidad virtual es la que sumerge por completo al usuario en el entorno del metaverso. La aumentada solo superpone elementos al mundo real."},
  {"id":"ANA-T5-2","subject":"anato","exam":"Tema 5","text":"Los animales invertebrados presentan exoesqueleto compuesto por:","options":["Quitina.","Esqueleto óseo.","Estructura esquelética llena de líquido."],"correct":0,"e":"El exoesqueleto de los invertebrados, como insectos y crustáceos, está formado por quitina."},
  {"id":"DIG-T1-28","subject":"digi","exam":"Tema 1","text":"¿Cuál de las siguientes es una ventaja clave para las empresas en un entorno 4.0?","options":["Reducción de costos operativos gracias a la automatización y análisis de datos.","Aumento de la intervención manual en los procesos de producción.","Eliminación de la necesidad de usar tecnologías digitales."],"correct":0,"e":"Gracias a la automatización y al análisis de datos, las empresas 4.0 reducen sus costes operativos."},
  {"id":"ANA-T5-3","subject":"anato","exam":"Tema 5","text":"El esqueleto está constituido por:","options":["Tejido óseo.","Tejido cartilaginoso.","Ambas respuestas son correctas."],"correct":2,"e":"El esqueleto está formado por tejido óseo y tejido cartilaginoso, así que ambas son correctas."},
  {"id":"ANA-T5-4","subject":"anato","exam":"Tema 5","text":"El tejido óseo está formado a su vez por:","options":["Tejido óseo compacto.","Tejido óseo esponjoso.","Ambas respuestas son correctas."],"correct":2,"e":"El tejido óseo puede ser compacto (exterior y duro) o esponjoso (interior y con trabéculas), así que ambas son correctas."},
  {"id":"ANA-T5-5","subject":"anato","exam":"Tema 5","text":"La función hematopoyética del hueso consiste en:","options":["Dar estructura y forma al cuerpo.","Almacén de calcio y fosfato para el organismo.","En producir ciertos componentes de la sangre."],"correct":2,"e":"La función hematopoyética es producir células sanguíneas en la médula ósea roja."},
  {"id":"ANA-T5-6","subject":"anato","exam":"Tema 5","text":"La epífisis es:","options":["Es el extremo de los huesos largos.","Es el cuerpo de los huesos largos.","Es un disco cartilaginoso que forma parte de los huesos largos."],"correct":0,"e":"La epífisis es cada uno de los extremos de un hueso largo. El cuerpo es la diáfisis."},
  {"id":"ANA-T5-7","subject":"anato","exam":"Tema 5","text":"Los huesos planos son:","options":["Un tipo de hueso donde predomina la longitud y el ancho sobre su espesor.","Huesos cortos similares a un cubo.","Aquellos huesos que por su forma no se pueden clasificar en otro tipo."],"correct":0,"e":"En los huesos planos predominan la longitud y la anchura sobre el grosor (por ejemplo, el esternón o los del cráneo)."},
  {"id":"ANA-T5-8","subject":"anato","exam":"Tema 5","text":"Las articulaciones semimóviles son:","options":["Aquellas que permiten una cierta movilidad entre los huesos que se unen.","Aquellas que permiten una mayor movilidad.","Aquellas que no tienen capacidad de movimiento."],"correct":0,"e":"Las articulaciones semimóviles permiten un movimiento limitado entre los huesos, como las de las vértebras."},
  {"id":"ANA-T5-9","subject":"anato","exam":"Tema 5","text":"El esqueleto apendicular:","options":["Es el de las extremidades.","Corresponde a los huesos que constituyen el eje del cuerpo.","Comprende la columna vertebral y el esternón."],"correct":0,"e":"El esqueleto apendicular es el de las extremidades y sus cinturas. El axial es el eje: cráneo, columna, costillas y esternón."},
  {"id":"ANA-T5-10","subject":"anato","exam":"Tema 5","text":"El hueso frontal forma parte de:","options":["El cráneo.","La columna vertebral.","Las costillas verdaderas."],"correct":0,"e":"El hueso frontal forma la frente y es uno de los huesos del cráneo."},
  {"id":"ANA-T5-11","subject":"anato","exam":"Tema 5","text":"El coxis:","options":["Es un hueso triangular de pequeño tamaño, formado por la unión de tres-cuatro vértebras.","Está formado por la fusión de cinco vértebras sacras.","Se articula con las costillas."],"correct":0,"e":"El coxis es un hueso pequeño y triangular formado por la fusión de 3 o 4 vértebras. El que forman cinco vértebras fusionadas es el sacro."},
  {"id":"ANA-T5-12","subject":"anato","exam":"Tema 5","text":"La lordosis lumbar es:","options":["Una desviación de la columna vertebral, que resulta curvada en forma de \"S\" o de \"C\".","La curvatura fisiológica de la columna vertebral en la región dorsal.","La curvatura fisiológica de la columna en la región cervical o lumbar."],"correct":2,"e":"La lordosis es la curvatura fisiológica de la columna en las zonas cervical y lumbar. La curva dorsal es la cifosis y la desviación en S o C, la escoliosis."},
  {"id":"ANA-T5-13","subject":"anato","exam":"Tema 5","text":"La caja torácica está constituida por:","options":["Las vértebras dorsales en la parte posterior y las costillas en la zona lateral.","El esternón en la parte ventral del tórax.","Ambas respuestas son correctas."],"correct":2,"e":"La caja torácica la forman las vértebras dorsales por detrás, las costillas a los lados y el esternón por delante."},
  {"id":"ANA-T5-14","subject":"anato","exam":"Tema 5","text":"Los huesos que constituyen la cintura escapular son:","options":["Húmero.","Omóplato y clavícula.","Radio y cúbito."],"correct":1,"e":"La cintura escapular la forman el omóplato (escápula) y la clavícula."},
  {"id":"ANA-T5-15","subject":"anato","exam":"Tema 5","text":"El escafoides se encuentra localizado en:","options":["El carpo.","En las falanges.","En la columna vertebral."],"correct":0,"e":"El escafoides es uno de los huesos del carpo (la muñeca). También hay un escafoides en el tarso del pie."},
  {"id":"ANA-T5-16","subject":"anato","exam":"Tema 5","text":"Los tendones:","options":["Son haces de fibras de tejido conjuntivo resistente.","Están formados por fibras musculares.","Son la parte activa del aparato locomotor."],"correct":0,"e":"Los tendones son haces de tejido conjuntivo fibroso y muy resistente que unen los músculos a los huesos."},
  {"id":"ANA-T5-17","subject":"anato","exam":"Tema 5","text":"Según la dimensión y la forma de los músculos pueden ser:","options":["Largos, cortos, orbiculares y anchos.","Flexores y extensores.","Bíceps, tríceps y cuádriceps."],"correct":0,"e":"Por su forma y tamaño, los músculos pueden ser largos, cortos, anchos u orbiculares. Flexor y extensor es una clasificación por función."},
  {"id":"ANA-T5-18","subject":"anato","exam":"Tema 5","text":"Los maseteros son músculos:","options":["De párpados y cejas.","Masticadores.","Que se originan en las fosas temporales."],"correct":1,"e":"Los maseteros son los músculos que cierran la mandíbula al masticar."},
  {"id":"ANA-T5-19","subject":"anato","exam":"Tema 5","text":"El esternocleidomastoideo:","options":["Realiza movimientos de flexión, inclinación y rotación del cuello.","Se encarga de elevar la cabeza y el cuello.","Contribuye con la inspiración y movimientos laterales del cuello."],"correct":0,"e":"El esternocleidomastoideo flexiona, inclina y rota el cuello."},
  {"id":"ANA-T5-20","subject":"anato","exam":"Tema 5","text":"La artritis significa:","options":["Inflamación de las articulaciones.","Disminución de la densidad ósea.","Degeneración del cartílago articular."],"correct":0,"e":"Artritis significa inflamación de una articulación. La pérdida de densidad ósea es la osteoporosis y la degeneración del cartílago, la artrosis."},
  {"id":"SOS-T1-1","subject":"soste","exam":"Tema 1","text":"El crecimiento económico siempre es contrario a la sostenibilidad.","options":["Verdadero.","Falso."],"correct":1,"e":"Falso: el crecimiento económico puede ser compatible con la sostenibilidad si respeta los límites sociales y ambientales."},
  {"id":"SOS-T1-2","subject":"soste","exam":"Tema 1","text":"¿Cuál de estos aspectos NO está incluido en la \"S\" de ASG?","options":["Diversidad e inclusión.","Relación con comunidades locales.","Cambio climático."],"correct":2,"e":"La S de ASG es el criterio social (diversidad, comunidades, derechos laborales). El cambio climático pertenece a la A, el criterio ambiental."},
  {"id":"SOS-T1-3","subject":"soste","exam":"Tema 1","text":"¿Qué busca la sostenibilidad social?","options":["Reducir el uso de recursos naturales.","Aumentar la rentabilidad económica.","Fortalecer la cohesión y estabilidad de las poblaciones."],"correct":2,"e":"La sostenibilidad social busca fortalecer la cohesión y la estabilidad de las poblaciones."},
  {"id":"SOS-T1-4","subject":"soste","exam":"Tema 1","text":"¿Cuál es la finalidad de los criterios ASG?","options":["Evaluar únicamente los resultados financieros de una empresa.","Orientar a la sociedad y a los inversores sobre la sostenibilidad empresarial.","Medir el crecimiento económico sin considerar el impacto social o ambiental."],"correct":1,"e":"Los criterios ASG orientan a la sociedad y a los inversores sobre lo sostenible que es una empresa, más allá de sus resultados financieros."},
  {"id":"SOS-T1-5","subject":"soste","exam":"Tema 1","text":"¿Qué es la Inversión Socialmente Responsable (ISR)?","options":["Una inversión que solo considera factores financieros de rentabilidad.","Una inversión que incorpora factores éticos, sociales y ambientales en el proceso de toma de decisiones.","Una inversión centrada solo en la rentabilidad a corto plazo."],"correct":1,"e":"La ISR tiene en cuenta factores éticos, sociales y ambientales, además de la rentabilidad, al decidir dónde invertir."},
  {"id":"SOS-T1-6","subject":"soste","exam":"Tema 1","text":"La contaminación es una de las principales causas de enfermedades, pero no guarda relación con la salud mental.","options":["Verdadero.","Falso."],"correct":1,"e":"Falso: la contaminación afecta a la salud física y también a la salud mental."},
  {"id":"SOS-T1-7","subject":"soste","exam":"Tema 1","text":"¿Cuál de los siguientes problemas se considera principalmente de tipo social?","options":["Contaminación.","Pérdida de biodiversidad.","Superpoblación."],"correct":2,"e":"La superpoblación es sobre todo un problema social. La contaminación y la pérdida de biodiversidad son problemas ambientales."},
  {"id":"SOS-T1-8","subject":"soste","exam":"Tema 1","text":"Las mayores emisiones de GEI se producen en:","options":["Industria.","Generación de energía eléctrica.","Transporte."],"correct":2,"e":"Según el temario, el transporte es el sector con mayores emisiones de gases de efecto invernadero."},
  {"id":"SOS-T1-9","subject":"soste","exam":"Tema 1","text":"¿Qué tipo de soluciones implican las NET (Negative Emissions Technologies)?","options":["Soluciones tecnológicas para la captura de carbono.","Soluciones relacionadas con la reducción de emisiones de vehículos.","Soluciones naturales como la reforestación."],"correct":0,"e":"Las NET son soluciones tecnológicas para capturar y almacenar carbono. La reforestación es una solución natural."},
  {"id":"SOS-T1-10","subject":"soste","exam":"Tema 1","text":"¿Cuál es el objetivo de la sostenibilidad según los criterios aplicados por la UE?","options":["Satisfacer las necesidades actuales sin comprometer las capacidades de las generaciones futuras.","Garantizar un equilibrio entre el crecimiento económico, la cohesión social y la protección medioambiental.","Ambas son correctas."],"correct":2,"e":"La UE entiende la sostenibilidad como satisfacer las necesidades actuales sin comprometer las futuras y equilibrar economía, sociedad y medio ambiente, así que ambas son correctas."},
  {"id":"SOS-T1-11","subject":"soste","exam":"Tema 1","text":"¿En qué documento apareció por primera vez la definición de sostenibilidad en el ámbito de la UE?","options":["Acuerdo de París.","Informe Brundtland.","Marco de Sendai."],"correct":1,"e":"El Informe Brundtland (1987) fue el primero en definir el desarrollo sostenible."},
  {"id":"SOS-T1-12","subject":"soste","exam":"Tema 1","text":"La Agenda 2030:","options":["Es el marco que tiene como objetivo reducir las amenazas, tanto naturales como humanas.","Es un marco que busca promover la prosperidad, la igualdad y la paz en todo el mundo.","Es un acuerdo a nivel nacional que busca estudiar y reducir los riesgos del cambio climático."],"correct":1,"e":"La Agenda 2030 de la ONU busca promover la prosperidad, la igualdad y la paz en todo el mundo. La A describe el Marco de Sendai."},
  {"id":"SOS-T1-13","subject":"soste","exam":"Tema 1","text":"¿Cuántos ODS se han establecido?","options":["8.","17.","16."],"correct":1,"e":"La Agenda 2030 fija 17 Objetivos de Desarrollo Sostenible (ODS)."},
  {"id":"SOS-T1-14","subject":"soste","exam":"Tema 1","text":"¿Qué son los ESG o ASG?","options":["Son indicadores que evalúan la actuación empresarial más allá de los resultados financieros.","Indicadores que orientan tanto a la sociedad como a los inversores sobre aspectos financieros de una empresa.","Son normativas legales que todas las empresas deben cumplir obligatoriamente."],"correct":0,"e":"Los criterios ESG o ASG valoran la actuación ambiental, social y de gobierno de una empresa, más allá de sus resultados financieros."},
  {"id":"SOS-T1-15","subject":"soste","exam":"Tema 1","text":"Las emisiones principales de gases de efecto invernadero por actividades humanas son:","options":["Dióxido de carbono y metano.","Vapor de agua y óxido nitroso.","Metano y ozono."],"correct":0,"e":"El dióxido de carbono y el metano son los principales gases de efecto invernadero que emiten las actividades humanas."},
  {"id":"SOS-T1-16","subject":"soste","exam":"Tema 1","text":"La superpoblación:","options":["Es un fenómeno en el que la Tierra no puede generar los recursos utilizados por la población mundial para cada año.","Se refiere únicamente al crecimiento poblacional en los países desarrollados.","Se refiere a la abundancia de recursos disponibles para toda la población mundial."],"correct":0,"e":"La superpoblación se da cuando la Tierra no puede regenerar cada año los recursos que consume la población mundial."},
  {"id":"SOS-T1-17","subject":"soste","exam":"Tema 1","text":"¿Qué actividad humana es responsable de la liberación de gases y polvos tóxicos que afectan la contaminación del aire?","options":["Actividad industrial.","Deforestación.","Reciclaje de residuos."],"correct":0,"e":"La actividad industrial libera gases y partículas tóxicas que contaminan el aire."},
  {"id":"SOS-T1-18","subject":"soste","exam":"Tema 1","text":"El sector que tiene un peso mayor y que representa casi un tercio de las emisiones es el:","options":["Transporte.","Industrial.","Agricultura y ganadería."],"correct":0,"e":"Según el temario, el transporte es el sector que más pesa y supone casi un tercio de las emisiones."},
  {"id":"SOS-T1-19","subject":"soste","exam":"Tema 1","text":"¿Qué ODS plantea la importancia de las alianzas globales frente a los retos ambientales?","options":["ODS 5.","ODS 16.","ODS 17."],"correct":2,"e":"El ODS 17, «Alianzas para lograr los objetivos», destaca la cooperación global frente a los retos."},
  {"id":"SOS-T1-20","subject":"soste","exam":"Tema 1","text":"Sostenibilidad que busca fortalecer la cohesión y estabilidad de las poblaciones y su desarrollo vital.","options":["Ambiental.","Económica.","Social."],"correct":2,"e":"La sostenibilidad social es la que busca la cohesión, la estabilidad y el desarrollo vital de las poblaciones."},
  {"id":"SOS-T1-21","subject":"soste","exam":"Tema 1","text":"La sigla A en el término ASG se refiere, entre otras, a una de las siguientes situaciones, señala la correcta.","options":["Derechos humanos.","Recursos naturales.","Estructura y buen gobierno de la empresa."],"correct":1,"e":"La A de ASG es el criterio ambiental, que incluye el uso de los recursos naturales. Los derechos humanos son la S y el buen gobierno, la G."},
  {"id":"SOS-T1-22","subject":"soste","exam":"Tema 1","text":"Poner fin al hambre, la malnutrición, duplicar la productividad agrícola sin dañar a los ecosistemas y adaptarse al cambio climático está englobado en el:","options":["Objetivo 2: Hambre cero.","Objetivo 3, salud y bienestar.","Objetivo 1, sobre el fin de la pobreza."],"correct":0,"e":"El ODS 2, «Hambre cero», busca acabar con el hambre y la malnutrición y lograr una agricultura sostenible."},
  {"id":"SOS-T1-23","subject":"soste","exam":"Tema 1","text":"El GRI es:","options":["Una iniciativa para elaborar informes de sostenibilidad para las empresas.","Una herramienta que evalúa el impacto ambiental de un producto, proceso o servicio a lo largo de su ciclo de vida, desde la extracción de materias primas hasta su eliminación.","Una organización sin ánimo de lucro cuyo objetivo es desarrollar normas de contabilidad de sostenibilidad."],"correct":0,"e":"La GRI (Global Reporting Initiative) es una iniciativa para que las empresas elaboren informes de sostenibilidad. La B describe el análisis de ciclo de vida."},
  {"id":"SOS-T1-24","subject":"soste","exam":"Tema 1","text":"El concepto de ISR:","options":["Se refiere a inversionistas que buscan maximizar las ganancias económicas sin importar el impacto social o ambiental.","Incorpora criterios éticos, sociales y ambientales para tomar decisiones.","Consiste en invertir únicamente en empresas con altos rendimientos financieros."],"correct":1,"e":"La Inversión Socialmente Responsable incorpora criterios éticos, sociales y ambientales a las decisiones de inversión."},
  {"id":"SOS-T1-25","subject":"soste","exam":"Tema 1","text":"La eutrofización provoca:","options":["Deforestación.","Aceleración excesiva en el crecimiento de algas y plantas.","Acidificación de los océanos."],"correct":1,"e":"La eutrofización es el exceso de nutrientes en el agua, que provoca un crecimiento descontrolado de algas y plantas."},
  {"id":"SOS-T1-26","subject":"soste","exam":"Tema 1","text":"Los biocombustibles:","options":["Son una alternativa a los combustibles fósiles para la reducción de emisiones.","Son más contaminantes que los combustibles fósiles.","Son más baratos que los combustibles fósiles."],"correct":0,"e":"Los biocombustibles son una alternativa a los combustibles fósiles para reducir emisiones."},
  {"id":"SOS-T1-27","subject":"soste","exam":"Tema 1","text":"¿Cuál de las siguientes es una solución natural para la absorción de gases de efecto invernadero (GEI)?","options":["La captura de carbono mediante tecnología industrial.","La reforestación y conservación de bosques.","La geoingeniería solar."],"correct":1,"e":"Reforestar y conservar los bosques es una solución natural: los árboles absorben CO2 de la atmósfera."},
  {"id":"SOS-T1-28","subject":"soste","exam":"Tema 1","text":"¿Cuál es una característica de las soluciones tecnológicas (NET) para la captura de carbono?","options":["Están completamente desarrolladas.","Son económicamente accesibles para todos los sectores.","Aún no están completamente desarrolladas y son caras."],"correct":2,"e":"Las tecnologías de captura de carbono (NET) todavía no están totalmente desarrolladas y son caras."},
  {"id":"SOS-T1-29","subject":"soste","exam":"Tema 1","text":"La alianza global para afrontar los retos ambientales:","options":["Únicamente es responsabilidad de los gobiernos.","Requiere la colaboración entre entidades públicas, privadas y ONGs.","Implica la participación de los países desarrollados, excluyendo los que estén en vías de desarrollo."],"correct":1,"e":"Afrontar los retos ambientales exige colaborar entre administraciones, empresas y ONG de todos los países."},
  {"id":"EMP-15","subject":"emple1","exam":"Habilidades y acceso al empleo","text":"Señala la opción correcta:","options":["El acceso al mundo laboral depende exclusivamente de la experiencia previa en un puesto de trabajo.","Poseer ciertas habilidades interpersonales es un requisito que se pide en las ofertas de empleo.","El nivel de conocimientos en informática no es relevante para la mayoría de los puestos de trabajo."],"correct":1,"e":"Las ofertas de empleo piden cada vez más habilidades interpersonales (comunicación, trabajo en equipo). La experiencia no es lo único y la informática sí es relevante."},
  {"id":"EMP-16","subject":"emple1","exam":"Habilidades y acceso al empleo","text":"El acceso a los cuerpos de funcionarios de carrera se realiza de acuerdo con la titulación exigida.","options":["Verdadero","Falso"],"correct":0,"e":"Verdadero: los cuerpos de funcionarios se clasifican en grupos según la titulación que se exige para entrar en ellos."},
  {"id":"EMP-17","subject":"emple1","exam":"Habilidades y acceso al empleo","text":"¿Qué se entiende por asertividad?","options":["Capacidad de expresar y defender opiniones de forma constructiva y respetuosa.","Capacidad para afrontar y responder de manera efectiva a los cambios o imprevistos en el entorno.","Capacidad de comunicar y compartir nuestras emociones con los demás."],"correct":0,"e":"La asertividad es expresar y defender tus opiniones de forma clara, constructiva y respetuosa. La B describe la adaptabilidad."},
  {"id":"EMP-18","subject":"emple1","exam":"Habilidades y acceso al empleo","text":"¿Cuál de los siguientes grupos de clasificación de funcionarios requiere la titulación de Licenciatura, Ingeniería o Arquitectura?","options":["Subgrupo A1.","Grupo B.","Grupo C."],"correct":0,"e":"El subgrupo A1 exige título universitario de licenciatura, ingeniería, arquitectura o grado equivalente."},
  {"id":"EMP-19","subject":"emple1","exam":"Habilidades y acceso al empleo","text":"¿Cuál de las siguientes NO es una habilidad blanda o soft skill?","options":["Inteligencia emocional.","Capacidad de liderazgo.","Conocimiento en programación de software."],"correct":2,"e":"Programar es una habilidad técnica (hard skill). La inteligencia emocional y el liderazgo son habilidades blandas."},
  {"id":"EMP-20","subject":"emple1","exam":"Habilidades y acceso al empleo","text":"¿Qué sector económico tiene mayor peso en la economía española?","options":["Sector primario.","Sector secundario.","Sector terciario."],"correct":2,"e":"El sector terciario (servicios: comercio, turismo, sanidad, educación…) es el que más pesa en la economía española."},
  {"id":"EMP-21","subject":"emple1","exam":"Habilidades y acceso al empleo","text":"¿Qué sector se basa en la investigación, el desarrollo y la innovación?","options":["Sector cuaternario.","Sector terciario.","Sector secundario."],"correct":0,"e":"El sector cuaternario agrupa las actividades basadas en el conocimiento: investigación, desarrollo e innovación (I+D+i)."},
  {"id":"EMP-22","subject":"emple1","exam":"Habilidades y acceso al empleo","text":"¿Qué acción es parte de la búsqueda activa de empleo?","options":["Esperar a que lleguen ofertas de trabajo.","Utilizar herramientas y estrategias efectivas para encontrar oportunidades.","Mantenerse en un solo sector sin explorar otras áreas."],"correct":1,"e":"Buscar empleo de forma activa es usar herramientas y estrategias para encontrar oportunidades, no esperar a que lleguen."},
  {"id":"EMP-23","subject":"emple1","exam":"Habilidades y acceso al empleo","text":"¿Cuál es una de las habilidades interpersonales más importantes en el mercado laboral actual?","options":["Capacidad para imponer sus opiniones.","Inteligencia emocional.","Priorizar el éxito individual sobre el éxito del equipo."],"correct":1,"e":"La inteligencia emocional (gestionar las propias emociones y entender las ajenas) es una de las habilidades más valoradas hoy."},
  {"id":"EMP-24","subject":"emple1","exam":"Habilidades y acceso al empleo","text":"¿Cuál de las siguientes NO se considera una habilidad interpersonal?","options":["Conocimientos técnicos en programación.","Empatía.","Resolución de conflictos."],"correct":0,"e":"Los conocimientos de programación son técnicos. La empatía y la resolución de conflictos son habilidades interpersonales."},
  {"id":"EMP-25","subject":"emple1","exam":"Habilidades y acceso al empleo","text":"El personal empleado público NO incluye:","options":["Funcionarios de carrera.","Personal eventual.","Trabajadores autónomos."],"correct":2,"e":"El personal empleado público lo forman funcionarios de carrera, interinos, personal laboral y eventual. Los autónomos trabajan por cuenta propia."},
  {"id":"EMP-26","subject":"emple1","exam":"Habilidades y acceso al empleo","text":"¿Qué se entiende por \"promoción interna\" en el ámbito de la Función Pública?","options":["El ascenso de un funcionario dentro de la misma categoría o cuerpo.","La contratación de personal laboral externo.","El paso de un funcionario a un puesto en el sector privado."],"correct":0,"e":"La promoción interna es el ascenso del funcionario dentro de la Administración, a otra categoría o cuerpo."},
  {"id":"EMP-27","subject":"emple1","exam":"Habilidades y acceso al empleo","text":"¿Qué titulación se exige para acceder al Subgrupo A1 de la función pública?","options":["Formación Profesional de Grado Superior.","Licenciatura, Ingeniería o equivalente.","Título de ESO."],"correct":1,"e":"Para el subgrupo A1 se exige licenciatura, ingeniería o título universitario equivalente."},
  {"id":"EMP-28","subject":"emple1","exam":"Habilidades y acceso al empleo","text":"¿Qué es la resiliencia?","options":["La capacidad de adquirir conocimientos técnicos rápidamente.","La capacidad de adaptarse a situaciones difíciles y superar la adversidad.","La capacidad de defender opiniones y pensamientos de forma constructiva."],"correct":1,"e":"La resiliencia es la capacidad de adaptarse a situaciones difíciles y salir adelante tras la adversidad."},
  {"id":"EMP-29","subject":"emple1","exam":"Habilidades y acceso al empleo","text":"Las habilidades blandas:","options":["También conocidas como hard skills, mejoran la productividad laboral.","Son conocimientos técnicos adquiridos durante la formación.","Son habilidades interpersonales que nos permiten relacionarnos con el entorno."],"correct":2,"e":"Las habilidades blandas (soft skills) son las interpersonales, las que nos permiten relacionarnos. Los conocimientos técnicos son hard skills."},
  {"id":"EMP-30","subject":"emple1","exam":"Habilidades y acceso al empleo","text":"¿Qué sector incluye actividades como la educación o la sanidad?","options":["Sector primario.","Sector secundario.","Sector terciario."],"correct":2,"e":"La educación y la sanidad son servicios, por lo que pertenecen al sector terciario."},
  {"id":"EMP-31","subject":"emple1","exam":"Habilidades y acceso al empleo","text":"La empatía es la capacidad de:","options":["Saber comunicarse con eficacia.","Mostrar comprensión hacia los sentimientos y preocupaciones de otros.","Tomar decisiones de forma independiente."],"correct":1,"e":"La empatía es ponerse en el lugar del otro y comprender sus sentimientos y preocupaciones."},
  {"id":"EMP-32","subject":"emple1","exam":"Habilidades y acceso al empleo","text":"¿Qué objetivo persiguen las acciones de inserción laboral?","options":["Aumentar la formación de los empleados en la empresa.","Mejorar la competitividad de las empresas en el mercado.","Integrar y acompañar a colectivos con dificultades al mercado laboral."],"correct":2,"e":"Las acciones de inserción laboral ayudan a colectivos con dificultades a entrar en el mercado de trabajo y los acompañan en el proceso."},
  {"id":"EMP-33","subject":"emple1","exam":"Habilidades y acceso al empleo","text":"En relación a las ofertas de empleo NO es cierto que:","options":["La capacidad de adaptación es una habilidad requerida hoy en día.","Es necesario poseer estudios de postgrado para cualquier puesto.","Poseer un nivel informático básico es relevante para la mayoría de los puestos de trabajo."],"correct":1,"e":"No es cierto que haga falta un postgrado para cualquier puesto. La adaptabilidad y la informática básica sí se piden en la mayoría."},
  {"id":"EMP-34","subject":"emple1","exam":"Habilidades y acceso al empleo","text":"¿Qué incluye el personal empleado público en España?","options":["Funcionarios de carrera y voluntarios.","Funcionarios de carrera, interinos, personal laboral y eventual.","Exclusivamente funcionarios de carrera y personal eventual."],"correct":1,"e":"El personal empleado público incluye funcionarios de carrera, interinos, personal laboral y personal eventual."},
  {"id":"EMP-35","subject":"emple1","exam":"Habilidades y acceso al empleo","text":"¿Cuál de los siguientes requisitos NO es necesario para acceder al empleo público?","options":["Tener experiencia laboral previa en el sector público.","Superar las pruebas selectivas.","Pagar la tasa correspondiente, salvo excepción."],"correct":0,"e":"Para acceder al empleo público no se exige experiencia previa en el sector público. Sí hay que superar las pruebas y, salvo excepciones, pagar la tasa."},
  {"id":"EMP-36","subject":"emple1","exam":"Habilidades y acceso al empleo","text":"¿Qué título se requiere para acceder al grupo B en la Función Pública?","options":["Licenciatura o equivalente.","Título de Formación Profesional de Grado Superior.","Título de Bachillerato."],"correct":1,"e":"Para el grupo B se exige el título de Técnico Superior de Formación Profesional."},
  {"id":"EMP-37","subject":"emple1","exam":"Habilidades y acceso al empleo","text":"¿Qué son las \"hard skills\"?","options":["Conocimientos técnicos adquiridos durante la formación.","Habilidades relacionadas con la creatividad.","Habilidades interpersonales."],"correct":0,"e":"Las hard skills son los conocimientos técnicos adquiridos con la formación y la experiencia."},
  {"id":"EMP-38","subject":"emple1","exam":"Habilidades y acceso al empleo","text":"¿Cuál de las siguientes habilidades interpersonales se relaciona con la capacidad de defender opiniones y pensamientos de forma constructiva?","options":["Asertividad.","Empatía.","Lealtad."],"correct":0,"e":"La asertividad es la habilidad de defender tus opiniones y pensamientos de forma constructiva."},
  {"id":"EMP-39","subject":"emple1","exam":"Habilidades y acceso al empleo","text":"En el mercado laboral actual:","options":["Su acceso depende exclusivamente de la experiencia previa en un puesto de trabajo.","Es importante encontrar un equilibrio entre habilidades técnicas e interpersonales.","Las habilidades técnicas son más importantes que las habilidades interpersonales."],"correct":1,"e":"Hoy se valora un equilibrio entre habilidades técnicas e interpersonales; ninguna basta por sí sola."},
  {"id":"EMP-40","subject":"emple1","exam":"Prevención de riesgos laborales","text":"La prevención es el conjunto de medidas que se adoptan una vez que se ha detectado el peligro.","options":["Verdadero","Falso"],"correct":1,"e":"Falso: la prevención actúa antes, con medidas para evitar o reducir los riesgos en todas las fases de la actividad, no cuando el peligro ya se ha detectado."},
  {"id":"EMP-41","subject":"emple1","exam":"Prevención de riesgos laborales","text":"¿Qué factor NO está relacionado con las condiciones de seguridad en un puesto de trabajo?","options":["El orden, limpieza y mantenimiento general de todas las instalaciones.","El manejo de equipos de trabajo.","La falta de personal en la empresa."],"correct":2,"e":"Las condiciones de seguridad tienen que ver con instalaciones, orden, limpieza y equipos de trabajo. La falta de personal es un factor organizativo."},
  {"id":"EMP-42","subject":"emple1","exam":"Prevención de riesgos laborales","text":"La vigilancia de la salud de los trabajadores no es una obligación del empresario.","options":["Verdadero","Falso"],"correct":1,"e":"Falso: la Ley de Prevención de Riesgos Laborales obliga al empresario a garantizar la vigilancia periódica de la salud de sus trabajadores."},
  {"id":"EMP-43","subject":"emple1","exam":"Prevención de riesgos laborales","text":"¿En cuál de los siguientes casos el reconocimiento médico de la vigilancia de la salud NO es obligatorio, sino voluntario?","options":["Ana trabaja en un laboratorio donde se manipulan productos químicos y la normativa exige exámenes médicos periódicos.","Juan es administrativo en una oficina; su estado de salud no constituye un peligro y no existe normativa específica que exija el examen.","Marcos trabaja en un hospital, ha estado en contacto con pacientes con enfermedades infecciosas y existe riesgo de contagio."],"correct":1,"e":"El reconocimiento médico es voluntario salvo que la normativa lo exija o que la salud del trabajador suponga un riesgo. En el caso de Juan no se da ninguna de las dos cosas."},
  {"id":"EMP-44","subject":"emple1","exam":"Prevención de riesgos laborales","text":"¿Qué actuación es incorrecta en caso de una quemadura?","options":["Cubrir la quemadura con gasas estériles.","Valorar la gravedad de las quemaduras.","Aplicar apósitos de papel."],"correct":2,"e":"Los apósitos de papel o algodón se pegan a la quemadura y no deben usarse. Se cubre con gasas estériles tras valorar la gravedad."},
  {"id":"EMP-45","subject":"emple1","exam":"Prevención de riesgos laborales","text":"Si una persona tiene una obstrucción incompleta, se debe golpear la espalda para facilitar la salida del cuerpo extraño.","options":["Verdadero","Falso"],"correct":1,"e":"Falso: si la obstrucción es incompleta y la persona puede toser, se le anima a toser. Los golpes en la espalda se reservan para cuando la tos deja de ser eficaz."},
  {"id":"EMP-46","subject":"emple1","exam":"Prevención de riesgos laborales","text":"El ruido en el entorno de trabajo es un agente contaminante, ¿de qué tipo?","options":["Agente biológico.","Agente químico.","Agente físico."],"correct":2,"e":"El ruido es un agente físico, igual que las vibraciones, la temperatura o las radiaciones."},
  {"id":"EMP-47","subject":"emple1","exam":"Prevención de riesgos laborales","text":"¿Qué afirmación sobre los equipos de protección individual es correcta?","options":["Tienen como objetivo la protección simultánea de varios trabajadores.","Son la primera opción de protección ante cualquier riesgo.","Son la última barrera entre el trabajador y el riesgo al que está expuesto."],"correct":2,"e":"Los EPI protegen a un solo trabajador y son la última barrera: se usan cuando el riesgo no se puede eliminar ni controlar con medidas colectivas."},
  {"id":"EMP-48","subject":"emple1","exam":"Prevención de riesgos laborales","text":"¿En qué empresas debe constituirse el comité de seguridad y salud?","options":["En empresas con 50 o más trabajadores.","En todas las empresas independientemente de su tamaño.","Solo en empresas con menos de 50 trabajadores."],"correct":0,"e":"El comité de seguridad y salud es obligatorio en empresas o centros con 50 o más trabajadores."},
  {"id":"EMP-49","subject":"emple1","exam":"Prevención de riesgos laborales","text":"¿Cómo define la Ley 31/1995 el concepto de \"riesgo laboral\"?","options":["La posibilidad de que un trabajador sufra un daño derivado de su trabajo.","Enfermedad, patología o lesiones sufridas con motivo u ocasión del trabajo.","La existencia de agentes contaminantes en el lugar de trabajo."],"correct":0,"e":"La Ley 31/1995 define el riesgo laboral como la posibilidad de que un trabajador sufra un daño derivado del trabajo. La B describe el daño."},
  {"id":"EMP-50","subject":"emple1","exam":"Prevención de riesgos laborales","text":"¿Cuál de los siguientes elementos NO se considera una \"condición de trabajo\"?","options":["La organización de la jornada laboral.","Las características del entorno físico donde se desarrolla la actividad.","La categoría profesional asignada al trabajador."],"correct":2,"e":"Son condiciones de trabajo las características que influyen en la seguridad y la salud (entorno, organización, carga). La categoría profesional no lo es."},
  {"id":"EMP-51","subject":"emple1","exam":"Prevención de riesgos laborales","text":"Los virus son agentes contaminantes:","options":["Biológicos.","Físicos.","Químicos."],"correct":0,"e":"Virus, bacterias, hongos y parásitos son agentes contaminantes biológicos."},
  {"id":"EMP-52","subject":"emple1","exam":"Prevención de riesgos laborales","text":"¿Qué se entiende por \"accidente de trabajo\" según la Ley General de la Seguridad Social?","options":["Todo incidente que ocurra en el lugar de trabajo, independientemente de su causa.","Toda lesión corporal que el trabajador sufra con ocasión o por consecuencia del trabajo que ejecute por cuenta ajena.","Cualquier lesión que el trabajador sufra en su vida cotidiana, aunque no esté relacionada con su actividad laboral."],"correct":1,"e":"Accidente de trabajo es toda lesión corporal que sufre el trabajador por cuenta ajena con ocasión o como consecuencia de su trabajo."},
  {"id":"EMP-53","subject":"emple1","exam":"Prevención de riesgos laborales","text":"¿Cuál es el objetivo principal de las técnicas de prevención en el entorno laboral?","options":["Reducir las consecuencias de los riesgos una vez que se materializan.","Detectar y eliminar los factores de riesgo laboral.","Actuar sobre los trabajadores para que se adapten a los riesgos existentes."],"correct":1,"e":"Las técnicas de prevención buscan detectar y eliminar los factores de riesgo antes de que causen daño."},
  {"id":"EMP-54","subject":"emple1","exam":"Prevención de riesgos laborales","text":"Una patología inespecífica es:","options":["Aquella en la que se da una relación causa-efecto entre el trabajo.","Aquella en la que influyen otros factores no laborales.","Cualquier patología recogida en el cuadro de Enfermedades Profesionales."],"correct":1,"e":"Una patología inespecífica es la que, además del trabajo, tiene otros factores no laborales que influyen en su aparición."},
  {"id":"EMP-55","subject":"emple1","exam":"Prevención de riesgos laborales","text":"¿Cuál de los siguientes es un derecho de los trabajadores en materia de prevención de riesgos laborales?","options":["Derecho a recibir formación e información sobre los riesgos laborales.","Derecho al incumplimiento de sus obligaciones sin justificación.","Derecho a decidir libremente si usa o no los equipos de protección individual."],"correct":0,"e":"El trabajador tiene derecho a recibir formación e información sobre los riesgos de su puesto. Usar los EPI es una obligación, no algo opcional."},
  {"id":"EMP-56","subject":"emple1","exam":"Prevención de riesgos laborales","text":"Los trabajadores pueden participar en cuestiones de prevención de riesgos a través de:","options":["Delegados de prevención.","El comité de seguridad y salud.","Ambas son correctas."],"correct":2,"e":"Los trabajadores participan en prevención a través de los delegados de prevención y del comité de seguridad y salud."},
  {"id":"EMP-57","subject":"emple1","exam":"Prevención de riesgos laborales","text":"¿Cuál es el principal objetivo de la vigilancia de la salud en el entorno laboral?","options":["Detectar posibles daños derivados de las condiciones de trabajo y mejorar la salud de los trabajadores.","Garantizar que los trabajadores reciban formación en prevención de riesgos laborales.","Supervisar a los trabajadores en sus tareas diarias."],"correct":0,"e":"La vigilancia de la salud sirve para detectar a tiempo daños causados por las condiciones de trabajo y mejorar la salud de la plantilla."},
  {"id":"EMP-58","subject":"emple1","exam":"Prevención de riesgos laborales","text":"¿Qué son las técnicas de primeros auxilios?","options":["La atención médica especializada proporcionada por los servicios de emergencia.","Las acciones que permiten la atención inmediata de un accidentado en el lugar del incidente antes de la llegada de personal especializado.","Las técnicas que solo pueden ser aplicadas por personal sanitario."],"correct":1,"e":"Los primeros auxilios son la atención inmediata al accidentado en el lugar del suceso hasta que llega personal especializado."},
  {"id":"EMP-59","subject":"emple1","exam":"Prevención de riesgos laborales","text":"¿Cuál de las siguientes afirmaciones sobre el concepto de \"prevención\" es correcta?","options":["Es la adopción de medidas y actividades en todas las fases de la empresa para evitar o disminuir los riesgos laborales.","Es la evaluación de los riesgos una vez ocurrido un accidente de trabajo.","Solo se aplica a trabajos peligrosos o de alto riesgo."],"correct":0,"e":"La prevención es el conjunto de medidas en todas las fases de la actividad de la empresa para evitar o reducir los riesgos laborales."},
  {"id":"EMP-60","subject":"emple1","exam":"Prevención de riesgos laborales","text":"Representa un factor de riesgo derivado de la carga de trabajo:","options":["La exposición a temperaturas extremas en el lugar de trabajo.","La falta de señalización de salidas de emergencia.","Una postura inadecuada en el trabajo."],"correct":2,"e":"Las posturas inadecuadas son un factor de carga de trabajo (física). La temperatura es un agente físico y la señalización, una condición de seguridad."},
  {"id":"EMP-61","subject":"emple1","exam":"Prevención de riesgos laborales","text":"¿Cuál de los siguientes requisitos NO es necesario para que un accidente se considere accidente de trabajo?","options":["Que el trabajador sufra una lesión corporal.","Que el trabajador esté contratado por cuenta ajena.","Que ocurra siempre en el lugar de trabajo."],"correct":2,"e":"No hace falta que ocurra en el lugar de trabajo: también cuentan, por ejemplo, el accidente in itinere o el sufrido en una misión fuera del centro."},
  {"id":"EMP-62","subject":"emple1","exam":"Prevención de riesgos laborales","text":"¿Cuál de los siguientes casos NO se considera un accidente de trabajo?","options":["Un accidente ocurrido durante la realización de una tarea distinta a la categoría profesional del trabajador, por orden del empresario.","Una enfermedad que el trabajador ya padecía, pero que se agrava tras un accidente de trabajo.","Una lesión causada por un acto de imprudencia temeraria del trabajador."],"correct":2,"e":"La imprudencia temeraria del trabajador excluye que se considere accidente de trabajo. Los otros dos casos sí se consideran."},
  {"id":"EMP-63","subject":"emple1","exam":"Prevención de riesgos laborales","text":"¿Cuál de las siguientes afirmaciones es una obligación de los trabajadores en materia de prevención de riesgos laborales?","options":["Utilizar correctamente los equipos de protección facilitados por la empresa.","Usar los equipos de protección únicamente si el riesgo es evidente.","Reparar por su cuenta las máquinas que presenten fallos de seguridad."],"correct":0,"e":"El trabajador debe usar correctamente los equipos de protección que le da la empresa. Si una máquina falla, debe avisar, no repararla él."},
  {"id":"EMP-64","subject":"emple1","exam":"Prevención de riesgos laborales","text":"¿Qué tipo de medida de protección tiene prioridad según los principios de la acción preventiva?","options":["Las medidas de protección individual.","Las medidas de protección colectiva.","Ambas tienen la misma prioridad."],"correct":1,"e":"Según la Ley de Prevención, la protección colectiva tiene prioridad sobre la individual."},
  {"id":"EMP-65","subject":"emple1","exam":"Prevención de riesgos laborales","text":"¿Cuál de los siguientes ejemplos corresponde a una medida de protección colectiva?","options":["El uso de casco de protección.","La instalación de barandillas para evitar caídas desde altura.","El uso de gafas de protección en una zona de trabajo."],"correct":1,"e":"Una barandilla protege a todos los que trabajan en la zona, por eso es protección colectiva. El casco y las gafas son EPI."},
  {"id":"EMP-66","subject":"emple1","exam":"Prevención de riesgos laborales","text":"¿Qué trabajadores tienen derecho a participar en cuestiones de prevención de riesgos laborales?","options":["Solo los delegados de prevención.","Todos los trabajadores a través de sus representantes.","Solo los trabajadores designados por la dirección de la empresa."],"correct":1,"e":"Todos los trabajadores tienen derecho a participar en la prevención, normalmente a través de sus representantes."},
  {"id":"EMP-67","subject":"emple1","exam":"Prevención de riesgos laborales","text":"¿Qué elemento debe estar presente obligatoriamente en todo lugar de trabajo?","options":["Un desfibrilador automático.","Una sala de primeros auxilios en todos los casos.","Un botiquín de primeros auxilios."],"correct":2,"e":"Todo lugar de trabajo debe tener al menos un botiquín de primeros auxilios. El desfibrilador o la sala solo son obligatorios en algunos casos."},
  {"id":"EMP-68","subject":"emple1","exam":"Prevención de riesgos laborales","text":"¿Cuál es la primera acción que se debe realizar según la pauta P.A.S.?","options":["Avisar a los servicios de emergencia.","Proteger el lugar para evitar más riesgos.","Socorrer al accidentado de forma inmediata."],"correct":1,"e":"La conducta PAS empieza por Proteger: asegurar la zona para que no haya más víctimas, ni tampoco el que ayuda. Después se Avisa y se Socorre."},
  {"id":"ASI-T1-1","subject":"asise","exam":"Tema 1","text":"¿Qué debemos comprobar y asegurar en el paso A de la valoración primaria?","options":["Si el paciente realiza movimientos respiratorios","Si la vía aérea está permeable y permite el paso de aire","Si el paciente presenta pulso carotídeo central","El nivel exacto de consciencia en la escala Glasgow"],"correct":1,"e":"En la A (Airway) se comprueba que la vía aérea está permeable y deja pasar el aire. La respiración se valora en la B y el pulso en la C."},
  {"id":"ASI-T1-2","subject":"asise","exam":"Tema 1","text":"En la valoración de la vía aérea (A), ¿cuál es el principal problema en un paciente inconsciente en decúbito supino?","options":["Que suele presentar convulsiones continuas","Que la lengua se relaja, cae hacia atrás y obstruye la vía aérea","La contracción involuntaria de la glotis","Que la frecuencia cardíaca desciende bruscamente"],"correct":1,"e":"En el paciente inconsciente boca arriba la lengua pierde tono, cae hacia atrás y tapa la vía aérea. Es la causa más frecuente de obstrucción."},
  {"id":"ASI-T1-3","subject":"asise","exam":"Tema 1","text":"¿Para qué se utiliza la maniobra frente-mentón?","options":["Para permeabilizar la vía aérea en pacientes inconscientes no traumáticos","Para comprobar la presencia de pulso periférico","Para inmovilizar la columna cervical","Para evaluar el reflejo fotomotor pupilar"],"correct":0,"e":"La maniobra frente-mentón abre la vía aérea en pacientes inconscientes sin sospecha de traumatismo cervical."},
  {"id":"ASI-T1-4","subject":"asise","exam":"Tema 1","text":"¿Cuál es el método más adecuado para permeabilizar la vía aérea en un paciente con sospecha de trauma?","options":["Maniobra frente-mentón","Tracción mandibular (o elevación mentoniana sin extensión)","Maniobra de Heimlich","Colocación en Posición Lateral de Seguridad"],"correct":1,"e":"Si se sospecha trauma se usa la tracción mandibular (elevación del mentón sin extender el cuello) para no mover la columna cervical."},
  {"id":"ASI-T1-5","subject":"asise","exam":"Tema 1","text":"¿Con qué objetivo aplicamos la regla VER - OÍR - SENTIR en la valoración primaria?","options":["Comprobar si hay latido cardíaco","Evaluar la respuesta al dolor","Medir la presión arterial sistólica","Comprobar si el paciente respira por sí mismo"],"correct":3,"e":"Ver el tórax moverse, oír la respiración y sentir el aire en la mejilla sirve para comprobar si el paciente respira por sí mismo."},
  {"id":"ASI-T1-6","subject":"asise","exam":"Tema 1","text":"Respecto al concepto de disnea, ¿cuál de las siguientes afirmaciones es cierta?","options":["Es una sensación subjetiva de falta de aire o ahogo que refiere el paciente","Es un signo objetivo que equivale a tener menos de 10 r.p.m.","Es la coloración azulada de mucosas y uñas","Se mide obligatoriamente con el fonendoscopio"],"correct":0,"e":"La disnea es una sensación subjetiva de falta de aire que refiere el paciente. La coloración azulada es la cianosis."},
  {"id":"ASI-T1-7","subject":"asise","exam":"Tema 1","text":"¿Cómo se mide de forma básica la frecuencia respiratoria en urgencias?","options":["Mediante un espirómetro de incentivo","Por observación directa de la expansión del tórax durante un minuto","Utilizando exclusivamente el pulsiómetro","Mediante palpación de la arteria radial"],"correct":1,"e":"La frecuencia respiratoria se mide observando cuántas veces se eleva el tórax durante un minuto completo."},
  {"id":"ASI-T1-8","subject":"asise","exam":"Tema 1","text":"Respecto a la frecuencia respiratoria según la edad, es cierto que:","options":["El valor normal es idéntico en niños y adultos (12-20 r.p.m.)","Cuanto más joven es la persona, mayor es su frecuencia respiratoria basal","Cuanto más joven es la persona, menor es su frecuencia respiratoria","Los lactantes respiran más lento que los ancianos"],"correct":1,"e":"Cuanto más pequeño es el niño, más alta es su frecuencia respiratoria en reposo."},
  {"id":"ASI-T1-9","subject":"asise","exam":"Tema 1","text":"¿Cuál es el rango normal de Frecuencia Respiratoria (eupnea) en un adulto sano en reposo?","options":["5 a 10 r.p.m.","12 a 20 r.p.m.","25 a 40 r.p.m.","40 a 60 r.p.m."],"correct":1,"e":"La frecuencia respiratoria normal (eupnea) de un adulto en reposo es de 12 a 20 respiraciones por minuto."},
  {"id":"ASI-T1-10","subject":"asise","exam":"Tema 1","text":"Un adulto que presenta una frecuencia respiratoria de 8 r.p.m. se encuentra en:","options":["Eupnea","Taquipnea","Bradipnea","Apnea"],"correct":2,"e":"Por debajo de 12 rpm en un adulto se habla de bradipnea. Con 8 rpm el paciente está en bradipnea."},
  {"id":"ASI-T1-11","subject":"asise","exam":"Tema 1","text":"Un adulto que presenta una frecuencia respiratoria de 28 r.p.m. se encuentra en:","options":["Eupnea","Bradipnea","Disnea","Taquipnea"],"correct":3,"e":"Por encima de 20 rpm en un adulto se habla de taquipnea. La disnea es una sensación, no una frecuencia."},
  {"id":"ASI-T1-12","subject":"asise","exam":"Tema 1","text":"La presencia de una coloración azulado-violácea en la piel y mucosas por falta de oxigenación se denomina:","options":["Tiraje","Cianosis","Hemoptisis","Eritema"],"correct":1,"e":"La cianosis es el color azulado-violáceo de piel y mucosas por falta de oxígeno."},
  {"id":"ASI-T1-13","subject":"asise","exam":"Tema 1","text":"Un lactante de 2 años que al inspirar hunde los espacios intercostales y el abdomen presenta:","options":["Respiración superficial","Respiración con tiraje","Bradipnea fisiológica","Respiración de Cheyne-Stokes"],"correct":1,"e":"Si al inspirar se hunden los espacios intercostales y el abdomen, hay tiraje: un signo de dificultad respiratoria importante."},
  {"id":"ASI-T1-14","subject":"asise","exam":"Tema 1","text":"La hemoptisis se define como:","options":["La salida de sangre procedente del tubo digestivo a través del vómito","La salida de sangre procedente del aparato respiratorio mediante la tos","El sangrado activo procedente de la cavidad nasal","La tinción azulada de las uñas por mala perfusión"],"correct":1,"e":"La hemoptisis es la expulsión con la tos de sangre que viene del aparato respiratorio. La sangre vomitada es hematemesis y la nasal, epistaxis."},
  {"id":"ASI-T1-15","subject":"asise","exam":"Tema 1","text":"¿Cuál de las siguientes opciones NO es un ruido respiratorio patológico?","options":["Sibilancia","Estridor","Expectoración","Roncus"],"correct":2,"e":"La expectoración es expulsar secreciones, no un ruido respiratorio. Sibilancias, estridor y roncus sí son ruidos patológicos."},
  {"id":"ASI-T1-16","subject":"asise","exam":"Tema 1","text":"¿Qué parámetro fisiológico mide de forma no invasiva un pulsioxímetro?","options":["La concentración total de CO₂ en el aire espirado","La presión parcial de oxígeno disuelto en plasma (PaO₂)","El porcentaje de hemoglobina saturada con oxígeno (SpO₂) y la frecuencia cardíaca","La frecuencia respiratoria por minuto"],"correct":2,"e":"El pulsioxímetro mide sin pinchar el porcentaje de hemoglobina saturada de oxígeno (SpO2) y la frecuencia cardíaca."},
  {"id":"ASI-T1-17","subject":"asise","exam":"Tema 1","text":"¿Qué valor de saturación de oxígeno (SpO₂) se considera dentro del rango de normalidad en un paciente sin patología respiratoria?","options":["Entre el 95% y el 100%","Entre el 90% y el 94%","Entre el 85% y el 90%","Siempre superior al 105%"],"correct":0,"e":"En una persona sin enfermedad respiratoria, la saturación normal está entre el 95 y el 100%."},
  {"id":"ASI-T1-18","subject":"asise","exam":"Tema 1","text":"Si el pulsioxímetro marca una saturación de oxígeno (SpO₂) del 88% en un paciente adulto, diremos que presenta:","options":["Normoxia","Hipotension","Hipoxia","Hiperoxia"],"correct":2,"e":"Una saturación del 88% es baja, así que el paciente tiene hipoxia (en adultos sanos se considera hipoxia por debajo del 95%)."},
  {"id":"ASI-T1-19","subject":"asise","exam":"Tema 1","text":"¿Cuál de los siguientes factores puede alterar la lectura del pulsioxímetro y dar una medición errónea o nula?","options":["La presencia de fiebre alta","La vasoconstricción periférica por hipotermia o esmalte de uñas oscuro","Que el paciente presente taquipnea","La toma simultánea de la presión arterial en el brazo opuesto"],"correct":1,"e":"El frío (vasoconstricción periférica) o el esmalte de uñas oscuro dificultan que el aparato lea bien la sangre del dedo y dan medidas erróneas o nulas."},
  {"id":"ASI-T1-20","subject":"asise","exam":"Tema 1","text":"¿En qué región anatómica se localiza el pulso carotídeo?","options":["En el pliegue del codo","En la cara lateral del cuello","En la cara interna de la muñeca","En la fosa poplítea detrás de la rodilla"],"correct":1,"e":"El pulso carotídeo se palpa en la cara lateral del cuello, junto a la tráquea."},
  {"id":"ASI-T1-21","subject":"asise","exam":"Tema 1","text":"¿En qué localización palparías preferentemente el pulso braquial o humeral?","options":["En la cara anterior de la muñeca","En la ingle","Detrás del maléolo interno del tobillo","En la cara interna del brazo / pliegue del codo"],"correct":3,"e":"El pulso braquial o humeral se palpa en la cara interna del brazo o en el pliegue del codo. En lactantes es el pulso de referencia."},
  {"id":"ASI-T1-22","subject":"asise","exam":"Tema 1","text":"¿Dónde se localiza la referencia anatómica del pulso femoral?","options":["En la ingle","En el dorso del pie","En la región temporal de la cabeza","En el cuello"],"correct":0,"e":"El pulso femoral se palpa en la ingle."},
  {"id":"ASI-T1-23","subject":"asise","exam":"Tema 1","text":"¿En qué punto anatómico debemos buscar el pulso pedio o tibial posterior?","options":["En la ingle","En el cuello","En el pie tras el maléolo interno","En el pliegue posterior de la rodilla"],"correct":2,"e":"Según la clave, se busca en el pie, detrás del maléolo interno. Ese punto es en realidad el pulso tibial posterior; el pedio se palpa en el dorso del pie."},
  {"id":"ASI-T1-24","subject":"asise","exam":"Tema 1","text":"Ante una pérdida progresiva de presión arterial por shock, ¿cuál es el último pulso central que se deja de palpar?","options":["El pulso radial","El pulso pedio","El pulso carotídeo","El pulso braquial"],"correct":2,"e":"Al caer la tensión, primero desaparecen los pulsos periféricos y el último en dejar de palparse es el carotídeo, que es central."},
  {"id":"ASI-T1-25","subject":"asise","exam":"Tema 1","text":"¿Cuál es la Frecuencia Cardíaca normal en reposo para un adulto?","options":["30 a 60 l.p.m.","60 a 100 l.p.m.","80 a 120 l.p.m.","100 a 140 l.p.m."],"correct":1,"e":"La frecuencia cardíaca normal de un adulto en reposo es de 60 a 100 latidos por minuto."},
  {"id":"ASI-T1-26","subject":"asise","exam":"Tema 1","text":"Respecto a la variación fisiológica de la frecuencia cardíaca con la edad, se cumple que:","options":["Aumenta gradualmente a medida que la persona envejece","Disminuye a medida que aumenta la edad (los lactantes tienen mayor FC)","Permanece exactamente constante a lo largo de toda la vida","Es más alta en ancianos que en recién nacidos"],"correct":1,"e":"La frecuencia cardíaca disminuye con la edad: los lactantes la tienen mucho más alta que los adultos."},
  {"id":"ASI-T1-27","subject":"asise","exam":"Tema 1","text":"Un adulto que presenta una frecuencia cardíaca medida en reposo de 35 l.p.m. tiene:","options":["Normocardia","Taquicardia","Bradicardia","Asistolia"],"correct":2,"e":"Por debajo de 60 lpm en un adulto se habla de bradicardia. Con 35 lpm el paciente está bradicárdico."},
  {"id":"ASI-T1-28","subject":"asise","exam":"Tema 1","text":"Un adulto que presenta una frecuencia cardíaca de 82 l.p.m. en reposo se clasifica con:","options":["Frecuencia cardíaca normal","Bradicardia","Taquicardia","Fibrilación"],"correct":0,"e":"82 lpm está dentro del rango normal de 60 a 100 lpm."},
  {"id":"ASI-T1-29","subject":"asise","exam":"Tema 1","text":"Un paciente adulto en reposo con una frecuencia cardíaca de 127 l.p.m. presenta:","options":["Bradicardia","Taquicardia","Ritmo sinusal normal","Miosis cardíaca"],"correct":1,"e":"Por encima de 100 lpm en un adulto se habla de taquicardia. Con 127 lpm el paciente está taquicárdico."},
  {"id":"ASI-T1-30","subject":"asise","exam":"Tema 1","text":"¿Qué refleja clínicamente un tiempo de rellenado capilar superior a 2 segundos?","options":["Buena perfusión tisular periférica","Hipoglucemia moderada","Mala perfusión en la circulación periférica","Hipertermia grave"],"correct":2,"e":"Si la uña tarda más de 2 segundos en recuperar el color tras presionarla, la sangre no llega bien a la periferia: hay mala perfusión."},
  {"id":"ASI-T1-31","subject":"asise","exam":"Tema 1","text":"¿A qué corresponde el concepto de Presión Arterial Sistólica (PAS) o \"máxima\"?","options":["A la presión ejercida sobre las arterias cuando los ventrículos se relajan","A la presión que se mide únicamente durante la fase de sueño profundo","A la presión que ejerce la sangre contra las arterias cuando el corazón se contrae e impulsa sangre","Al volumen total de sangre contenido en las venas cavas"],"correct":2,"e":"La presión sistólica o máxima es la que ejerce la sangre en las arterias cuando el corazón se contrae y la impulsa."},
  {"id":"ASI-T1-32","subject":"asise","exam":"Tema 1","text":"¿A qué corresponde el concepto de Presión Arterial Diastólica (PAD) o \"mínima\"?","options":["A la presión en las arterias durante la fase de relajación y llenado ventricular","A la fuerza de contracción del ventrículo izquierdo","A la presión registrada únicamente durante el ejercicio físico","Al pico máximo de presión del pulso arterial"],"correct":0,"e":"La presión diastólica o mínima es la que queda en las arterias cuando el corazón se relaja y se llena."},
  {"id":"ASI-T1-33","subject":"asise","exam":"Tema 1","text":"¿Cuáles son los valores considerados normales de Presión Arterial Sistólica en un adulto sano en reposo?","options":["60 a 90 mmHg","140 a 180 mmHg","80 a 120 mmHg","100 a 130 mmHg"],"correct":3,"e":"Según el PDF corregido del curso, la sistólica normal en un adulto en reposo está entre 100 y 130 mmHg."},
  {"id":"ASI-T1-34","subject":"asise","exam":"Tema 1","text":"¿Cuáles son los valores de referencia normales de Presión Arterial Diastólica en un adulto?","options":["60 a 80 mmHg","100 a 140 mmHg","40 a 55 mmHg","95 a 115 mmHg"],"correct":0,"e":"La diastólica normal en un adulto está entre 60 y 80 mmHg."},
  {"id":"ASI-T1-35","subject":"asise","exam":"Tema 1","text":"Un paciente adulto cuya toma de presión arterial arroja un resultado repetido de 165/105 mmHg presenta:","options":["Hipotensión arterial","Normotensión","Hipertensión arterial","Shock hipovolémico"],"correct":2,"e":"165/105 supera los 140/90, así que es hipertensión arterial."},
  {"id":"ASI-T1-36","subject":"asise","exam":"Tema 1","text":"Una escala que evalúa el nivel de consciencia categorizando al paciente mediante descripciones (como Alerta o Coma) es de tipo:","options":["Cuantitativa","Cualitativa","Numérica","Métrica"],"correct":1,"e":"Una escala que clasifica con palabras (alerta, coma…) es cualitativa, porque no da puntos."},
  {"id":"ASI-T1-37","subject":"asise","exam":"Tema 1","text":"Una escala que evalúa el nivel de consciencia sumando puntos a partir de ítems estandarizados es de tipo:","options":["Cualitativa","Descriptiva","Cuantitativa","Subjetiva"],"correct":2,"e":"Una escala que suma puntos, como la de Glasgow, es cuantitativa."},
  {"id":"ASI-T1-38","subject":"asise","exam":"Tema 1","text":"El estado en el que el paciente está despierto, orientado y responde adecuadamente a estímulos del entorno se denomina:","options":["Somnolencia","Alerta","Obnubilación","Estupor"],"correct":1,"e":"Alerta es el estado normal: despierto, orientado y respondiendo bien a lo que le rodea."},
  {"id":"ASI-T1-39","subject":"asise","exam":"Tema 1","text":"El estado de alteración donde el paciente solo sale de su letargo mediante estímulos muy intensos o dolorosos se llama:","options":["Somnolencia","Obnubilación","Estupor","Coma"],"correct":2,"e":"En el estupor el paciente solo sale de su letargo con estímulos muy intensos o dolorosos."},
  {"id":"ASI-T1-40","subject":"asise","exam":"Tema 1","text":"El estado de tendencia al sueño donde el paciente se adormila fácilmente pero se despierta ante llamadas leves se llama:","options":["Somnolencia","Estupor","Coma","Hiperactividad"],"correct":0,"e":"La somnolencia es tendencia al sueño: se adormila con facilidad pero despierta al llamarle."},
  {"id":"ASI-T1-41","subject":"asise","exam":"Tema 1","text":"La pérdida completa e irreversible de la consciencia sin respuesta a ningún estímulo externo corresponde a:","options":["Somnolencia","Obnubilación","Estupor","Coma"],"correct":3,"e":"El coma es la pérdida completa de la consciencia, sin respuesta a ningún estímulo."},
  {"id":"ASI-T1-42","subject":"asise","exam":"Tema 1","text":"El estado en el que el paciente muestra desorientación, lentitud mental y discurso confuso aunque mantiene la apertura ocular es:","options":["Alerta","Obnubilación","Coma profundo","Síncope"],"correct":1,"e":"En la obnubilación el paciente tiene los ojos abiertos, pero está desorientado, lento y con un discurso confuso."},
  {"id":"ASI-T1-43","subject":"asise","exam":"Tema 1","text":"Respecto a la regla AVDN de valoración cualitativa de la consciencia, ¿qué afirmación es FALSA?","options":["Divide el nivel de consciencia en 4 niveles de respuesta","Asigna una puntuación que va de 3 a 15 puntos","La letra D indica que solo responde ante estímulos dolorosos","Es una escala cualitativa rápida y fácil de aplicar"],"correct":1,"e":"Es falsa la B: la AVDN no da puntos, solo clasifica en cuatro niveles (Alerta, Verbal, Dolor, No responde). La puntuación de 3 a 15 es la de Glasgow."},
  {"id":"ASI-T1-44","subject":"asise","exam":"Tema 1","text":"En la regla AVDN, ¿qué letra se asigna a un paciente consciente y orientado?","options":["A","V","D","N"],"correct":0,"e":"La A de AVDN es Alerta: paciente consciente y orientado."},
  {"id":"ASI-T1-45","subject":"asise","exam":"Tema 1","text":"En la regla AVDN, si un paciente abre los ojos o se mueve solo cuando le hablamos en voz alta, le asignamos la letra:","options":["A","V","D","N"],"correct":1,"e":"La V es de Verbal: el paciente responde cuando se le habla en voz alta."},
  {"id":"ASI-T1-46","subject":"asise","exam":"Tema 1","text":"En la regla AVDN, a un paciente inconsciente que solo se queja al realizarle una presión en el lecho ungueal le corresponde:","options":["A","V","D","N"],"correct":2,"e":"La D es de Dolor: solo responde a estímulos dolorosos, como presionar el lecho de la uña."},
  {"id":"ASI-T1-47","subject":"asise","exam":"Tema 1","text":"En la regla AVDN, si el paciente no muestra ninguna reacción ante estímulos verbales ni dolorosos, se clasifica como:","options":["A","V","D","N"],"correct":3,"e":"La N es de No responde: no hay reacción ni a la voz ni al dolor."},
  {"id":"ASI-T1-48","subject":"asise","exam":"Tema 1","text":"Respecto a la Escala de Coma de Glasgow (GCS), señala la afirmación FALSA:","options":["Es una escala cuantitativa de valoración del nivel de consciencia","Una puntuación igual o menor a 8 puntos indica traumatismo o daño neurológico grave","A mayor puntuación obtenida, más profundo es el estado de coma del paciente","Su rango de valoración oscila entre 3 y 15 puntos"],"correct":2,"e":"Es falsa la C: en la escala de Glasgow, cuanto más baja es la puntuación, más profundo es el coma. Un 8 o menos indica daño neurológico grave."},
  {"id":"ASI-T1-49","subject":"asise","exam":"Tema 1","text":"¿Qué tres respuestas explora la Escala de Coma de Glasgow?","options":["Respuesta motora, respuesta verbal y respuesta ocular","Respuesta pupilar, frecuencia respiratoria y pulso","Nivel de atención, orientación espacial y respuesta al dolor","Reflejo fotomotor, fuerza muscular y deglución"],"correct":0,"e":"La escala de Glasgow valora la apertura ocular, la respuesta verbal y la respuesta motora."},
  {"id":"ASI-T1-50","subject":"asise","exam":"Tema 1","text":"¿Cuál es la puntuación MÁXIMA posible en la Escala de Coma de Glasgow?","options":["10 puntos","12 puntos","15 puntos","20 puntos"],"correct":2,"e":"La puntuación máxima de Glasgow es 15 (4 ocular + 5 verbal + 6 motora)."},
  {"id":"ASI-T1-51","subject":"asise","exam":"Tema 1","text":"¿Cuál es la puntuación MÍNIMA que puede obtener un paciente en la Escala de Coma de Glasgow?","options":["0 puntos","1 punto","3 puntos","5 puntos"],"correct":2,"e":"La puntuación mínima de Glasgow es 3, porque cada apartado puntúa como mínimo 1."},
  {"id":"ASI-T1-52","subject":"asise","exam":"Tema 1","text":"Al explorar las pupilas, observamos que la pupila derecha está dilatada y la izquierda contraída. Este hallazgo se denomina:","options":["Miosis","Midriasis","Isocoria","Anisocoria"],"correct":3,"e":"Cuando las pupilas tienen distinto tamaño se habla de anisocoria."},
  {"id":"ASI-T1-53","subject":"asise","exam":"Tema 1","text":"El término médico \"Midriasis\" hace referencia a:","options":["Pupilas dilatadas (aumento del diámetro pupilar)","Pupilas contraídas o puntiformes","Pupilas de tamaño asimétrico","Ausencia de reflejo a la luz"],"correct":0,"e":"Midriasis es la dilatación de la pupila."},
  {"id":"ASI-T1-54","subject":"asise","exam":"Tema 1","text":"El término médico \"Miosis\" hace referencia a:","options":["Pupilas dilatadas","Pupilas contraídas (disminución del diámetro pupilar)","Pupilas desiguales entre sí","Deformidad en la córnea"],"correct":1,"e":"Miosis es la contracción de la pupila (pupila pequeña o puntiforme)."},
  {"id":"ASI-T1-55","subject":"asise","exam":"Tema 1","text":"Cuando ambas pupilas tienen el mismo tamaño y reaccionan contrayéndose al aplicarles luz directa, se dice que son:","options":["Anisocóricas e hiporreactivas","Isocóricas y normorreactivas","Midriáticas y arreactivas","Mióticas e asimétricas"],"correct":1,"e":"Pupilas iguales que se contraen con la luz son isocóricas y normorreactivas."},
  {"id":"ASI-T1-56","subject":"asise","exam":"Tema 1","text":"¿Qué valores de glucemia basal en ayunas son normales en una persona sana?","options":["40 a 60 mg/dl","70 a 100 mg/dl","130 a 180 mg/dl","Superiores a 200 mg/dl"],"correct":1,"e":"La glucemia basal normal en ayunas está entre 70 y 100 mg/dl."},
  {"id":"ASI-T1-57","subject":"asise","exam":"Tema 1","text":"Un paciente que presenta una cifra de glucemia capilar de 45 mg/dl padece:","options":["Hiperglucemia","Normoglucemia","Hipoglucemia","Cetoacidosis"],"correct":2,"e":"Por debajo de 70 mg/dl hay hipoglucemia. Con 45 mg/dl es una hipoglucemia clara."},
  {"id":"ASI-T1-58","subject":"asise","exam":"Tema 1","text":"Una lectura de temperatura corporal tomada en la axila de 37,6 ºC indica:","options":["Hipotermia leve","Febrícula","Fiebre alta","Hiperpirexia grave"],"correct":1,"e":"Entre 37,1 y 37,9 ºC en la axila se considera febrícula."},
  {"id":"ASI-T1-59","subject":"asise","exam":"Tema 1","text":"¿Qué relación existe entre la temperatura periférica (axilar) y las temperaturas centrales (rectal o timpánica)?","options":["La axilar es entre 0,3 ºC y 0,5 ºC superior a las centrales","La axilar es 2 ºC superior debido a la sudoración axilar","Son exactamente idénticas en cualquier circunstancia","La axilar es entre 0,3 ºC y 0,5 ºC inferior a las centrales"],"correct":3,"e":"La temperatura axilar es entre 0,3 y 0,5 ºC más baja que la central (rectal o timpánica)."},
  {"id":"ASI-T1-60","subject":"asise","exam":"Tema 1","text":"A partir de qué cifra de temperatura axilar consideramos clínicamente que el paciente presenta fiebre?","options":["A partir de 37,1 ºC","A partir de 37,5 ºC","A partir de 38,0 ºC","A partir de 39,5 ºC"],"correct":2,"e":"Se considera fiebre a partir de 38 ºC en la axila; por debajo es febrícula."},
  {"id":"ASI-T1-61","subject":"asise","exam":"Tema 1","text":"¿Cuáles son las características típicas del dolor torácico por cardiopatía isquémica?","options":["Punzante, aumenta a la palpación e inmovilización","Opresivo, retroesternal, irradia a brazo e inmodificable","Pleurítico, aumenta al toser y con fiebre alta","Urente en epigastrio, empeora al tumbarse tras comer"],"correct":1,"e":"El dolor de la cardiopatía isquémica es opresivo, detrás del esternón, puede irradiarse al brazo y no cambia al moverse ni al presionar."},
  {"id":"ASI-T1-62","subject":"asise","exam":"Tema 1","text":"¿Qué aspecto y características suele presentar la piel de un paciente que se encuentra en una situación de mala perfusión tisular o compromiso hemodinámico (shock)?","options":["Piel pálida, fría y sudorosa (marmoleada o cianótica)","Piel caliente, enrojecida y seca","Piel de coloración amarillenta (ictericia) y caliente","Piel sonrosada, templada y con rellenado capilar inmediato"],"correct":0,"e":"En el shock la piel está pálida, fría y sudorosa, a veces moteada o con cianosis, porque la sangre se desvía a los órganos vitales."},
  {"id":"DOT-T1-1","subject":"dotacion","exam":"Tema 1","text":"Respecto a la definición de transporte sanitario, ¿cuál NO es cierta?","options":["Se realiza para desplazar personas por una razón sanitaria.","Los vehículos usados siempre deben tener medidas asistenciales.","Puede realizarse de forma individual o colectiva.","Se realiza mediante vehículos especialmente acondicionados."],"correct":1,"e":"Es falsa la B: no todos los vehículos de transporte sanitario son asistenciales. Las ambulancias A1 y A2 trasladan pacientes sin prestar asistencia en ruta."},
  {"id":"DOT-T1-2","subject":"dotacion","exam":"Tema 1","text":"Según la urgencia vital, el transporte sanitario se divide en:","options":["Emergencia, urgencia y demorable.","No grave, grave no crítico y crítico.","Primario, secundario y terciario.","Terrestre, aéreo y marítimo."],"correct":0,"e":"Según la urgencia vital, el transporte se clasifica en de emergencia, urgente y demorable (programado)."},
  {"id":"DOT-T1-3","subject":"dotacion","exam":"Tema 1","text":"El transporte que debe realizarse de inmediato por existir riesgo vital se denomina:","options":["De urgencia.","De emergencia.","Primario.","Demorable."],"correct":1,"e":"El transporte de emergencia es el que hay que hacer de inmediato porque hay riesgo vital. El urgente puede esperar algo más."},
  {"id":"DOT-T1-4","subject":"dotacion","exam":"Tema 1","text":"¿A qué llamamos transporte sanitario secundario?","options":["Al realizado entre edificios de un mismo hospital.","Al realizado desde el lugar de la emergencia al hospital.","Al realizado entre dos hospitales diferentes.","Al traslado programado desde el domicilio."],"correct":2,"e":"El transporte secundario es el que se hace entre dos hospitales distintos."},
  {"id":"DOT-T1-5","subject":"dotacion","exam":"Tema 1","text":"¿Cómo se denomina el traslado desde el lugar de una emergencia hasta un hospital?","options":["Primario.","Secundario.","Terciario.","Intrahospitalario."],"correct":0,"e":"El transporte primario es el que va desde el lugar de la emergencia hasta el hospital."},
  {"id":"DOT-T1-6","subject":"dotacion","exam":"Tema 1","text":"Un traslado entre dos edificios del mismo hospital se considera:","options":["Transporte primario.","Transporte secundario.","Transporte terciario.","Transporte colectivo."],"correct":2,"e":"El transporte terciario es el que se hace dentro de un mismo hospital, por ejemplo entre dos de sus edificios."},
  {"id":"DOT-T1-7","subject":"dotacion","exam":"Tema 1","text":"¿Cuál es un ejemplo de transporte sanitario secundario?","options":["Recogida de un accidentado en una zona de montaña.","Traslado entre dos edificios del mismo hospital.","Traslado desde el domicilio al hospital tras un accidente.","Traslado de un hospital a otro para un trasplante."],"correct":3,"e":"Trasladar a un paciente de un hospital a otro, por ejemplo para un trasplante, es transporte secundario."},
  {"id":"DOT-T1-8","subject":"dotacion","exam":"Tema 1","text":"Un paciente estable, grave y que precisa monitorización y cuidados intensivos es:","options":["No grave.","Grave no crítico.","Crítico.","No grave programado."],"correct":1,"e":"Según el temario, el paciente grave pero estable que necesita vigilancia y cuidados se clasifica como grave no crítico. El crítico es el inestable."},
  {"id":"DOT-T1-9","subject":"dotacion","exam":"Tema 1","text":"Según el RD 836/2012, las ambulancias se clasifican inicialmente en:","options":["Asistenciales y no asistenciales.","Convencionales y colectivas.","Tipo A y tipo B exclusivamente.","Urgentes y programadas."],"correct":0,"e":"El RD 836/2012 divide primero las ambulancias en no asistenciales (clase A) y asistenciales (clases B y C)."},
  {"id":"DOT-T1-10","subject":"dotacion","exam":"Tema 1","text":"Respecto a las ambulancias de transporte colectivo, ¿cuál NO es cierta?","options":["Pertenecen a la clase A1.","Son ambulancias no asistenciales.","Se destinan a traslados que no revisten urgencia.","Corresponden a la clase A2."],"correct":0,"e":"Es falsa la A: las ambulancias de transporte colectivo son de clase A2, no A1. Son no asistenciales y para traslados no urgentes."},
  {"id":"DOT-T1-11","subject":"dotacion","exam":"Tema 1","text":"¿Qué ambulancia no asistencial está destinada al transporte en camilla?","options":["Clase B.","Clase A1.","Clase A2.","Clase C."],"correct":1,"e":"La A1 es la ambulancia no asistencial para trasladar pacientes en camilla. La A2 es para varios pacientes sentados."},
  {"id":"DOT-T1-12","subject":"dotacion","exam":"Tema 1","text":"¿Cuál de las siguientes es una ambulancia NO asistencial?","options":["Soporte Vital Básico.","UVI móvil.","Soporte Vital Avanzado.","Transporte colectivo."],"correct":3,"e":"La ambulancia de transporte colectivo (A2) es no asistencial. SVB y SVA (UVI móvil) son asistenciales."},
  {"id":"DOT-T1-13","subject":"dotacion","exam":"Tema 1","text":"¿Qué clase corresponde a las ambulancias de Soporte Vital Avanzado?","options":["Clase B.","Clase A.","Clase C.","Clase A2."],"correct":2,"e":"La clase C es la ambulancia de soporte vital avanzado (SVA o UVI móvil). La B es la de soporte vital básico."},
  {"id":"DOT-T1-14","subject":"dotacion","exam":"Tema 1","text":"Respecto a las ambulancias de SVB, ¿cuál NO es cierta?","options":["Son ambulancias no asistenciales.","Pertenecen a la clase B.","Su dotación mínima incluye dos TES.","Permiten prestar asistencia sanitaria inicial."],"correct":0,"e":"Es falsa la A: las ambulancias de SVB (clase B) son asistenciales, llevan dos TES y permiten dar asistencia sanitaria inicial."},
  {"id":"DOT-T1-15","subject":"dotacion","exam":"Tema 1","text":"¿Qué ambulancias puede conducir con carácter general quien posee el certificado de transporte sanitario?","options":["Las clases A y B.","Las clases A1 y A2.","Únicamente las A1.","Las clases B y C."],"correct":1,"e":"Con el certificado profesional de transporte sanitario se pueden conducir con carácter general las no asistenciales A1 y A2."},
  {"id":"DOT-T1-16","subject":"dotacion","exam":"Tema 1","text":"¿Qué ambulancia debe contar como mínimo con dos personas tituladas como TES?","options":["Clase A.","Clase C.","Clase B.","Clase A2."],"correct":2,"e":"La ambulancia de clase B (SVB) debe llevar como mínimo dos técnicos en emergencias sanitarias."},
  {"id":"DOT-T1-17","subject":"dotacion","exam":"Tema 1","text":"¿Cuál es la dotación mínima estatal de una ambulancia de clase C?","options":["Conductor TES/habilitado y profesional de Enfermería.","Dos TES exclusivamente.","Conductor con certificado profesional y ayudante.","Médico y conductor exclusivamente."],"correct":0,"e":"La dotación mínima estatal de la clase C es un conductor TES (o habilitado) y un enfermero; el médico se añade cuando la asistencia lo requiere."},
  {"id":"DOT-T1-18","subject":"dotacion","exam":"Tema 1","text":"Respecto a los VIR, ¿cuál NO es cierta?","options":["Permiten asistir y estabilizar al paciente en el lugar.","Se desplazan hasta el lugar de la emergencia.","Pueden estar dotados de material sanitario avanzado.","Tienen capacidad para transportar al paciente al hospital."],"correct":3,"e":"Es falsa la D: el VIR lleva personal y material avanzado al lugar para estabilizar al paciente, pero no transporta pacientes."},
  {"id":"DOT-T1-19","subject":"dotacion","exam":"Tema 1","text":"La dotación sanitaria habitual de un helicóptero medicalizado incluye:","options":["TES, médico y enfermero, sin piloto.","Piloto, copiloto, médico y enfermero.","Piloto, médico y TES exclusivamente.","Piloto y dos TES exclusivamente."],"correct":1,"e":"El helicóptero medicalizado suele llevar piloto, copiloto, médico y enfermero."},
  {"id":"DOT-T1-20","subject":"dotacion","exam":"Tema 1","text":"El RD 836/2012 NO establece:","options":["El máximo de kilómetros que puede tener una ambulancia.","Características técnicas de los vehículos.","Dotación de personal.","Clases de ambulancias por carretera."],"correct":0,"e":"El RD 836/2012 regula las clases de ambulancias, sus características técnicas y su personal, pero no fija un máximo de kilómetros."},
  {"id":"DOT-T1-21","subject":"dotacion","exam":"Tema 1","text":"¿Qué dos zonas principales diferenciamos en una ambulancia?","options":["Habitáculo de conducción y habitáculo sanitario.","Habitáculo de mando y habitáculo sanitario.","Zona de personal y zona de pacientes.","Cabina técnica y cabina de emergencias."],"correct":0,"e":"Una ambulancia tiene dos zonas: el habitáculo de conducción (cabina) y el habitáculo sanitario (célula asistencial)."},
  {"id":"DOT-T1-22","subject":"dotacion","exam":"Tema 1","text":"Sobre las características generales del habitáculo sanitario, ¿cuál NO es cierta?","options":["No debe tener lunas para garantizar la intimidad.","Dispone de climatización independiente de la cabina.","Dispone de acceso lateral derecho y trasero.","Sus superficies deben facilitar limpieza y desinfección."],"correct":0,"e":"Es falsa la A: el habitáculo sanitario puede tener lunas (traslúcidas o protegidas para mantener la intimidad). Lo demás sí es correcto."},
  {"id":"DOT-T1-23","subject":"dotacion","exam":"Tema 1","text":"¿Qué tomas de corriente hemos estudiado como referencia para una A1?","options":["Cuatro tomas de 12 V.","Una de 12 V y otra de 230 V.","Cuatro tomas de 230 V.","Dos tomas de 12 V."],"correct":3,"e":"Como referencia para la A1 se estudiaron dos tomas de corriente de 12 V."},
  {"id":"DOT-T1-24","subject":"dotacion","exam":"Tema 1","text":"¿Qué ambulancia no asistencial puede transportar hasta 7 pacientes sentados?","options":["A1.","A2.","B.","C."],"correct":1,"e":"La A2 (transporte colectivo) puede llevar hasta 7 pacientes sentados."},
  {"id":"DOT-T1-25","subject":"dotacion","exam":"Tema 1","text":"¿Qué ambulancias deben disponer de señalización luminosa y acústica reglamentaria?","options":["Solo las A1.","Solo B y C.","Todas las ambulancias.","Solo las destinadas a emergencias."],"correct":2,"e":"Todas las ambulancias deben llevar la señalización luminosa y acústica reglamentaria."},
  {"id":"DOT-T1-26","subject":"dotacion","exam":"Tema 1","text":"¿Qué ambulancias disponen de conexión externa para mantener o cargar equipos?","options":["Las ambulancias asistenciales B y C.","Todas obligatoriamente.","Exclusivamente las C.","Exclusivamente las B."],"correct":0,"e":"Las asistenciales B y C disponen de una conexión externa para mantener cargados los equipos electromédicos."},
  {"id":"DOT-T1-27","subject":"dotacion","exam":"Tema 1","text":"¿Qué elemento es característico de las células sanitarias de B y C?","options":["Ausencia de bancada para la camilla.","Siete asientos para pacientes.","Plataforma para sillas de ruedas obligatoria.","Barras o asideros de techo para el personal."],"correct":3,"e":"Las células sanitarias de B y C llevan barras o asideros en el techo para que el personal se sujete mientras atiende en marcha."},
  {"id":"DOT-T1-28","subject":"dotacion","exam":"Tema 1","text":"¿Qué característica diferencia el habitáculo de B y C respecto a A1 y A2?","options":["Está diseñado para permitir asistencia sanitaria en ruta.","Carece de sistemas de fijación para la camilla.","Está destinado exclusivamente a pacientes sentados.","No necesita espacio alrededor de la camilla."],"correct":0,"e":"El habitáculo de B y C está pensado para dar asistencia sanitaria durante el trayecto, con espacio alrededor de la camilla."},
  {"id":"DOT-T1-29","subject":"dotacion","exam":"Tema 1","text":"¿En qué ambulancias la bancada facilita posicionar al paciente y acceder a él?","options":["A1 y A2.","B y C.","Solo A2.","Solo A1."],"correct":1,"e":"En B y C la bancada permite colocar al paciente en distintas posiciones y acceder a él para atenderle."},
  {"id":"DOT-T1-30","subject":"dotacion","exam":"Tema 1","text":"¿En qué ambulancias la bancada permite Trendelenburg, anti-Trendelenburg y desplazamiento lateral?","options":["En todas las ambulancias.","En las ambulancias asistenciales B y C.","Exclusivamente en las C.","Exclusivamente en las A1."],"correct":1,"e":"En las asistenciales B y C la bancada permite Trendelenburg, anti-Trendelenburg y desplazamiento lateral."},
  {"id":"DOT-T1-31","subject":"dotacion","exam":"Tema 1","text":"Respecto a ambulancias para pacientes psiquiátricos, ¿cuál NO es cierta?","options":["Pueden incorporar una silla para sujetar al paciente.","El material puede mantenerse protegido en armarios.","Deben identificarse exteriormente como emergencia psiquiátrica.","Su diseño busca aumentar la seguridad durante el traslado."],"correct":2,"e":"Es falsa la C: no hay que rotularlas como «emergencia psiquiátrica». Sí pueden llevar silla de sujeción y el material guardado en armarios por seguridad."},
  {"id":"DOT-T1-32","subject":"dotacion","exam":"Tema 1","text":"¿Qué ambulancias deben disponer de material para medir la tensión arterial?","options":["Solo las no asistenciales.","Las ambulancias asistenciales B y C.","Exclusivamente las C.","Exclusivamente las A2."],"correct":1,"e":"El material para medir la tensión arterial es obligatorio en las asistenciales B y C."},
  {"id":"DOT-T1-33","subject":"dotacion","exam":"Tema 1","text":"¿Qué ambulancias pueden disponer de material para pequeñas intervenciones quirúrgicas?","options":["Las no asistenciales.","Las asistenciales B y C.","Exclusivamente las A2.","Solo las A1."],"correct":1,"e":"Las asistenciales B y C pueden llevar material para pequeñas intervenciones quirúrgicas (curas y suturas)."},
  {"id":"DOT-T1-34","subject":"dotacion","exam":"Tema 1","text":"¿Qué ambulancias asistenciales disponen de collarines cervicales?","options":["Solo las A.","Solo las A2.","Solo las C.","B y C."],"correct":3,"e":"Los collarines cervicales forman parte de la dotación de las ambulancias asistenciales B y C."},
  {"id":"DOT-T1-35","subject":"dotacion","exam":"Tema 1","text":"¿Qué ambulancia se caracteriza por disponer de bombas de perfusión?","options":["A1.","B.","C.","A2."],"correct":2,"e":"Las bombas de perfusión, que administran fármacos de forma controlada, son propias de la ambulancia C (SVA)."},
  {"id":"DOT-T1-36","subject":"dotacion","exam":"Tema 1","text":"¿Qué ambulancia se caracteriza por un monitor-desfibrilador manual multiparamétrico?","options":["A1.","A2.","C.","Transporte colectivo."],"correct":2,"e":"El monitor-desfibrilador manual multiparamétrico es característico de la ambulancia C. La B lleva un DEA o DESA."},
  {"id":"DOT-T1-37","subject":"dotacion","exam":"Tema 1","text":"¿Qué ambulancia puede disponer de material para canalizar una vía venosa central?","options":["A1.","B.","C.","A2."],"correct":2,"e":"El material para canalizar una vía venosa central es propio de la ambulancia C, que lleva personal facultativo."},
  {"id":"DOT-T1-38","subject":"dotacion","exam":"Tema 1","text":"¿Qué ambulancias pueden disponer de material básico de curas?","options":["Solo las A.","Solo B y C.","Exclusivamente las C.","A, B y C."],"correct":3,"e":"Todas las ambulancias, A, B y C, pueden llevar material básico de curas."},
  {"id":"DOT-T1-39","subject":"dotacion","exam":"Tema 1","text":"¿Qué ambulancias asistenciales pueden disponer de kit de asistencia al parto?","options":["Solo las A.","B y C.","Exclusivamente las C.","Solo las A2."],"correct":1,"e":"El kit de asistencia al parto forma parte de la dotación de las asistenciales B y C."},
  {"id":"DOT-T1-40","subject":"dotacion","exam":"Tema 1","text":"¿Qué ambulancias pueden disponer de Ambú y mascarillas de distintos tamaños?","options":["Solo las A.","Solo B y C.","A, B y C.","Exclusivamente las C."],"correct":2,"e":"El balón de ventilación (Ambú) con mascarillas de varios tamaños puede estar en las ambulancias A, B y C."},
  {"id":"DOT-T1-41","subject":"dotacion","exam":"Tema 1","text":"¿Qué ambulancias asistenciales disponen de silla de evacuación?","options":["B y C.","Solo las A.","Solo las C.","Solo las A2."],"correct":0,"e":"La silla de evacuación forma parte de la dotación de las asistenciales B y C."},
  {"id":"DOT-T1-42","subject":"dotacion","exam":"Tema 1","text":"¿Qué ambulancia se caracteriza por disponer de respirador mecánico?","options":["A1.","B.","C.","A2."],"correct":2,"e":"El respirador mecánico es propio de la ambulancia C (SVA)."},
  {"id":"DOT-T1-43","subject":"dotacion","exam":"Tema 1","text":"¿Qué dotación de oxígeno fijo hemos estudiado para una ambulancia C?","options":["Dos botellas de al menos 400 L cada una.","Dos botellas de al menos 800 L cada una.","Dos botellas de al menos 2.000 L cada una.","Una botella de al menos 4.000 L."],"correct":2,"e":"Para la ambulancia C se estudiaron dos botellas fijas de oxígeno de al menos 2.000 litros cada una."},
  {"id":"DOT-T1-44","subject":"dotacion","exam":"Tema 1","text":"¿Qué ambulancias asistenciales disponen de tablero espinal con inmovilizador de cabeza?","options":["Solo las A.","B y C.","Solo las C.","Solo las A2."],"correct":1,"e":"El tablero espinal con inmovilizador de cabeza forma parte de la dotación de las asistenciales B y C."},
  {"id":"DOT-T1-45","subject":"dotacion","exam":"Tema 1","text":"¿Qué ambulancia de SVB dispone de desfibrilador externo automático o semiautomático?","options":["A1.","B.","A2.","Transporte colectivo."],"correct":1,"e":"La ambulancia de SVB (clase B) lleva un desfibrilador externo automático o semiautomático (DEA/DESA)."},
  {"id":"DOT-T1-46","subject":"dotacion","exam":"Tema 1","text":"¿Qué ambulancias pueden disponer de material fungible para oxigenoterapia?","options":["Solo las A.","Solo B y C.","A, B y C.","Exclusivamente las C."],"correct":2,"e":"El material fungible de oxigenoterapia (mascarillas, gafas nasales) puede estar en las ambulancias A, B y C."},
  {"id":"DOT-T1-47","subject":"dotacion","exam":"Tema 1","text":"¿Qué ambulancias asistenciales pueden disponer de material para acceso venoso periférico?","options":["Solo las A.","B y C.","Exclusivamente las C.","Solo las A2."],"correct":1,"e":"Las asistenciales B y C pueden llevar material para canalizar una vía venosa periférica."},
  {"id":"DOT-T1-48","subject":"dotacion","exam":"Tema 1","text":"¿Qué ambulancias pueden disponer de cánulas orofaríngeas de Guedel?","options":["Solo las A.","Solo B y C.","A, B y C.","Exclusivamente las C."],"correct":2,"e":"Las cánulas orofaríngeas de Guedel pueden estar en las ambulancias A, B y C."},
  {"id":"DOT-T1-49","subject":"dotacion","exam":"Tema 1","text":"¿Qué ambulancias asistenciales disponen de férulas para inmovilizar extremidades?","options":["Solo las A.","B y C.","Solo las A2.","Exclusivamente las C."],"correct":3,"e":"Según la clave del curso, las férulas para inmovilizar extremidades son exclusivas de la clase C. Revísalo con tu temario, porque las ambulancias B también suelen llevarlas."},
  {"id":"DOT-T1-50","subject":"dotacion","exam":"Tema 1","text":"¿Qué ambulancia dispone de la dotación más amplia de medicación para tratamiento farmacológico?","options":["A1.","A2.","C.","Transporte colectivo."],"correct":2,"e":"La ambulancia C (SVA) lleva la dotación de medicación más amplia, porque hay personal sanitario que puede administrarla."},
  {"id":"DOT-T1-51","subject":"dotacion","exam":"Tema 1","text":"¿Qué característica diferencia fundamentalmente a un VIR de una ambulancia?","options":["No puede desplazarse a emergencias.","No está destinado al transporte de pacientes.","No transporta material sanitario.","Solo realiza transporte programado."],"correct":1,"e":"Lo que distingue al VIR es que no transporta pacientes: lleva personal y material al lugar, pero el traslado lo hace una ambulancia."},
  {"id":"DOT-T1-52","subject":"dotacion","exam":"Tema 1","text":"Según el RD 836/2012, ¿qué elemento es opcional en una ambulancia A2?","options":["Los asientos.","La puerta lateral.","La camilla.","La climatización."],"correct":2,"e":"Según el RD 836/2012, en la A2 la camilla es opcional, porque está pensada para pacientes sentados."},
  {"id":"DOT-T1-53","subject":"dotacion","exam":"Tema 1","text":"¿Qué capacidad mínima tienen las botellas portátiles de O₂ estudiadas para la clase C?","options":["200 L.","2.000 L.","4.000 L.","400 L."],"correct":3,"e":"En la ambulancia C las botellas portátiles de oxígeno son de al menos 400 litros."},
  {"id":"DOT-T1-54","subject":"dotacion","exam":"Tema 1","text":"¿Qué sistema puede incorporar una ambulancia C para medicamentos termolábiles?","options":["Un pequeño frigorífico.","Un calentador de sueros.","Una toma de oxígeno.","Una plataforma elevadora."],"correct":0,"e":"La ambulancia C puede llevar un pequeño frigorífico para conservar los medicamentos que necesitan frío (termolábiles)."},
  {"id":"DOT-T1-55","subject":"dotacion","exam":"Tema 1","text":"¿Qué medios pueden utilizarse para realizar transporte sanitario?","options":["Únicamente vehículos terrestres.","Medios terrestres, aéreos y marítimos.","Únicamente ambulancias y helicópteros.","Exclusivamente ambulancias y aviones."],"correct":1,"e":"El transporte sanitario puede hacerse por tierra, aire y mar."},
  {"id":"MEC-T2-1","subject":"mecanica","exam":"Tema 2","text":"¿Cuál es la función principal de los latiguillos flexibles del circuito hidráulico de frenos?","options":["Absorber las oscilaciones de las ruedas manteniendo la conexión hidráulica con los elementos receptores.","Incrementar la presión hidráulica generada por la bomba de freno.","Regular automáticamente la presión de frenado en función de la carga del vehículo."],"correct":0,"e":"Los latiguillos son tubos flexibles que unen la instalación rígida con las ruedas, así absorben los movimientos de la suspensión sin perder la conexión hidráulica."},
  {"id":"MEC-T2-2","subject":"mecanica","exam":"Tema 2","text":"En un sistema de frenos de tambor, ¿qué elemento sirve de soporte a las zapatas y a parte del mecanismo de accionamiento?","options":["El tambor solidario al buje.","El plato portafreno.","La pinza de freno."],"correct":1,"e":"El plato portafreno va fijo y sobre él se montan las zapatas y parte del mecanismo. El tambor es la pieza que gira con la rueda."},
  {"id":"MEC-T2-3","subject":"mecanica","exam":"Tema 2","text":"¿Qué característica constituye una ventaja de los frenos de disco frente a los de tambor según el temario?","options":["Mayor capacidad de refrigeración y menor tamaño de las piezas para una eficacia equivalente.","Mayor complejidad constructiva y mejor retención del calor.","Mayor superficie de fricción y peor evacuación térmica."],"correct":0,"e":"El freno de disco se refrigera mejor y, a igual eficacia, sus piezas son más pequeñas que las del tambor."},
  {"id":"MEC-T2-4","subject":"mecanica","exam":"Tema 2","text":"En un servofreno que funciona por depresión, ¿dónde se encuentra situado normalmente este dispositivo?","options":["Entre el repartidor de frenada y el circuito trasero.","Entre la bomba de freno y los bombines de las ruedas.","Entre el pedal de freno y la bomba hidráulica."],"correct":2,"e":"El servofreno va entre el pedal y la bomba de freno: multiplica la fuerza del pie aprovechando la depresión del motor."},
  {"id":"MEC-T2-5","subject":"mecanica","exam":"Tema 2","text":"¿Qué función desempeña el repartidor de frenada instalado en las canalizaciones de los frenos traseros?","options":["Disminuir la presión hidráulica para reducir el riesgo de bloqueo de las ruedas traseras.","Aumentar la presión trasera durante las frenadas intensas.","Igualar permanentemente la presión de ambos ejes, independientemente de la carga."],"correct":0,"e":"El repartidor reduce la presión que llega a las ruedas traseras para que no se bloqueen al frenar fuerte."},
  {"id":"MEC-T2-6","subject":"mecanica","exam":"Tema 2","text":"En un sistema de frenos de tambor, ¿qué elemento devuelve las zapatas hacia su posición inicial cuando desaparece la acción de frenado?","options":["Los muelles de recuperación.","El actuador hidráulico.","El sistema de ajuste automático."],"correct":0,"e":"Los muelles de recuperación devuelven las zapatas a su posición cuando se suelta el freno."},
  {"id":"MEC-T2-7","subject":"mecanica","exam":"Tema 2","text":"¿Qué diferencia fundamental existe entre el sistema principal de frenado y el sistema auxiliar o de estacionamiento descritos en el temario?","options":["Ambos funcionan exclusivamente mediante presión hidráulica.","El principal funciona hidráulicamente y el auxiliar habitualmente de forma mecánica.","El principal funciona mecánicamente y el auxiliar hidráulicamente."],"correct":1,"e":"El freno principal (de servicio) es hidráulico y el de estacionamiento suele ser mecánico, accionado por cable."},
  {"id":"MEC-T2-8","subject":"mecanica","exam":"Tema 2","text":"¿Qué circunstancia provoca que la unidad electrónica del ABS reduzca la presión hidráulica de frenado en una rueda?","options":["Que la velocidad de giro de esa rueda disminuya de forma desproporcionada respecto a las demás y a la velocidad del vehículo.","Que todas las ruedas mantengan exactamente la misma velocidad de giro.","Que el conductor reduzca ligeramente la presión sobre el pedal."],"correct":0,"e":"Si una rueda frena mucho más rápido que las demás y que el vehículo (va a bloquearse), la centralita del ABS le reduce la presión."},
  {"id":"MEC-T2-9","subject":"mecanica","exam":"Tema 2","text":"Según el tema, ¿con qué frecuencia aproximada pueden disminuir y aumentar la presión de frenado los sistemas ABS habituales?","options":["Entre 12 y 15 veces por segundo.","Entre 15 y 18 veces por segundo.","Entre 30 y 40 veces por segundo."],"correct":1,"e":"Según el temario, el ABS modula la presión de frenado (la baja y la sube) entre 15 y 18 veces por segundo."},
  {"id":"MEC-T2-10","subject":"mecanica","exam":"Tema 2","text":"Si el dispositivo de control del ABS detecta una perturbación o anomalía en el sistema, ¿qué actuación se describe en el temario?","options":["Aumenta permanentemente la presión hidráulica de las cuatro ruedas.","Desconecta el ABS y activa su lámpara de advertencia.","Bloquea el circuito hidráulico principal para evitar que el vehículo circule."],"correct":1,"e":"Si el ABS detecta una avería, se desconecta y enciende su testigo. El coche sigue frenando con el freno normal, sin ABS."},
  {"id":"MEC-T2-11","subject":"mecanica","exam":"Tema 2","text":"Durante una frenada de emergencia en un vehículo equipado con ABS, ¿cómo debe actuar el conductor según el tema?","options":["Soltar el pedal en cuanto detecte que el ABS comienza a intervenir.","Bombear el pedal repetidamente para evitar el bloqueo.","Presionar el pedal de freno firmemente y mantenerlo presionado."],"correct":2,"e":"Con ABS hay que pisar a fondo y mantener el pedal: el sistema ya modula la presión. No hay que bombear el freno."},
  {"id":"MEC-T2-12","subject":"mecanica","exam":"Tema 2","text":"¿Qué componente permite al ABS conocer el régimen de giro individual de las ruedas?","options":["Los sensores de velocidad instalados en las ruedas.","El repartidor mecánico de frenada.","El sensor de presión del servofreno."],"correct":0,"e":"Los sensores de velocidad de cada rueda informan al ABS de cómo gira cada una."},
  {"id":"MEC-T2-13","subject":"mecanica","exam":"Tema 2","text":"¿Qué función cumple el embrague dentro del sistema de transmisión del vehículo?","options":["Modificar la relación de transmisión entre los engranajes de la caja de cambios.","Permitir el acoplamiento y desacoplamiento de la transmisión del movimiento entre el motor y la caja de cambios.","Distribuir el par motor entre las ruedas de un mismo eje."],"correct":1,"e":"El embrague acopla y desacopla el motor de la caja de cambios, para arrancar y cambiar de marcha."},
  {"id":"MEC-T2-14","subject":"mecanica","exam":"Tema 2","text":"¿Qué conjunto de tipos de embrague aparece recogido en la clasificación general del temario?","options":["De fricción, centrífugos e hidráulicos.","Sincronizados, epicicloidales y de toma constante.","Mecánicos, neumáticos y eléctricos exclusivamente."],"correct":0,"e":"Según el temario, los embragues se clasifican en de fricción, centrífugos e hidráulicos."},
  {"id":"MEC-T2-15","subject":"mecanica","exam":"Tema 2","text":"¿Qué elemento del embrague convencional ejerce la presión necesaria para aprisionar el disco entre el volante motor y la maza?","options":["El eje primario de la caja de cambios.","Los muelles helicoidales del mecanismo.","El cojinete de accionamiento por sí solo."],"correct":1,"e":"En el embrague convencional son los muelles helicoidales los que aprietan el disco entre el volante motor y la maza."},
  {"id":"MEC-T2-16","subject":"mecanica","exam":"Tema 2","text":"¿Qué función realizan los muelles dispuestos entre la zona de fricción y el núcleo del disco de embrague?","options":["Aumentar la presión hidráulica del circuito de accionamiento.","Transmitir el giro de manera elástica, amortiguando las brusquedades de la transmisión.","Mantener permanentemente separado el disco del volante motor."],"correct":1,"e":"Los muelles del disco transmiten el giro de forma elástica y amortiguan los tirones de la transmisión."},
  {"id":"MEC-T2-17","subject":"mecanica","exam":"Tema 2","text":"¿Qué elemento sustituye a los muelles helicoidales en un embrague de diafragma?","options":["Un mecanismo hidráulico situado en el interior del volante motor.","Un conjunto de piñones helicoidales sincronizados.","Un disco delgado de acero de forma cónica provisto de cortes radiales."],"correct":2,"e":"El embrague de diafragma sustituye los muelles helicoidales por un disco de acero cónico con cortes radiales."},
  {"id":"MEC-T2-18","subject":"mecanica","exam":"Tema 2","text":"¿Cuál de las siguientes NO es una ventaja atribuida en el temario al embrague de diafragma frente al convencional de muelles?","options":["Menor esfuerzo necesario para desembragar.","Mayor uniformidad en la presión aplicada sobre el plato.","Mayor complejidad constructiva y mayor dificultad de equilibrado."],"correct":2,"e":"La mayor complejidad no es una ventaja: el diafragma es más sencillo, más fácil de equilibrar, presiona de forma uniforme y necesita menos esfuerzo."},
  {"id":"MEC-T2-19","subject":"mecanica","exam":"Tema 2","text":"¿Qué consecuencia puede tener un acoplamiento excesivamente brusco del embrague al iniciar la marcha?","options":["Una reducción automática de la relación de transmisión.","La desconexión del eje secundario del diferencial.","El calado del motor al intentar vencer bruscamente la inercia del vehículo."],"correct":2,"e":"Si se suelta el embrague de golpe al arrancar, el motor no puede vencer la inercia del vehículo y se cala."},
  {"id":"MEC-T2-20","subject":"mecanica","exam":"Tema 2","text":"¿Por qué los forros del disco de embrague deben presentar elevada resistencia al desgaste y al calor?","options":["Porque son los encargados de refrigerar el aceite de la caja de cambios.","Porque deben transmitir el esfuerzo de rotación del motor mediante fricción sin resbalamientos indebidos.","Porque deben absorber la presión hidráulica procedente del sistema de frenos."],"correct":1,"e":"Los forros transmiten el giro del motor por fricción, por eso deben resistir el desgaste y el calor sin patinar."},
  {"id":"MEC-T2-21","subject":"mecanica","exam":"Tema 2","text":"¿Cuál es la finalidad principal de la caja de cambios en un vehículo?","options":["Adaptar el par y las revoluciones transmitidas a las ruedas a las necesidades de circulación.","Mantener constantes las revoluciones del motor y de las ruedas.","Eliminar las resistencias aerodinámicas y de rodadura."],"correct":0,"e":"La caja de cambios adapta el par y las revoluciones que llegan a las ruedas a lo que necesita cada momento de la marcha."},
  {"id":"MEC-T2-22","subject":"mecanica","exam":"Tema 2","text":"Según el documento, ¿qué elemento sustituye al embrague convencional en una caja de cambios automática tradicional?","options":["Un sincronizador de toma directa.","Un repartidor hidráulico de frenada.","Un convertidor de par."],"correct":2,"e":"En la caja automática tradicional el convertidor de par sustituye al embrague convencional."},
  {"id":"MEC-T2-23","subject":"mecanica","exam":"Tema 2","text":"¿Qué característica diferencia una caja de cambios manual pilotada de una automática convencional?","options":["La manual pilotada mantiene una construcción interna semejante a la manual, pero utiliza actuadores para accionar el embrague y seleccionar las marchas.","La manual pilotada carece de elementos de accionamiento del embrague.","La manual pilotada emplea obligatoriamente un convertidor de par."],"correct":0,"e":"La manual pilotada es por dentro como una manual, pero el embrague y los cambios los hacen actuadores."},
  {"id":"MEC-T2-24","subject":"mecanica","exam":"Tema 2","text":"En las cajas de cambios manuales de dos ejes descritas en el temario, ¿cuál es el recorrido de transmisión de movimiento?","options":["Eje primario, piñones seleccionados, eje secundario, diferencial y palieres.","Eje secundario, eje primario, embrague y ruedas.","Eje intermediario, eje terciario y árbol de transmisión."],"correct":0,"e":"En la caja de dos ejes el movimiento va del eje primario, por los piñones de la marcha elegida, al secundario, y de ahí al diferencial y a los palieres."},
  {"id":"MEC-T2-25","subject":"mecanica","exam":"Tema 2","text":"¿Por qué las cajas de cambios manuales de dos ejes suelen utilizarse en vehículos de tracción delantera?","options":["Porque necesitan alojar un eje intermediario longitudinal de grandes dimensiones.","Porque su construcción compacta permite compartir espacio con el motor e integrar el diferencial.","Porque transmiten el movimiento directamente al eje trasero sin necesidad de diferencial."],"correct":1,"e":"La caja de dos ejes es compacta e integra el diferencial, por eso cabe junto al motor en los coches de tracción delantera."},
  {"id":"MEC-T2-26","subject":"mecanica","exam":"Tema 2","text":"¿Qué disposición caracteriza a las cajas de cambios de toma constante de tres ejes descritas en el documento?","options":["Se emplean exclusivamente en vehículos de tracción delantera con motor transversal.","Se utilizan en vehículos de propulsión trasera, normalmente con motor longitudinal y caja alargada.","Carecen de eje intermediario y transmiten siempre el giro directamente al diferencial delantero."],"correct":1,"e":"Las cajas de tres ejes y toma constante se usan en propulsión trasera, normalmente con motor longitudinal y una caja alargada."},
  {"id":"MEC-T2-27","subject":"mecanica","exam":"Tema 2","text":"En una caja de cambios de tres ejes y toma constante, ¿qué característica presenta el conjunto formado por el eje primario y el intermediario?","options":["Existe un engranamiento permanente entre los piñones que transmiten el movimiento del primario al intermediario.","El eje intermediario solamente recibe movimiento cuando se acciona el sincronizador de la última velocidad.","Ambos ejes permanecen desacoplados hasta que se selecciona la marcha atrás."],"correct":0,"e":"En toma constante, los piñones del primario y del intermediario están siempre engranados."},
  {"id":"MEC-T2-28","subject":"mecanica","exam":"Tema 2","text":"En una caja de cambios de tres ejes, ¿qué sucede cuando se selecciona una velocidad de toma directa como la descrita en el temario?","options":["El eje primario queda unido directamente al terciario mediante un sincronizador.","El movimiento debe pasar obligatoriamente por todos los engranajes del eje intermediario.","El diferencial queda desacoplado y las ruedas giran libremente."],"correct":0,"e":"En la toma directa el sincronizador une el eje primario con el de salida y el giro pasa directamente, sin desmultiplicar."},
  {"id":"MEC-T2-29","subject":"mecanica","exam":"Tema 2","text":"¿Qué afirmación describe correctamente el funcionamiento de una caja manual pilotada?","options":["Necesita que el conductor accione físicamente el pedal del embrague en cada cambio.","Su funcionamiento exige que todas las relaciones de transmisión sean continuamente variables.","Puede disponer de un modo automático en el que los actuadores gestionan el embrague y la selección de marchas sin intervención del conductor."],"correct":2,"e":"La manual pilotada puede tener un modo automático en el que los actuadores manejan embrague y marchas sin que intervenga el conductor."},
  {"id":"MEC-T2-30","subject":"mecanica","exam":"Tema 2","text":"¿Cuál es la diferencia constructiva fundamental entre una caja manual pilotada y una caja automática convencional, según el documento?","options":["La manual pilotada utiliza necesariamente engranajes epicicloidales y la automática engranajes manuales.","Ambas son internamente idénticas y solo cambia la posición de la palanca.","La manual pilotada conserva una arquitectura interna de caja manual, mientras que la automática convencional presenta una construcción diferente."],"correct":2,"e":"La manual pilotada conserva el interior de una caja manual; la automática convencional tiene una construcción distinta (convertidor y engranajes epicicloidales)."},
  {"id":"ASI-T1-63","subject":"asise","exam":"Tema 1","text":"¿Qué debemos comprobar y asegurar fundamentalmente en el paso \"A\" (Airway) de la valoración primaria?","options":["Si el paciente realiza movimientos respiratorios voluntarios","Si la vía aérea está permeable y permite el libre paso de aire","Si el paciente presenta un pulso carotídeo central palpable","El nivel exacto de consciencia mediante la escala de Glasgow"],"correct":1,"e":"En la A (Airway) se comprueba que la vía aérea está permeable y deja pasar el aire. La respiración se valora en la B y el pulso en la C."},
  {"id":"ASI-T1-64","subject":"asise","exam":"Tema 1","text":"¿Cuál es el principal problema que obstruye la vía aérea en un paciente adulto que se encuentra inconsciente en decúbito supino?","options":["La presencia continuada de convulsiones tónico-clónicas","La contracción espasmódica e involuntaria de la glotis","Que la lengua se relaja, cae hacia atrás y bloquea la faringe","El descenso brusco de la frecuencia cardíaca basal"],"correct":2,"e":"En el paciente inconsciente boca arriba la lengua pierde tono, cae hacia atrás y bloquea la faringe."},
  {"id":"ASI-T1-65","subject":"asise","exam":"Tema 1","text":"¿Qué método de apertura de la vía aérea está formalmente contraindicado si sospechamos que el paciente ha sufrido un traumatismo cervical?","options":["La maniobra frente-mentón","La técnica de tracción mandibular","La retirada manual de cuerpos extraños visibles","La colocación en posición lateral de seguridad"],"correct":0,"e":"Si se sospecha lesión cervical está contraindicada la maniobra frente-mentón, porque extiende el cuello. Se usa la tracción mandibular."},
  {"id":"ASI-T1-66","subject":"asise","exam":"Tema 1","text":"¿Cuál es el rango normal de la Frecuencia Respiratoria (eupnea) en un adulto sano en situación de reposo?","options":["Entre 5 y 10 respiraciones por minuto","Entre 12 y 20 respiraciones por minuto","Entre 25 y 40 respiraciones por minuto","Entre 40 y 60 respiraciones por minuto"],"correct":1,"e":"La frecuencia respiratoria normal (eupnea) de un adulto en reposo es de 12 a 20 respiraciones por minuto."},
  {"id":"ASI-T1-67","subject":"asise","exam":"Tema 1","text":"¿Qué parámetro fisiológico mide de forma no invasiva el pulsioxímetro de pulso en la valoración respiratoria?","options":["La concentración total de dióxido de carbono (CO2) espirado","La presión parcial exacta de oxígeno disuelto en plasma (PaO2)","El porcentaje de hemoglobina saturada con oxígeno (SpO2) y la frecuencia cardiaca","La frecuencia respiratoria exacta por minuto"],"correct":2,"e":"El pulsioxímetro mide sin pinchar el porcentaje de hemoglobina saturada de oxígeno (SpO2) y la frecuencia cardíaca."},
  {"id":"ASI-T1-68","subject":"asise","exam":"Tema 1","text":"¿Qué rango de saturación de oxígeno (SpO2) se considera dentro de la normalidad (normoxia) en un paciente sin patología respiratoria previa?","options":["Entre el 95% y el 100%","Entre el 90% y el 94%","Entre el 85% y el 89%","Siempre por debajo del 85%"],"correct":0,"e":"En una persona sin enfermedad respiratoria, la saturación normal está entre el 95 y el 100%."},
  {"id":"ASI-T1-69","subject":"asise","exam":"Tema 1","text":"¿Cuál es el valor normal de la Frecuencia Cardíaca (normocardia) en un adulto en reposo?","options":["De 30 a 60 latidos por minuto","De 60 a 100 latidos por minuto","De 80 a 120 latidos por minuto","De 100 a 140 latidos por minuto"],"correct":1,"e":"La frecuencia cardíaca normal de un adulto en reposo es de 60 a 100 latidos por minuto."},
  {"id":"ASI-T1-70","subject":"asise","exam":"Tema 1","text":"¿Qué indica clínicamente un tiempo de rellenado capilar superior a 2 segundos al presionar el lecho ungueal?","options":["Una excelente perfusión tisular periférica","Un estado de presión arterial sistólica elevada","Una deficiencia o mala perfusión en la circulación periférica","Una situación de hipertermia corporal grave"],"correct":2,"e":"Un relleno capilar de más de 2 segundos indica que la sangre no llega bien a la periferia: hay mala perfusión."},
  {"id":"ASI-T1-71","subject":"asise","exam":"Tema 1","text":"¿A qué se denomina Presión Arterial Sistólica (PAS) o máxima?","options":["A la presión ejercida sobre las paredes arteriales cuando los ventrículos se relajan","A la presión registrada únicamente durante la fase de sueño profundo","A la presión máxima generada cuando el corazón se contrae e impulsa la sangre","Al volumen total de sangre circulante contenido en las grandes venas cavas"],"correct":2,"e":"La presión sistólica o máxima es la que genera el corazón al contraerse e impulsar la sangre."},
  {"id":"ASI-T1-72","subject":"asise","exam":"Tema 1","text":"¿Cuáles son los valores considerados como normales de Presión Arterial Sistólica en un adulto sano en reposo?","options":["De 60 a 90 mmHg","De 80 a 120 mmHg","De 140 a 180 mmHg","De 100 a 130 mmHg"],"correct":3,"e":"Según el PDF corregido del curso, la sistólica normal en un adulto en reposo está entre 100 y 130 mmHg."},
  {"id":"ASI-T1-73","subject":"asise","exam":"Tema 1","text":"Respecto a la escala AVDN de valoración cualitativa del nivel de consciencia, ¿qué letra se le asigna a un paciente que únicamente responde o reacciona ante estímulos dolorosos intensos?","options":["La letra A","La letra V","La letra D","La letra N"],"correct":2,"e":"La D de AVDN es de Dolor: solo responde a estímulos dolorosos intensos."},
  {"id":"ASI-T1-74","subject":"asise","exam":"Tema 1","text":"¿Qué tres parámetros evalúa cuantitativamente la Escala de Coma de Glasgow (GCS)?","options":["La respuesta motora, la respuesta verbal y la respuesta ocular","La reactividad pupilar, la frecuencia respiratoria y el pulso periférico","El nivel de atención, la orientación espacial y la respuesta al dolor","El reflejo fotomotor, la fuerza muscular y la capacidad de deglución"],"correct":0,"e":"La escala de Glasgow valora la respuesta motora, la verbal y la ocular."},
  {"id":"ASI-T1-75","subject":"asise","exam":"Tema 1","text":"¿Cuál es la puntuación MÍNIMA que puede obtener un paciente al ser evaluado mediante la Escala de Coma de Glasgow?","options":["0 puntos","1 punto","3 puntos","5 puntos"],"correct":2,"e":"La puntuación mínima de Glasgow es 3, porque cada apartado puntúa como mínimo 1."},
  {"id":"ASI-T1-76","subject":"asise","exam":"Tema 1","text":"¿Qué hallazgo clínico observamos al explorar las pupilas si una de ellas se encuentra más dilatada que la otra?","options":["Miosis bilateral","Midriasis simétrica","Anisocoria","Isocoria normorreactiva"],"correct":2,"e":"Si una pupila está más dilatada que la otra hay anisocoria."},
  {"id":"ASI-T1-77","subject":"asise","exam":"Tema 1","text":"¿Cuáles son las características clínicas típicas del dolor torácico originado por una cardiopatía isquémica aguda?","options":["Dolor punzante que aumenta de forma clara al presionar las costillas y al respirar","Dolor de tipo opresivo, retroesternal, inmodificable con los movimientos y que puede irradiar a la mandíbula o brazo izquierdo","Dolor de carácter pleurítico que empeora notablemente al toser y cursa con fiebre alta","Dolor urente localizado en epigastrio que empeora al tumbarse tras haber comido"],"correct":1,"e":"El dolor de la cardiopatía isquémica es opresivo, retroesternal, no cambia con los movimientos y puede irradiarse a la mandíbula o al brazo izquierdo."},
  {"id":"DOT-T1-56","subject":"dotacion","exam":"Tema 1","text":"¿Cuál de las siguientes afirmaciones sobre el transporte sanitario es INCORRECTA?","options":["Puede realizarse de forma individual o colectiva.","Puede efectuarse mediante vehículos terrestres, aéreos o marítimos.","Todos los vehículos de transporte sanitario deben estar preparados para prestar asistencia sanitaria avanzada.","Su finalidad es trasladar personas por razones sanitarias."],"correct":2,"e":"Es falsa la C: solo las ambulancias de clase C están preparadas para asistencia avanzada; las A ni siquiera son asistenciales."},
  {"id":"DOT-T1-57","subject":"dotacion","exam":"Tema 1","text":"Un paciente es trasladado desde un hospital comarcal a otro hospital que dispone de una unidad especializada. ¿Cómo se clasifica este transporte según su origen y destino?","options":["Transporte secundario.","Transporte terciario.","Transporte primario.","Transporte demorable."],"correct":0,"e":"Trasladar a un paciente entre dos hospitales es transporte secundario."},
  {"id":"DOT-T1-58","subject":"dotacion","exam":"Tema 1","text":"Un paciente presenta una patología grave y necesita vigilancia y cuidados sanitarios durante el traslado, pero su situación clínica permanece estable. ¿Cómo se clasifica?","options":["Paciente no grave programado.","Paciente crítico inestable.","Paciente no grave.","Paciente grave no crítico."],"correct":3,"e":"Es un paciente grave no crítico: necesita vigilancia y cuidados, pero está estable."},
  {"id":"DOT-T1-59","subject":"dotacion","exam":"Tema 1","text":"¿Cuál de las siguientes situaciones corresponde a un transporte sanitario de emergencia?","options":["Traslado programado para una sesión de rehabilitación.","Traslado inmediato de un paciente con compromiso vital.","Traslado de un paciente estable para una prueba diagnóstica.","Traslado no urgente entre dos hospitales."],"correct":1,"e":"El transporte de emergencia es el traslado inmediato de un paciente con compromiso vital."},
  {"id":"DOT-T1-60","subject":"dotacion","exam":"Tema 1","text":"¿Qué ambulancia resulta más adecuada para trasladar a varios pacientes que pueden viajar sentados y no necesitan asistencia sanitaria durante el trayecto?","options":["Ambulancia clase A1.","Ambulancia clase B.","Ambulancia clase C.","Ambulancia clase A2."],"correct":3,"e":"La A2 es la ambulancia de transporte colectivo, para varios pacientes sentados que no necesitan asistencia."},
  {"id":"DOT-T1-61","subject":"dotacion","exam":"Tema 1","text":"Según el RD 836/2012, ¿qué dotación mínima de personal corresponde a una ambulancia de clase B?","options":["Un conductor con certificado profesional y un ayudante.","Un conductor TES y otro profesional con la misma titulación.","Un conductor TES y un profesional de enfermería.","Un conductor TES y un médico."],"correct":1,"e":"La ambulancia B lleva como mínimo un conductor TES y otro TES."},
  {"id":"DOT-T1-62","subject":"dotacion","exam":"Tema 1","text":"¿Cuál de las siguientes afirmaciones sobre los Vehículos de Intervención Rápida (VIR) es correcta?","options":["Permiten prestar asistencia sanitaria en el lugar, pero no están destinados a trasladar pacientes.","Se utilizan principalmente para el transporte colectivo programado.","Disponen obligatoriamente de una camilla para trasladar pacientes.","Sustituyen a las ambulancias de SVA durante el transporte hospitalario."],"correct":0,"e":"El VIR permite asistir al paciente en el lugar, pero no lo transporta."},
  {"id":"DOT-T1-63","subject":"dotacion","exam":"Tema 1","text":"¿Qué característica distingue principalmente el habitáculo de las ambulancias asistenciales B y C del de las ambulancias no asistenciales?","options":["Disponer de sistemas de climatización.","Tener superficies lavables y desinfectables.","Permitir la prestación de asistencia sanitaria durante el traslado.","Disponer de puertas para introducir y extraer al paciente."],"correct":2,"e":"El habitáculo de B y C está preparado para atender al paciente durante el traslado; climatización, superficies lavables y puertas las tienen todas."},
  {"id":"DOT-T1-64","subject":"dotacion","exam":"Tema 1","text":"¿Cuál de las siguientes características corresponde a la bancada de las ambulancias asistenciales B y C?","options":["Está diseñada exclusivamente para fijar la camilla, sin permitir movimientos.","Permite el posicionamiento del paciente y el desplazamiento lateral de la camilla.","Se utiliza principalmente para sujetar sillas de ruedas.","Sustituye los cinturones de seguridad de la camilla."],"correct":1,"e":"La bancada de B y C permite colocar al paciente en distintas posiciones y desplazar la camilla lateralmente."},
  {"id":"DOT-T1-65","subject":"dotacion","exam":"Tema 1","text":"Una ambulancia A2 transporta a un paciente sentado en su silla de ruedas. ¿Qué medida de seguridad debe adoptarse?","options":["Activar los frenos de la silla sin utilizar otros sistemas.","Sujetar al paciente con el cinturón de la propia silla.","Colocar la silla entre dos asientos para evitar desplazamientos.","Fijar la silla al vehículo y utilizar un sistema de retención para el ocupante."],"correct":3,"e":"La silla de ruedas debe ir anclada al vehículo y el ocupante sujeto con su propio sistema de retención."},
  {"id":"DOT-T1-66","subject":"dotacion","exam":"Tema 1","text":"¿Qué elemento del equipamiento permite diferenciar una ambulancia de SVA de una ambulancia de SVB?","options":["Un respirador mecánico.","Un balón autoinflable de ventilación.","Un juego de collarines cervicales.","Un equipo de aspiración de secreciones."],"correct":0,"e":"El respirador mecánico solo está en las ambulancias de SVA. Ambú, collarines y aspirador los llevan también las de SVB."},
  {"id":"DOT-T1-67","subject":"dotacion","exam":"Tema 1","text":"¿Qué material puede encontrarse en una ambulancia de SVB para facilitar la inmovilización de un paciente traumatizado?","options":["Bombas de perfusión y calentador de sueros.","Laringoscopio y tubos endotraqueales.","Camilla de cuchara, colchón de vacío y collarines cervicales.","Catéteres venosos centrales y monitor multiparamétrico."],"correct":2,"e":"Para inmovilizar a un traumatizado, la ambulancia SVB lleva camilla de cuchara, colchón de vacío y collarines. Las demás opciones son material de SVA."},
  {"id":"DOT-T1-68","subject":"dotacion","exam":"Tema 1","text":"¿Qué dotación de oxígeno fijo hemos estudiado para las ambulancias asistenciales de clase C?","options":["Una botella fija de 2.000 litros.","Dos botellas fijas de 2.000 litros cada una y otra portátil de 400 litros.","Dos botellas fijas de 400 litros cada una.","Una botella fija de 4.000 litros y otra portátil de 200 litros."],"correct":1,"e":"La ambulancia C lleva dos botellas fijas de 2.000 litros cada una y una portátil de 400 litros."},
  {"id":"DOT-T1-69","subject":"dotacion","exam":"Tema 1","text":"¿Cuál de las siguientes afirmaciones sobre el equipamiento de las ambulancias de clase B es correcta?","options":["No pueden transportar material para accesos venosos periféricos.","Deben disponer de un respirador mecánico para ventilación invasiva.","Están destinadas a realizar técnicas invasivas de soporte vital avanzado.","Pueden disponer de material para accesos venosos, que solo se podrá usar si hay personal habilitado."],"correct":3,"e":"La B puede llevar material para accesos venosos, pero solo puede usarlo personal habilitado para ello (enfermería o medicina)."},
  {"id":"DOT-T1-70","subject":"dotacion","exam":"Tema 1","text":"¿Qué característica es propia de las ambulancias de clase C en relación con el tratamiento del paciente crítico?","options":["Pueden disponer de bombas de perfusión, calentador de sueros y frigorífico para medicamentos termolábiles.","Su equipamiento se limita a oxigenoterapia y material básico de curas.","Su habitáculo está diseñado principalmente para transportar varios pacientes sentados.","No necesitan disponer de monitorización avanzada durante el traslado."],"correct":0,"e":"La ambulancia C puede llevar bombas de perfusión, calentador de sueros y frigorífico para atender al paciente crítico."}
];
